    public void closed(){
        if (!shutdown) {
            connectService.removeConnect(this);
            List list = new ArrayList(clients);
            for (int i = 0; i < list.size(); i++) {
                Integer id = (Integer) list.get(i);
                WorldPlayer player = playerService.getWorldPlayer(id.intValue());
                unRegistry(player);
                player.reset();
                playerService.savePlayer(player);
                try {
					playerService.toDbPetPracticeTime(player);
					log.info("ID[" + player.getId() + "] PlayerName[" + player.getPlayerName() + "] toDbPetPracticeTime Saved");
				} catch (BuyException e) {
					log.info("ID[" + player.getId() + "] PlayerName[" + player.getPlayerName() + "] toDbPetPracticeTime Error");
					e.printStackTrace();
				}
                log.info(player.getPlayerName() + "saved");
            }
            list.clear();
            log.info(name + "closed");
        }
    }

