    /**
     * 百层爬塔相关协议
     * @param data
     */
    private void hundredFloorTower(UWAPData data) throws Exception  {
    	WorldPlayer player = getPlayer(data.getSessionId());
		if (player != null) {
			synchronized (player) {
				//协议类型
				int type = data.readInt();
				switch (type) {
				case 0://登陆请求
					loginInTower(data, player);
					break;
				case 1://确定花钱爬百层
					useMoneyInTower(data, player);
					break;
//				case 2://使用自动爬百层药水
//					useItemInTower(data, player);
//					break;
				default:
					break;
				}
			}
		}
	}

//    private void useItemInTower(UWAPData data, WorldPlayer player) {
//		
//	}

	/**
     * 花钱爬塔
     * @param data
     * @param player
     */
    private void useMoneyInTower(UWAPData data, WorldPlayer player) throws Exception {
    	int itemBuyID = 201610;
    	log.info("Tower:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] send buy try");
		if (iShopHide(player, itemBuyID, data.getSerial(), data.getSessionId(),
				1, (byte) 13, -1, 0) != ISHOP_OK) {
			log.info("Tower:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] not have enough money");
//		log.info("花钱开宝箱:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] 余额不足");
			String resultsStr = "亲，您的余额不足，本次购买不成功，请及时充值。";
			throw new ITimesException(resultsStr, data.getSerial(),
					data.getSessionId(), (byte) 36);
		}
	}

	private void loginInTower(UWAPData data, WorldPlayer player) {
//		if(player.getBossRushStage() == null){}
		
    	UWAPSegment seg = new UWAPSegment(
    			ClientConstants.EXTEND_PROTOCOL, data.getSerial(),
    			data.getSessionId());
    	seg.writeShort(ClientConstants.EXTEND_HUNDRED_FLOOR_TOWER);
    	seg.writeInt(0);
    	seg.writeInt(BossRush.getMaxStage());
    	seg.writeInt(player.getBossRushStage());
    	write(seg);
    }
    
    /**
     * 通知玩家需要购买道具
     * @param data
     * @param player
     */
    private void sendTowerNeedBuyMessage(Command data, WorldPlayer player) {
    	UWAPSegment seg = new UWAPSegment(
    			ClientConstants.EXTEND_PROTOCOL, data.getSerial(),
    			data.getSessionId());
    	seg.writeShort(ClientConstants.EXTEND_HUNDRED_FLOOR_TOWER);
    	seg.writeInt(1);
    	write(seg);
    }

	/**
     * 花钱开宝箱相关协议
     * @param data
     * @throws Exception
     */
    private void awardBox(UWAPData data) throws Exception {
    	WorldPlayer player = getPlayer(data.getSessionId());
    /*	Calendar calendar = Calendar.getInstance();
		calendar.set(2013, 0,1,0,0,0);
		
		long start = calendar.getTimeInMillis();
		calendar.set(2013,3,12,24,0,0);
		long end = calendar.getTimeInMillis();*/
		if (player != null) {
			synchronized (player) {
				//协议类型
				int type = data.readInt();
				switch (type) {
				case 0://登陆请求
					loginInAwardBoxSystem(data, player);
					break;
				case 1:// 花钱开宝箱请求
				
					if(System.currentTimeMillis()> NoahsarkConfig.getStartDate().getTime()){
						IItem iit = Items.getTemplate(580014).newInstance();
						if(!player.hasItem(580014)){
							openBoxByMoney(data, player, false);
						}else{
							openBoxByTicket(data,player,false);
						}				
						
						
					}else {
						openBoxByMoney(data, player, false);
					}
					//openBoxByMoney(data, player, false);
					break;
				case 2://发奖请求
					sendPrizeItem(data, player);
					break;
				case 3:		
					if(System.currentTimeMillis()> NoahsarkConfig.getStartDate().getTime()){
						IItem iit = Items.getTemplate(580014).newInstance();
						if(!player.hasItem(580014)){
							openBoxByMoney(data, player, true);
						}else{
							openBoxByTicket(data,player,true);
						}				
						
						
					}else {
						openBoxByMoney(data, player, true);
					}
					//openBoxByMoney(data, player, false);
					break;
				case 4:
					sendPrizeItemWhenExit(data, player);
				default:
					break;
				}
			}
		}
	}

    /**
     * 接到退出请求后将未发奖的奖品发给玩家
     * @param data
     * @param player
     */
    private void sendPrizeItemWhenExit(UWAPData data, WorldPlayer player) {
    	log.info("AwardBox:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] exit");
		//检查是否有宝箱没给，给宝箱
		if (player.getAwardBoxItemId() != 0) {
			int itemId = player.getAwardBoxItemId();
			player.setAwardBoxItemId(0);
			log.info("AwardBox:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] exit with email get itemId[" + itemId + "]");
//			log.info("花钱开宝箱:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] 登陆时获得 itemId[" + player.getAwardBoxItemId() + "]");
			chatService.sendPrivateMessage(-1,"系统",player.getId(),
					"您有未领取的奥德赛之旅开奖物品，系统以邮件方式发送到您的邮箱，请及时查收。");
			IItem item = Items.getTemplate(itemId).newInstance();
			byte[] att = ItemUtils.item2dbAttachment(item, 1);
			mailService.sendMail(player.getId(), player.getPlayerName(), -1, "系统",
					"奥德赛之旅未领取物品", "您有未成功领取的奥德赛之旅开奖物品，系统以附件方式发送给您，请及时查收", att, 0, true);
		}
		
		if (player.getAwardBoxItemIdArray() != null) {
			int[] itemId = new int[10];
			itemId = player.getAwardBoxItemIdArray();
			if(itemId[0] != 0){
				player.resetAwardBoxItemIdArrayAfterGivePrize();
				chatService.sendPrivateMessage(-1,"系统",player.getId(),
						"您有未领取的奥德赛之旅开奖物品，系统以邮件方式发送到您的邮箱，请及时查收。");
				for(int index = 0; index < itemId.length; index++){
					log.info("AwardBox:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] exit with email get itemIdArray [" + itemId + "]");
//			log.info("花钱开宝箱:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] 登陆时获得 itemId[" + player.getAwardBoxItemId() + "]");
					IItem item = Items.getTemplate(itemId[index]).newInstance();
					byte[] att = ItemUtils.item2dbAttachment(item, 1);
					mailService.sendMail(player.getId(), player.getPlayerName(), -1, "系统",
							"奥德赛之旅未领取物品", "您有未成功领取的奥德赛之旅开奖物品，系统以附件方式发送给您，请及时查收", att, 0, true);
				}
			}
		}
	}

	/**
     * 接到发奖请求后将奖品发给玩家
     * @param data
     * @param player
     */
    private void sendPrizeItem(UWAPData data, WorldPlayer player) throws Exception{
    	int itemIndex = data.readInt();

		if (player.getAwardBoxItemId() != 0) {
			int resultItemId = player.getAwardBoxItemId();
			player.setAwardBoxItemId(0);
			Changed changed = new Changed();
			IItem item = Items.getTemplate(resultItemId).newInstance();
			
			log.info("AwardBox:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] get prizeItem ItemID["
					+ resultItemId + "]");

			if (player.completeAddItem(item, 1, changed,
					player.getClientDataVersion()) == null) {
				byte[] att = ItemUtils.item2dbAttachment(item, 1);
				mailService.sendMail(player.getId(), player.getPlayerName(),
						-1, "系统", "奥德赛之旅开奖物品背包满邮件", "你的背包满了，奥德赛之旅开奖物品邮寄到您的邮箱。", att, 0, true);
				sendMessage(player.getId(), "你的背包满了，已经把奥德赛之旅开奖物品邮寄到您的邮箱!");
				log.info("AwardBox:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] bag is full.Send mail with ItemID["
						+ resultItemId + "]");

			}
			
			String item_msg = Items.getMessage(resultItemId, 10, player.getPlayerName(), item.getName(), "奥德赛之旅");
    		if (item_msg != null){
    				chatService.sendWorldMessage(-1, "系统", item_msg);
    		}

			sendGetItem(changed, data.getSerial(), data.getSessionId(), (byte)0);
			
			UWAPSegment seg = new UWAPSegment(
					ClientConstants.EXTEND_PROTOCOL, data.getSerial(),
					data.getSessionId());
			seg.writeShort(ClientConstants.EXTEND_AWARD_BOX);
			seg.writeInt(2);
//			seg.writeString(AwardBoxConfig.getShowMessageByIndex(itemIndex));
			write(seg);
		}else if(player.getAwardBoxItemIdArray() != null){
			int[] resultItemId = new int[10];
			resultItemId = player.getAwardBoxItemIdArray();
			if(resultItemId[0] != 0){	
				player.resetAwardBoxItemIdArrayAfterGivePrize();
				Changed changed = new Changed();
				boolean isShowMessage = false;
				for(int index = 0; index < resultItemId.length; index++){
					IItem item = Items.getTemplate(resultItemId[index]).newInstance();
					
					log.info("AwardBox:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] get ItemID in prizeItemArray ["
							+ resultItemId + "]");
					
					if (player.completeAddItem(item, 1, changed,
							player.getClientDataVersion()) == null) {
						byte[] att = ItemUtils.item2dbAttachment(item, 1);
						mailService.sendMail(player.getId(), player.getPlayerName(),
								-1, "系统", "奥德赛之旅开奖物品背包满邮件", "你的背包满了，奥德赛之旅开奖物品邮寄到您的邮箱。", att, 0, true);
						if(!isShowMessage){
							isShowMessage = true;
							sendMessage(player.getId(), "你的背包满了，已经把奥德赛之旅开奖物品邮寄到您的邮箱!");
						}
						log.info("AwardBox:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] bag is full.Send mail with ItemID["
								+ resultItemId + "]");
						
					}
					
					String item_msg = Items.getMessage(resultItemId[index], 10, player.getPlayerName(), item.getName(), "奥德赛之旅");
					if (item_msg != null){
						chatService.sendWorldMessage(-1, "系统", item_msg);
					}
				}
				
				sendGetItem(changed, data.getSerial(), data.getSessionId(), (byte)0);
				
				UWAPSegment seg = new UWAPSegment(
						ClientConstants.EXTEND_PROTOCOL, data.getSerial(),
						data.getSessionId());
				seg.writeShort(ClientConstants.EXTEND_AWARD_BOX);
				seg.writeInt(2);
//			seg.writeString(AwardBoxConfig.getShowMessageByIndex(itemIndex));
				write(seg);
			}
		}else{
			String resultsStr = "您未获得奖品。";
			log.info("AwardBox:ID[" + player.getId() + "] Client itemIndex["
					+ itemIndex + "] Service itemId[" + player.getAwardBoxItemId()
					+ "] get prize fail!");
			throw new ITimesException(resultsStr, data.getSerial(),
					data.getSessionId(), (byte) 36);
		}
	}

	/**
     * 花钱开宝箱
     * @param data
     * @param player
	 * @param isBuyTen 
     */
	private void openBoxByMoney(UWAPData data, WorldPlayer player, boolean isBuyTen)
			throws Exception {
		int itemBuyID = 201645;// 隐藏道具
		int itemBuyMoney = 180;// 隐藏道具价格
		
		
		int itemBuyCount = AwardBoxConfig.getPrice() / itemBuyMoney ;
		if(isBuyTen == true){
			//一次开十个
			itemBuyCount = itemBuyCount * 10;
		}
		
		if(itemBuyCount <= 0){
			String resultsStr = "系统购买异常。";
			log.info("AwardBox:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] itemBuyCount[" + itemBuyCount + "] exception");
			throw new ITimesException(resultsStr, data.getSerial(),
					data.getSessionId(), (byte) 36);
		}
		
		// 检查其otherPool是否为空，此处是为了防止其连续点击
		if(isBuyTen == true && player.getAwardBoxItemIdArray() != null){
			if (player.getAwardBoxItemIdArray()[0] != 0) {
				String resultsStr = "亲，您前一次奥德赛之旅的开奖物品还未领取，本次不能开奖。";
				int[] items = player.getAwardBoxItemIdArray();
				String logStr = new String();
				if(items != null && items.length > 0){
		    		for(int i =0; i < items.length; i++){
		    			logStr += "itemId" + i +"[" + items[i] + "]";
		    		}
		    	}
				log.info("AwardBox:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] not get awardBoxItemArray " + logStr);
				throw new ITimesException(resultsStr, data.getSerial(),
						data.getSessionId(), (byte) 36);
			}
		}else{
			if (player.getAwardBoxItemId() != 0) {
				String resultsStr = "亲，您前一次奥德赛之旅的开奖物品还未领取，本次不能开奖。";
				log.info("AwardBox:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] not get awardBoxItem[" + player.getAwardBoxItemId() + "]");
				throw new ITimesException(resultsStr, data.getSerial(),
						data.getSessionId(), (byte) 36);
			}
		}
		
		// 检查是否关闭了系统，以防临时有问题，开关在awardBox.xml里配置
		if(AwardBoxConfig.getIsSystemOpen() != 1){
			String resultsStr = "对不起，当前系统已被关闭，您的操作无效，请退出此系统。";
			throw new ITimesException(resultsStr, data.getSerial(),
					data.getSessionId(), (byte) 36);
		}
		
		if(Server.iMoneyType == Server.IMONEY_TYPE_CMCC){
			if(player.hasItem(itemBuyID, itemBuyCount)){
				Changed changed = new Changed();
				log.info("AwardBox:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] removeItem count[" + itemBuyCount + "] try");
				if(player.completeRemoveItem(itemBuyID, itemBuyCount, changed) != null){
					log.info("AwardBox:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] removeItem count[" + itemBuyCount + "] succeed");
					if(isBuyTen){
						int[] resultIndex = AwardBoxConfig.getBoxResultIndexArray(player);
                		UWAPSegment segment = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
                		segment.writeShort(ClientConstants.EXTEND_AWARD_BOX);
                		segment.writeInt(3);
                		segment.writeInts(resultIndex);
                		write(segment);
					}else{
						int resultIndex = AwardBoxConfig.getBoxResultIndex(player);
						UWAPSegment segment = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
						segment.writeShort(ClientConstants.EXTEND_AWARD_BOX);
						segment.writeInt(1);
						segment.writeInt(resultIndex);
						write(segment);
					}
					sendGetItem(changed, data.getSerial(), data.getSessionId(), (byte)20);
				}else{
					log.info("AwardBox:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] removeItem count[" + itemBuyCount + "] fail");
					IItemTemplate item = Items.getTemplate(itemBuyID);
					throw new ITimesException("无法扣除" + item.getName() + "!", data.getSerial(),
							data.getSessionId(), (byte) 36);	
				}
			}else{
				IItemTemplate item = Items.getTemplate(itemBuyID);
				throw new ITimesException("您没有足够的" + item.getName() + "!", data.getSerial(),
						data.getSessionId(), (byte) 36);
			}
		}else{
			// 检查其余额是否足够
			if(isBuyTen == true){
				log.info("AwardBox:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] send buy ten try");
				if (iShopHide(player, itemBuyID, data.getSerial(), data.getSessionId(),
						itemBuyCount, (byte) 12, -1, 0) != ISHOP_OK) {
					log.info("AwardBox:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] not have enough money");
	//			log.info("花钱开宝箱:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] 余额不足");
					String resultsStr = "亲，您的余额不足，本次不能开奖，请及时充值。";
					throw new ITimesException(resultsStr, data.getSerial(),
							data.getSessionId(), (byte) 36);
				}
			}else{
				log.info("AwardBox:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] send buy try");
				if (iShopHide(player, itemBuyID, data.getSerial(), data.getSessionId(),
						itemBuyCount, (byte) 11, -1, 0) != ISHOP_OK) {
					log.info("AwardBox:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] not have enough money");
	//			log.info("花钱开宝箱:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] 余额不足");
					String resultsStr = "亲，您的余额不足，本次不能开奖，请及时充值。";
					throw new ITimesException(resultsStr, data.getSerial(),
							data.getSessionId(), (byte) 36);
				}
			}
		}
	}
	
