	/**
     * 登陆花钱开宝箱系统
     * @param player
     */
	public void loginInAwardBoxSystem(UWAPData data, WorldPlayer player) {
		log.info("AwardBox:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] login in");
		//检查是否有宝箱没给，给宝箱，此时要确保玩家不能进入界面不能按转宝箱
		if (player.getAwardBoxItemId() != 0) {
			int itemId = player.getAwardBoxItemId();
			player.setAwardBoxItemId(0);
			log.info("AwardBox:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] login with email get itemId[" + itemId + "]");
//			log.info("花钱开宝箱:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] 登陆时获得 itemId[" + player.getAwardBoxItemId() + "]");
			chatService.sendPrivateMessage(-1,"系统",player.getId(),
					"您有未领取的奥德赛之旅开奖物品，系统以邮件方式发送到您的邮箱，请及时查收。");
			IItem item = Items.getTemplate(itemId).newInstance();
			byte[] att = ItemUtils.item2dbAttachment(item, 1);
			mailService.sendMail(player.getId(), player.getPlayerName(), -1, "系统",
					"奥德赛之旅未领取物品", "您有未成功领取的奥德赛之旅开奖物品，系统以附件方式发送给您，请及时查收", att, 0, true);
		}
		
		if (player.getAwardBoxItemIdArray() != null) {
			int[] itemId = new int[10];
			itemId = player.getAwardBoxItemIdArray();
			if(itemId[0] != 0){
				player.resetAwardBoxItemIdArrayAfterGivePrize();
				chatService.sendPrivateMessage(-1,"系统",player.getId(),
						"您有未领取的奥德赛之旅开奖物品，系统以邮件方式发送到您的邮箱，请及时查收。");
				for(int index = 0; index < itemId.length; index++){
					log.info("AwardBox:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] login with email get itemIdArray [" + itemId + "]");
//			log.info("花钱开宝箱:ID[" + player.getId() + "] name[" + player.getPlayerName() + "] 登陆时获得 itemId[" + player.getAwardBoxItemId() + "]");
					IItem item = Items.getTemplate(itemId[index]).newInstance();
					byte[] att = ItemUtils.item2dbAttachment(item, 1);
					mailService.sendMail(player.getId(), player.getPlayerName(), -1, "系统",
							"奥德赛之旅未领取物品", "您有未成功领取的奥德赛之旅开奖物品，系统以附件方式发送给您，请及时查收", att, 0, true);
				}
			}
		}
		
		UWAPSegment seg = new UWAPSegment(
				ClientConstants.EXTEND_PROTOCOL, data.getSerial(),
				data.getSessionId());
		seg.writeShort(ClientConstants.EXTEND_AWARD_BOX);
		seg.writeInt(0);
		seg.writeInt(AwardBoxConfig.getIsSystemOpen());
		seg.writeInt(AwardBoxConfig.getMoneyType());
		seg.writeInt(AwardBoxConfig.getPrice());
		seg.writeStrings(AwardBoxConfig.getDescribes(player));
		seg.writeInts(AwardBoxConfig.getElemIndex());
		seg.writeInts(AwardBoxConfig.getElemBackIndex());
		write(seg);
	}
	
	/**
     * 兔子赛跑相关协议处理
     * @param data
     */
	private void rabbitRace(UWAPData data) throws Exception {
		WorldPlayer player = getPlayer(data.getSessionId());
		if (player != null) {
			int type = data.readInt();
			int nowState = RabbitRaceConfig.getNowState();
			if (type == 0) {
				// 登陆赛跑系统,注册用户进入Map
				if (RabbitRaceConfig.isRegisterPalyer()) {
					// RabbitRacePlayerData playerData = new
					// RabbitRacePlayerData(player.getId(),player.getPlayerName());
					// resetJettonNums();
					// RabbitRaceConfig.isResetPlayerJettonNums(playerData);
					RabbitRaceConfig.setPlayerInHashMap(player);
				}
				// int clintTime = data.readInt();
				int[] nums = { 0, 0, 0, 0, 0 };
				if (RabbitRaceConfig.playerJettonHashMap.containsKey(player
						.getId())) {
					RabbitRacePlayerData racePlayerData = RabbitRaceConfig.playerJettonHashMap
							.get(player.getId());
					nums = racePlayerData.getJettonNums();
				}

				int raceNum = RabbitRaceConfig.raceNum;
				if(raceNum > 0){
					raceNum = raceNum - 1;
				}
				
				UWAPSegment seg = new UWAPSegment(
						ClientConstants.EXTEND_PROTOCOL, data.getSerial(),
						data.getSessionId());
				seg.writeShort(ClientConstants.EXTEND_RABBIT_RACE);
				seg.writeInt(0);
				seg.writeInt(nowState);
				seg.writeInts(nums);
				seg.writeInt(RabbitRaceConfig.getCountDown());
				seg.writeInt(raceNum);
				seg.writeInt(RabbitRaceConfig.raceMaxNum);
				switch (nowState) {
				case RabbitRaceConfig.STATE_RACE_RUN:
					int counter = RabbitRaceConfig.getRaceCounter();
					int firLoc = RabbitRaceConfig.getRabbitFirLoc(counter);
					int secLoc = RabbitRaceConfig.getRabbitSecLoc(counter);
					int thiLoc = RabbitRaceConfig.getRabbitThiLoc(counter);
					seg.writeInts(RabbitRaceConfig.getRabbitFirIsUseSkill());
					seg.writeInts(RabbitRaceConfig.getRabbitSecIsUseSkill());
					seg.writeInts(RabbitRaceConfig.getRabbitThiIsUseSkill());
					seg.writeInt(firLoc);
					seg.writeInt(secLoc);
					seg.writeInt(thiLoc);
					seg.writeInt(counter);
					break;
				case RabbitRaceConfig.STATE_ACTION_WAIT:
					seg.writeString("亲，兔兔百米大赛每天12:00-13:00开始哦！");
					break;
				case RabbitRaceConfig.STATE_MESSAGE:
					seg.writeString("亲，兔兔百米大赛马上就要开始了，您要准时参加哦！");
					break;
				case RabbitRaceConfig.STATE_ACTION_END:
					seg.writeString("亲，兔兔百米大赛每天12:00-13:00开始哦！您来迟了呀。");
					break;
				default:
					break;
				}
				write(seg);
			} else if (type == 1) {
				// 投注后，把玩家信息放入相应的投注队列内
				Changed changed = new Changed();
				String resultsStr;
				int wagerType = data.readInt() - 1;// 客户端发上来的是1-5，存在数组里是0-4
				int jettonNum = data.readInt();

				int afterAddJettonNum = 0;

				if (RabbitRaceConfig.playerJettonHashMap.containsKey(player
						.getId())) {
					RabbitRacePlayerData playerData = RabbitRaceConfig.playerJettonHashMap
							.get(player.getId());
					afterAddJettonNum = jettonNum
							+ playerData.getJettonNum(wagerType);
				} else {
					afterAddJettonNum = jettonNum;
				}

				if (afterAddJettonNum <= 0 || afterAddJettonNum > 1000) {
					resultsStr = "您下注的注数超出范围，单类下注总额上限1000注";
					throw new ITimesException(resultsStr, data.getSerial(),
							data.getSessionId(), (byte) 36);
				}
				int moneyForEachJetton = RabbitRaceConfig.moneyOfEachJetton;
				int money = jettonNum * moneyForEachJetton;
				if (RabbitRaceConfig.isCanWager()) {
					if (haveEnoughMoney(player, money)) {
						if (RabbitRaceConfig.playerJettonHashMap
								.containsKey(player.getId())) {
							RabbitRacePlayerData playerData = RabbitRaceConfig.playerJettonHashMap
									.get(player.getId());
							// log.info("ConnectSession:玩家" +
							// player.getPlayerName() + "投票成功，" + "注数：" +
							// jettonNum + "投注类型" + wagerType + "总注数：" +
							// afterAddJettonNum + "注");
							int raceNumForStr = RabbitRaceConfig.raceNum;
							log.info("Race number is[" + raceNumForStr + "]ID["
									+ player.getId() + "] Name["
									+ player.getPlayerName()
									+ "] vote succeed." + "His jettonNum is["
									+ jettonNum + "].Vote type is[" + wagerType
									+ "].His all jettonNum is["
									+ afterAddJettonNum + "]");
							player.decMoney(money, changed);
							playerData.addJettonNum(wagerType, jettonNum);
							RabbitRaceConfig.putPlayerInWagerTypeMap(wagerType,
									player.getId());
							sendGetItem(changed, data.getSerial(),
									data.getSessionId(), (byte) 0);
							resultsStr = "恭喜您下注成功，您当前下注总额为"
									+ playerData.getJettonNum(wagerType) + "注";
						} else {
							resultsStr = "您登陆兔兔百米大赛异常，当前下注不成功，请重新登陆兔兔百米大赛";
							throw new ITimesException(resultsStr,
									data.getSerial(), data.getSessionId(),
									(byte) 36);
						}

					} else {
						resultsStr = "您当前余额不足，投注不成功";
						throw new ITimesException(resultsStr, data.getSerial(),
								data.getSessionId(), (byte) 36);
					}
				} else {
					resultsStr = "您当前不在下注时间，请在赛跑开始前5分钟内进行投票";
					throw new ITimesException(resultsStr, data.getSerial(),
							data.getSessionId(), (byte) 36);
				}

				int jettonNumForSend = 0;
				if (RabbitRaceConfig.playerJettonHashMap.containsKey(player
						.getId())) {
					RabbitRacePlayerData playerData = RabbitRaceConfig.playerJettonHashMap
							.get(player.getId());
					jettonNumForSend = playerData.getJettonNum(wagerType);
				} else {
					jettonNumForSend = 0;
					log.info("RabbitRace:ConnectSession[1296] ID["
							+ player.getId()
							+ "] in playerJettonHashMap is Null");
				}
				UWAPSegment seg = new UWAPSegment(
						ClientConstants.EXTEND_PROTOCOL, data.getSerial(),
						data.getSessionId());
				seg.writeShort(ClientConstants.EXTEND_RABBIT_RACE);
				seg.writeInt(1);
				seg.writeInt(wagerType + 1);// 客户端的是1-5，服务器存在数组里是0-4
				seg.writeInt(jettonNumForSend);
				seg.writeString(resultsStr);
				write(seg);
			}
			// else if (type == 2) {
			//
			// }
			else if (type == 3) {
				String resultStr;
				String nameString = RabbitRaceConfig.getWinRabbitName();
				boolean isSame = data.readBoolean();
				// log.info("ConnectSession:玩家" + player.getPlayerName()+
				// "向服务器发送结束信息，申请给奖励。" );
				if (RabbitRaceConfig.isCanGiveResult()) {
					if (RabbitRaceConfig.isPlayerWin(player.getId())) {
						RabbitRaceConfig.givePlayerPrize(player.getId());
						resultStr = nameString + "。恭喜您压中结果，恭祝您的金库日渐丰盈！";
					} else if (RabbitRaceConfig.isPlayerWagerInThisRace(player
							.getId())) {
						RabbitRaceConfig.sendMoneyIfPlayerHaveJetton(player
								.getId());
						resultStr = nameString
								+ "。您没猜对结果，没关系，下次再接再厉。活动期间，系统将赠送您部分金额！";
					} else {
						// log.info("RabbitRaceConfig:玩家" +
						// player.getPlayerName() +
						// "未下注，不发钱");
						resultStr = nameString + "。投注押兔子，欢乐获大奖！";
					}
					UWAPSegment seg = new UWAPSegment(
							ClientConstants.EXTEND_PROTOCOL, data.getSerial(),
							data.getSessionId());
					seg.writeShort(ClientConstants.EXTEND_RABBIT_RACE);
					seg.writeInt(4);
					seg.writeString(resultStr);
					seg.writeInt(RabbitRaceConfig.getCountDown());
					write(seg);
				}

				// log.info("ConnectSession:服务器向玩家" + player.getPlayerName()+
				// "发送获奖的结果字符串。再给完钱之后" );
			} else if (type == 4) {
				// 退出系统，hashMap内去掉玩家信息，不再给玩家发送坐标数据
				RabbitRaceConfig.playerHashMap.remove(player.getId());
			} else if (type == 7) {
				UWAPSegment seg = new UWAPSegment(
						ClientConstants.EXTEND_PROTOCOL, data.getSerial(),
						data.getSessionId());
				seg.writeShort(ClientConstants.EXTEND_RABBIT_RACE);
				seg.writeInt(7);
				List<WinPlayerTopData> playerDataList = RabbitRaceTop
						.getWinPlayerList();
				if (playerDataList != null) {
					seg.writeShort((short) playerDataList.size());
					int size = playerDataList.size();
					// seg.writeInt(size);
					for (int i = 0; i < size; i++) {
						WinPlayerTopData tmp = playerDataList.get(i);
						seg.writeInt(tmp.getPlayerId());
						seg.writeString(tmp.getPlayerName() + "   获得奖金数额:"
								+ tmp.getPlayerMoney());
						if (i <= 0) {
							seg.writeInt(Utils.CLR_ORANGE);
						} else if (i <= 2) {
							seg.writeInt(Utils.CLR_PURPLE);
						} else if (i <= 4) {
							seg.writeInt(Utils.CLR_BLUE);
						} else {
							seg.writeInt(Utils.CLR_WHITE);
						}
					}
				} else {
					seg.writeInt(0);
				}
				write(seg);
				// RabbitRaceConfig.sendWinPlayerTopList();
			}

		}
	}
    
	/**
	 * 判断是否有足够的金钱进行投注
	 * @param player 
	 * @param moneyNum 
	 * @return
	 */
    private boolean haveEnoughMoney(WorldPlayer player, int moneyNum) {
    	boolean enough = false;
    	if(player.getMoeny() >= moneyNum){
    		enough = true;
    	}
		return enough;
	}

	//VIP系统一键升级功能 
    private void levelUpByOneButton(UWAPData data)throws Exception {
    	int level = data.readInt();
    	int type = data.readInt();
    	WorldPlayer player = getPlayer(data.getSessionId());
    	int needcount = 0;
    	if(player != null){
    		synchronized (player) {
    			if(type == 1){
    				if(player.getLevel() != level){
    					throw new ITimesException("数据异常！",data.getSerial(),
    							data.getSessionId(),data.getAppType());
    				}
    				if(player.getLevel() >= 100){
    					throw new ITimesException("您已经是满级！",data.getSerial(),
    							data.getSessionId(),data.getAppType());
    				}
    				if(level <= 3){
    					needcount = level;
    				}else{
    					needcount = level * 180 / 100;
    				}
    				int []itemprice = getIshopEasyPrice(player, 201611, needcount);
    				String info = "升级将花费" + itemprice[2] * needcount + "i币，是否继续?";
    				UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
    				seg.writeShort(ClientConstants.EXTEND_VIP_LEVEL_UP_BY_ONE_BUTTON);
    				seg.writeInt(type);
    				seg.writeString(info);
    				write(seg);
    			}else if(type == 2){
    				if(level <= 3){
    					needcount = level;
    				}else{
    					needcount = level * 180 / 100;
    				}
    				int calltype = iShopHide(player, 201611, data.getSerial(), data.getSessionId(), needcount, (byte)9, -1 , 0);
    				if(calltype == ISHOP_NOIMONEY){
    					throw new ITimesException("您的" + Server.iMoneyString + "不足。",
		    					data.getSerial(), data.getSessionId(),
		    					data.getAppType());
    				}
    				UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
    				seg.writeShort(ClientConstants.EXTEND_VIP_LEVEL_UP_BY_ONE_BUTTON);
    				seg.writeInt(type);
    				write(seg);
    			}else if(type == 3){//核对vip信息
    				boolean isSame = false;
    				int viplevel = data.readInt();
    				int vipConsume = data.readInt();
    				int playerNewVipLevel = player.getVipNewLevel();
    				int playerNewVipConsume = player.getNewActivityConsumer();
    				if(viplevel == playerNewVipLevel && vipConsume == playerNewVipConsume){
    					isSame = true;
    					UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
        				seg.writeShort(ClientConstants.EXTEND_VIP_LEVEL_UP_BY_ONE_BUTTON);
        				seg.writeInt(type);
        				seg.writeBoolean(isSame);
        				write(seg);
    				}else{
    					UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
        				seg.writeShort(ClientConstants.EXTEND_VIP_LEVEL_UP_BY_ONE_BUTTON);
        				seg.writeInt(type);
        				seg.writeBoolean(isSame);
        				if(isSame == false){
        					seg.writeInt(playerNewVipLevel);
        					seg.writeInt(playerNewVipConsume);
        				}
        				write(seg);
    				}
    				
    			}
    		}
    	}
	}
    
    
    //宝石养成
    private void diamond_develop(UWAPData data)throws Exception{
    	int type = data.readInt();
    	int equid = data.readInt();//装备id
		int gemid = data.readInt();//孔位上宝石id
		byte holes = data.readByte();//当前孔位
    	WorldPlayer player = getPlayer(data.getSessionId());
    	if(player != null){
    		synchronized (player) {
    			if(type == 1){//确认信息
    				String info = "确定要对" + Items.getTemplate(gemid).getName() + "进行融合吗？";
    				UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
					seg.writeShort(ClientConstants.EXTEND_DIAMOND_DEVELOP);
					seg.writeInt(type);
					seg.writeString(info);
					write(seg);
    			}else if(type == 2){//宝石养成
    				Grid grid = player.getEquipmentByInstanceid(equid);
    				if(grid != null){
    					IEquipment equ = (IEquipment) grid.item;
    					if(equ != null){
    						DiamondMosaic currentmosaic = DiamondMosaic.getDiamondMosaicMap().get(gemid);//当前宝石镶嵌对象
    						short developAddPoint[] = equ.getDevelopAddPoint();
    						short developAddCount[] = equ.getDevelopAddCount();
    						if(developAddPoint != null){
    							if(!player.hasItem(gemid)){//背包中没有自动购买
    								//int holesDiamondCount = currentmosaic.getDevelopAddCount() + 1;
    								int needbuycount = 1;
    								UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
									seg.writeShort(ClientConstants.EXTEND_DIAMOND_DEVELOP);
									seg.writeInt(type);
									seg.writeBoolean(false);
									seg.writeInt(needbuycount);
									seg.writeString(Items.getTemplate(gemid).getName());
									write(seg);
									return;
    		    				}
    							int itemlevel = DiamondMosaic.findDiamondMosaicLevel(gemid);//获得宝石等级
    							if(itemlevel > 3 && itemlevel < 7){
    								Grid gridDiamond = player.getItem(gemid, 0);
	    							if(gridDiamond != null){
	    								log.info("ID[" + player.getId() + "] diamond_develop itemID[" + gemid + "] Remove TRY");
	    								Changed changed = new Changed();
	    								byte[] diamondRoleInfo = equ.getDiamondMosiacRoleInfo();//孔位信息
	    								if(diamondRoleInfo[holes] != IEquipment.CURRENT_EQU_CANDIAMOND + itemlevel){
	    									log.info("ID[" + player.getId() + "] diamond_develop dimondRoleInfo holes[" + holes + "] gemid[" + gemid + "] holesInfo[" + diamondRoleInfo[holes] + "] error");
	    									throw new ITimesException("数据错误", data.getSerial(), data.getSessionId(), (byte)36);
	    								}
	    								if (player.completeRemoveItem(gemid, 1, changed) != null) {
	    									developAddCount[holes] = (short)(developAddCount[holes] + 1);
	    									equ.setDevelopAddCount(developAddCount);
	    									log.info("ID[" + player.getId() + "] diamond_develop itemID[" + gemid + "] Remove success start develop!");
	    									int destid = DiamondMosaic.findSameProHigerItemId(gemid, itemlevel + 1);//目标id
	    									DiamondMosaic destmosaic = DiamondMosaic.getDiamondMosaicMap().get(destid);
	    									if(destmosaic != null){
		    									if(developAddCount[holes] >= 4){//融合4块宝石需升级更新孔位信息
		    										developAddCount[holes] = 0;
		    										equ.setDevelopAddCount(developAddCount);
		    										developAddPoint[holes] = 0;
		    										equ.setDevelopAddPoint(developAddPoint);
		    										diamondRoleInfo[holes] = (byte) (IEquipment.CURRENT_EQU_CANDIAMOND + itemlevel + 1);
		    										equ.setDiamondMosiacRoleInfo(diamondRoleInfo);
	    											equ.diamondMosaic(holes, destmosaic);
	    											//公告
	    											String appendString = Utils.equIdtoProtocol(equ.getId());
	    											String success_msg = "玩家：" + player.getPlayerName() + "将" + Utils.getClientItemColor(equ.getQuality()) + equ.getName() + "</c>" + "上的"
	    													+ Utils.getClientItemColor(Items.getTemplate(gemid).getQuality()) + Items.getTemplate(gemid).getName() + "</c>"		
	    													+ "融合成" + Utils.getClientItemColor(Items.getTemplate(destid).getQuality()) + Items.getTemplate(destid).getName() + "</c>" + appendString;
    												if (success_msg != null){
    													chatService.sendWorldMessage(player.getId(), "系统", success_msg);
    												}
	    											log.info("ID[" + player.getId() + "] diamond develop uplevel success!");
		    									}else{
		    										diamondRoleInfo[holes] = (byte) (IEquipment.CURRENT_EQU_CANDIAMOND + itemlevel);
		    										log.info("ID[" + player.getId() + "] dest_addpoint	" + destmosaic.getAddPoint());
		    										log.info("ID[" + player.getId() + "] current_addpoint	" + developAddPoint[holes]);
		    										int offectpoint = (destmosaic.getAddPoint() - currentmosaic.getAddPoint()) / 5;//每次增加点
		    										if(offectpoint > 0){
		    											developAddPoint[holes] += offectpoint;
		    											equ.setDevelopAddPoint(developAddPoint);
		    											equ.diamondMosaic(holes, currentmosaic);
		    											log.info("ID[" + player.getId() + "] add after current_addpoint	" + developAddPoint[holes]);
		    										}
	    											equ.setDiamondMosiacRoleInfo(diamondRoleInfo);
		    									}
		    									byte bindFlag = gridDiamond.item.getBindType();
		    									if (bindFlag != IItem.BIND_NO) {
		    										equ.setBinded(true);
		    									}
		    									equ.getEnchanting().resetStone(equ);
	    									}
	    									//更新装备属性
	    									byte recalculate = player.updateEquipmentProperty(equ, changed);
	    									if (recalculate == PlayerData.PLAYER_USE_EQUIPMENT || recalculate == PlayerData.PET_USE_EQUIPMENT) {
	    										Changed changed_1 = new Changed();
	    										player.removeAllEffect(changed_1);
	    										sendGetItem(changed_1, data.getSerial(), data.getSessionId(),
	    												(byte) 10);
	    										Changed changed_2 = new Changed();
	    										player.addAllEffect(changed_2);
	    										sendGetItem(changed_2, data.getSerial(), data.getSessionId(),
	    												(byte) 10);
	    										player.adjustProperty();
	    										// 向同一地区所有玩家下发宝石光效协议；返回3-7播放对应动画
	    										positionService.gemEffectAnimate(player, player.getMap(), player.getGemEffectLevel());
	    									}
	    									sendGetItem(changed, data.getSerial(), data.getSessionId(), (byte)36);
	    									UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
	    									seg.writeShort(ClientConstants.EXTEND_DIAMOND_DEVELOP);
	    									seg.writeInt(type);
	    									seg.writeBoolean(true);
	    									write(seg);
	    								}else{
	    									log.info("ID[" + player.getId() + "] diamond_develop itemID[" + gemid + "] Remove fail!");
	    									throw new ITimesException("无法扣除宝石", data.getSerial(), data.getSessionId(), (byte)36);
	    								}
	    							}
    							}else{
        	    					throw new ITimesException("3级以上且7级以下宝石才能使用此功能!",
        	    							data.getSerial(), data.getSessionId(),
        	    							data.getAppType());
        	    				}
    	    				}else{
    	    					throw new ITimesException("暂时无法使用此功能!", data.getSerial(), data.getSessionId(), (byte) 36);
    	    				}
    					}
    				}else{
    					throw new ITimesException("你身上没有该装备", data.getSerial(), data.getSessionId(), (byte) 36);
    				}
    			}
    		}
    	}
    }
    
    
