    public int getdiamondResult(DiamondMosaic diamondmosaic){
    	int result = 0;
    	int gemlevel = diamondmosaic.getDiamondLevel();
    	if(gemlevel > 0 && gemlevel < 3){//1.2级宝石
			result = 1;
		}else if(gemlevel == 3){
			if(diamondmosaic.isCanUse()){//3级宝石
				result = 2;
			}else{//原石
				result = 1;
			}
		}else if(gemlevel > 3){//3级以上
			result = 2;
		}
    	return result;
    }
    
    public int getMagicLevel(int magicPostType, WorldPlayer player){
    	int level = 1;
    	if(magicPostType == waterMagic){//水
    		level = player.getWaterLevel();
    	}else if(magicPostType == soilMagic){
    		level = player.getSoilLevel();
    	}else if(magicPostType == fireMagic){
    		level = player.getFireLevel();
    	}else if(magicPostType == windMagic){
    		level = player.getWindLevel();
    	}else if(magicPostType == mindMagic){
    		level = player.getMindLevel();
    	}
    	
    	//数值必然在1-5之间，做一步再确认
    	if(level < 1){
    		level = 1;
		}
    	if(level > 5){
    		level = 5;
    	}
    	return level;
    }
    
    public String getMagicPosStr(int magicPostType){
    	String posStr = "";
    	if(magicPostType == waterMagic){
    		posStr = "水元素";
    	}else if(magicPostType == soilMagic){
    		posStr = "土元素";
    	}else if(magicPostType == fireMagic){
    		posStr = "火元素";
    	}else if(magicPostType == windMagic){
    		posStr = "风元素";
    	}else if(magicPostType == mindMagic){
    		posStr = "精神元素";
    	}
    	return posStr;
    }
    
    private void showWorldMessage(int preLev, int afterLev, int magicpostype, WorldPlayer player){
    	if(afterLev > preLev){
    		while(afterLev > preLev){
    			preLev++;
    			chatService.sendWorldMessage( -1, "系统",
                        "恭喜" + player.getPlayerName() + "把封印法阵" + getMagicPosStr(magicpostype) + "提升到" + MagicPosMessage.getLevStr(preLev) + "等级，解开封印属性。");
    		}
		}
    }
    
