    public String cutVersion(String version){
        String[] s = version.split("-");
        return s[0];
    }
    
    public String cutChannel(String version) {
        String[] s = version.split("-");
        if (s.length > 1) {
            return s[1];
        } else {
            return "";
        }
    }
    
    /**
     * 从取得的手机号信息文本中解析出手机号。
     * @param info <?xml version="1.0" encoding="utf-8" ?><config mobile-no="13910564907"></config>
     * @return 手机号
     */
    public String cutPhone(String info) {
        String search = "mobile-no=\"";
        int pos = info.indexOf(search);
        if (pos == -1) {
            return "";
        }
        pos += search.length();
        int pos2 = info.indexOf('"', pos);
        if (pos2 == -1) {
            return "";
        }
        return info.substring(pos, pos2);
    }

    //主界面充值查询接口
    private void cmccCharge(UWAPData data) throws Exception{
        String userId = data.readString();
        String key = data.readString();
        int charge = data.readInt();
        if(charge/100<0||charge/100>100){
            UWAPSegment seg = new UWAPSegment(ClientConstants.CMCC_CHARGE_OK,data.getSerial(),data.getSessionId());
            seg.writeString("充值数额错误！");
            write(seg);
            return;
        }
        StoreService.ChargeRequest request = storeService.charge(charge,null, data.getSerial(),data.getSessionId(),this);
        UWAPSegment seg = new UWAPSegment(ClientConstants.CMCC_CHARGE);
        seg.writeString(userId);
        seg.writeString(key);
        seg.writeInt(charge/100);
        seg.writeInt(request.id);
        seg.writeInt(charge);
        Server.instance.authSession.write(seg);
    }
    /*
     * 查看buff
     */
    private void getbuffdata(UWAPData data) throws Exception {
    	WorldPlayer player = getPlayer(data.getSessionId());
    	if(player != null){
	    	int playerId = data.readInt();
	    	Buf[] buf = null;
	    	if(player.getId() == playerId){
	    		buf = player.getBufs();
	    	}else{
	    		WorldPlayer playerDest = playerService.getWorldPlayer(playerId);
	    		if(playerDest == null){
	    			sendMessage(player.getId(), "查看的玩家已经不在线");
	    			return;
	    		}
	    		buf = playerDest.getBufs();
	    	}
	    	
	    	UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
	        seg.writeShort((short) ClientConstants.EXTEND_PROTOCOL_BUFF);
	        int addOtherBufCount = 1;
	        //添加幸运时间
	        long now = System.currentTimeMillis();
	        long lucktime = player.getLuckTime() - now;
	        if(lucktime > 0){
	        	addOtherBufCount++;
	        }
	        //添加活力显示
	        seg.write((byte)(buf.length + addOtherBufCount));
	        if(lucktime > 0){
		        seg.write((byte)0);
		        seg.writeString("幸运时间持续：" + (lucktime / 60 / 1000 + 1) + "分钟");
	        }
	        seg.write((byte)0);
	        seg.writeString("当前活力值：" + player.getAllLife() + "/" + UnlineExpConfig.LIFEVALUE_MAX);
	        for (int j = 0; j < buf.length; j++) {
	            seg.write((byte)buf[j].getId());
	            seg.writeString(Buf.getBufStringToClient(buf[j]));
	        }
	        write(seg, player.getId());
    	}
    }
    
