    							//player.addItem(findNeedItemId, 1, changed, player.getClientDataVersion());
    							player.decMoney(DiamondMosaic.getDiamondMosaicProductMoney(findNeedItemId), changed);
    							UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
    							seg.writeShort(ClientConstants.EXTEND_DIAMONDMOSAIC);
    							seg.write((byte) 4);
    							seg.write((byte) flag);
    							write(seg);
