    /**
     * 重画界面
     * @param camp
     */
    private void getTechList(WorldPlayer player,UWAPData data){
        CampData campData = campMainService.getCampData(player.getCamp());

        UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
        seg.writeShort(ClientConstants.EXTEND_CAMPTECH);
        seg.write((byte)1);
        
        if(campData.getKingId() == player.getId()){
            seg.write((byte)1);         //是国王
        }else{
            seg.write((byte)2);         //不是国王
        }
        
        List<CampSkillData> campSkillDataList = campData.getSkillDataList();
        
        seg.writeInt(campSkillDataList.size());
        
        for(CampSkillData tmp : campSkillDataList){
            int effect = tmp.getEffect();
            int level = tmp.getLevel();
            
            CampSkill campSkill = CampConfig.campSkills.get(effect);
            CampSkillLevel campSkillLevel = campSkill.getLevel(level);
            CampSkillLevel campSkillNextLevel = campSkill.getLevel(level + 1);
            
            seg.writeInt(effect);
            seg.writeString(campSkill.getName());
            seg.writeInt(level);
            
            if(level == 0){
                seg.writeString(campSkill.getNoLevelDesc());
                seg.writeInt(0);
                seg.writeInt(0);
            }else{
                seg.writeString(campSkill.getLevelDesc(level));
                seg.writeInt(campSkillLevel.getMaint());
                seg.writeInt(campSkillLevel.getDestroy());
            }
            
            seg.writeInt(campSkill.getMaxLevel());
            
            if(campSkillNextLevel != null){
                seg.writeString(campSkill.getLevelDesc(campSkillNextLevel.getLevel()));
                seg.writeInt(campSkillNextLevel.getUpgrade());
            }
        }
        
        seg.writeString(String.valueOf(campData.getMoney()));

        write(seg);                     //阵营的菜单的画出
    }
