    /*
     * 检查客户端文件的版本号。如果有文件需要更新，服务器向客户端发送多个CONN_DOWNLOAD_FILE_OK包，并在最后发
     * 送CONN_CHECK_VERSION_OK。
     */
    private void checkVersion(UWAPData data) throws Exception {
    	String version = data.readString();
    	String model = data.readString();
    	String uimodel = data.readString();
    	int fileCount = data.readInt();
    	DownloadManager dm = DownloadManager.instance;
    	
    	// 检查所有文件的版本
    	List<Object[]> updateList = new ArrayList<Object[]>();
    	int totalLen = 0;
    	for (int i = 0; i < fileCount; i++) {
    		String fileName = data.readString();
//    		if(fileName.equals("menuBar.pip")){
//    			fileName = null;
//    		}
    		int fileVersion = data.readInt();
    		int newVersion = dm.getFileVersion(version, model, uimodel, fileName, Server.revisionName);
    		if (newVersion == 0) {
    			// 文件未找到
    			continue;
    		}
    		if (fileVersion == newVersion) {
    			// 文件未更新
    			continue;
    		}
    		
    		// 文件改变，加入更新列表中
    		Object[] updateInfo = new Object[4];
    		updateInfo[0] = fileName;
    		updateInfo[1] = new Integer(newVersion);
    		if ((newVersion & 0x80000000) != 0) {
    			// 内置文件，发送数据
    			updateInfo[2] = dm.getFileContent(version, model, uimodel, fileName, Server.revisionName);
    			totalLen += ((byte[])updateInfo[2]).length + 10;
    		} else {
    			totalLen += 10;
    		}
    		updateList.add(updateInfo);
    	}

		// 发送文件更新包
    	int sentLen = 0;
    	for (Object[] ui : updateList) {
    		String updateName = (String)ui[0];
    		int updateVersion = ((Integer)ui[1]).intValue();
    		byte[] updateData = (byte[])ui[2];
    		if (updateData != null) {
    			sentLen += updateData.length + 10;
    		} else {
    			sentLen += 10;
    		}
    		UWAPSegment seg = new UWAPSegment(ClientConstants.CONN_DOWNLOAD_FILE_OK, data.getSerial(), data.getSessionId());
    		seg.writeString(updateName);
    		seg.writeInt(updateVersion);
    		seg.writeInt(sentLen * 100 / totalLen);
    		if (updateData != null) {
    			seg.write((byte)1);
    			seg.write(updateData);
    		} else {
    			seg.write((byte)0);
    		}
    		write(seg);
    	}
    	
    	// 发送检查结束包
    	UWAPSegment seg = new UWAPSegment(ClientConstants.CONN_CHECK_VERSION_OK, data.getSerial(), data.getSessionId());
		write(seg);
    }
    
    //lfzuo Added
    //1.5版本技能升级列表使用
    private void getAbilityList(UWAPData data) throws Exception{
    	WorldPlayer player = getPlayer(data.getSessionId());
    	byte skillType = data.readByte();
    	UWAPSegment seg = new UWAPSegment(ClientConstants.ABILITY_LIST, data.getSerial(), data.getSessionId());
    	setAbilityBytes(player,seg,skillType);
    	
    	write(seg);
    }
    private void setAbilityBytes(WorldPlayer player,UWAPSegment seg,byte skillType){
    	Map<Integer , Byte> skills = player.getNextSkill(skillType);
    	seg.writeInt(skills.size());
    	for(Map.Entry<Integer, Byte> skill : skills.entrySet()){
    		int id = skill.getKey();
    		Ability ability	 = Ability.getAbility(id);;
  	    	seg.writeInt(id);
  	    	seg.writeInt(ability.getMaxLevel());
  	    	seg.write((byte) ability.getRequiredLevel());
  	    	seg.writeInt(ability.getPrice());
  	    	seg.write(skill.getValue());
      	   
    	}
    }
    private void cmccHistory(UWAPData data) throws Exception{
        String userId = data.readString();
        String key = data.readString();
        int historyType = data.readInt();
        String startDate = data.readString();
        String endDate = data.readString();
        int startSequence = data.readInt();
        int pageSize = data.readInt();

        // 新版协议，后面多2个int
        boolean newProtocol = false;
        int timeType = 0;
        int queryType = 0;
        try {
            timeType = data.readInt();
            queryType = data.readInt();
            newProtocol = true;
        } catch (Exception e) {
        }

        CmccHistoryRequest request = storeService.history(historyType, startDate, endDate, startSequence, pageSize, this, data.getSessionId(), data.getSerial());
        UWAPSegment seg = new UWAPSegment(ServerConstants.CMCC_GET_HISTORY);
        seg.writeInt(request.id);
        seg.write((byte) historyType);
        seg.writeInt(-1);
        seg.writeString(startDate);
        seg.writeString(endDate);
        seg.writeInt(startSequence); //startSequence
        seg.writeInt(pageSize); //count
        if (newProtocol) {
            seg.writeInt(timeType);
            seg.writeInt(queryType);
        }
        seg.writeString(userId);
        Server.instance.authSession.write(seg);
    }

