    private void actorCreate(UWAPData data) throws Exception {
        Client client = sessionId2Clients.get(data.getSessionId());
        if (client != null && client.status == Client.STATUS.LOGIN) {
            String playerName = data.readString();
            byte sex = data.readByte();
            int version = data.readInt();
            byte campByte = 2;
            try {
            	campByte = data.readByte();	 //1：黑暗阵营；2：光明阵营
            }catch (Exception ex) {
                log.info("name["+playerName+"]-old client");
                    
            }
            try {
                Player player = playerService.createPlayer(client, playerName, sex, version);
                String model = client.model;
                if (sex == 0) {	//为男性
		    		// 阵营
			    	if (campByte == Utils.CAMP_DARK) {	//黑暗
			    		player.setCamp(campByte);
			    		if ("NK-Nokia7370".equals(model) || "Nokia6681".equals(model) || "Nokia7500".equals(model)) {
			    			player.setFace((short)0);
			    		} else {
			    			player.setFace((short)Utils.MALE_DARK_CAMP_FACE_ID);
			    		}
			    	} else if (campByte == Utils.CAMP_BRIGHT) {
			    		player.setCamp(campByte);
			    		if ("NK-Nokia7370".equals(model) || "Nokia6681".equals(model) || "Nokia7500".equals(model)) {
			    			 player.setFace((short)0);
			    		} else {
			    			 player.setFace((short)Utils.MALE_BRIGHT_CAMP_FACE_ID);
			    		}
			    	} else {
			    		log.info("ConnectSession actorCreate Camp Select Error");
			    	}
		    	} else if (sex == 1) {	//为女性
		    		// 阵营
			    	if (campByte == Utils.CAMP_DARK) {
			    		player.setCamp(campByte);
			    		if ("NK-Nokia7370".equals(model) || "Nokia6681".equals(model) || "Nokia7500".equals(model)) {
			    			 player.setFace((short)1);
			    		} else {
			    			 player.setFace((short)Utils.FEMALE_DARK_CAMP_FACE_ID);
			    		}
			    	} else if (campByte == Utils.CAMP_BRIGHT) {
			    		player.setCamp(campByte);
			    		if ("NK-Nokia7370".equals(model) || "Nokia6681".equals(model) || "Nokia7500".equals(model)) {
			    			 player.setFace((short)1);
			    		} else {
			    			player.setFace((short)Utils.FEMALE_BRIGHT_CAMP_FACE_ID);
			    		}
			    	} else {
			    		log.info("ConnectSession actorCreate Camp Select Error");
			    	}
		        }
                
                player.setCamp(campByte);
                playerService.savePlayer(player);
                UWAPSegment seg = new UWAPSegment(ClientConstants.ACTOR_CREATE_OK, data.getSerial(), data.getSessionId());
                seg.writeInt(player.getId());
                seg.writeString(player.getPlayerName());
                seg.write(player.getData());
                seg.writeInt(0);
                seg.writeInt(100);
                write(seg);
            } catch (CreatePlayerException ex) {
                throw new ITimesException(ex.getMessage(), data.getSerial(), data.getSessionId(), data.getAppType());
            }
        }
    }


    private void sessionClosed(UWAPData data) throws Exception {
        int sessionId = data.readInt();
        Client client = sessionId2Clients.get(sessionId);
        if (client != null) {
        	WorldPlayer player = playerService.getWorldPlayer(client.playerId);
        	if(player != null){
        	    CampData campData = campMainService.getCampData(player.getCamp());

                if(campData != null){
                	if(campData.getKingId() == player.getId()){
                		String campName="";
                		if(player.getCamp() == 1){
                			campName = "黑暗";
                		}else if(player.getCamp() == 2){
                			campName = "光明";
                		}
                		chatService.sendCampMessage(-1, "系统", "威风凛凛的"+campName+"阵营领袖"+player.getPlayerName()+"挥挥衣袖下线了。",player.getCamp());
                	}
                }
        	}
            removeClient(client);
        }
    }

    abstract void removeClient(Client client);



    private void removeClientNoNotify(Client client){
        if (client.sessionId != -1) {
            sessionId2Clients.remove(client.sessionId);
        }
        if (client.playerId != -1) {
            playerId2Clients.remove(client.playerId);
        }
        if (client.accountId != -1) {
            accountId2Clients.remove(client.accountId);
//            if (client.isLogin()) {
//                UWAPSegment seg1 = new UWAPSegment(ServerConstants.PLAYER_LOGOUT);
//                seg1.writeInt(client.accountId);
//                authSession.write(seg1);
//            }
        }
        if (client.status == Client.STATUS.PLAYERLOGIN) {
            WorldPlayer player = playerService.getWorldPlayer(client.playerId);
            if (player != null)
                logout(player);
        }

    }

    private void stopServer(UWAPData data) throws Exception {
        connectService.stop();
        System.exit(1);
    }

    public void forceLogout(int accountId, String key) {
        Client client = accountId2Clients.get(accountId);
        if (client != null&&client.key.equals(key)) {
            removeClientNoNotify(client);
            killSession(client.sessionId);
        }
    }

    public void forceLogout(int accountId) {
        Client client = accountId2Clients.get(accountId);
        if (client != null) {
            removeClientNoNotify(client);
            killSession(client.sessionId);
        }
    }

    public void kick(int playerId) {
        Client client = playerId2Clients.get(playerId);
        if (client != null) {
            removeClient(client);
            killSession(client.sessionId);
        }
    }

    public void killSession(int sessionId) {
        UWAPSegment seg = new UWAPSegment(ServerConstants.KICK);
        seg.writeInt(sessionId);
        write(seg);
    }

    protected Client getAndCreateClient(int sessionId) {
        Client client = sessionId2Clients.get(sessionId);
        if (client == null) {
            client = new Client(sessionId);
            sessionId2Clients.put(sessionId, client);
        }
        return client;
    }

    protected Client getClient(int sessionId) {
        return sessionId2Clients.get(sessionId);
    }
    
    public Client getClientOfPlayer(int playerId) {
        return playerId2Clients.get(playerId);
    }

    protected WorldPlayer getPlayer(int sessionId) {
        Client client = sessionId2Clients.get(sessionId);
        if (client == null)
            return null;
        if (client.isPlayerLogin()) {
            return playerService.getWorldPlayer(client.playerId);
        }
        return null;
    }
