    private void getEquGemDesc (UWAPSegment seg, IEquipment equ) {
    	int size = 0;
		byte[] roleInfo = equ.getDiamondMosiacRoleInfo();
		for (byte i = 0; i < roleInfo.length; i ++) {
			if (roleInfo[i] > 1) {
				size ++;
        	}
		}
		seg.write((byte) size);
		for (byte i = 0; i < Utils.maxHolesEqu; i ++) {
			DiamondMosaic diamondMosaic = equ.getDiamondMosaicRole(i);
			if (diamondMosaic != null) {
				seg.writeString(Items.getTemplate(diamondMosaic.getItemId()).getName());
	        	seg.writeString(Items.getTemplate(diamondMosaic.getItemId()).getDesc());
			}
		}
    }
    
    private void createTaskDetailSegment(UWAPSegment seg, WorldPlayer player, short taskId) {
    	seg.writeShort(taskId);
    	String[] names = stageService.getTasksName(new short[] { taskId }, player.getLevel());
    	seg.writeString(names[0]);  	//任务名字 string
    	seg.writeInt(stageService.getTaskLevel(taskId));//      	任务等级 int
    	
    	List<TaskTracePoint> tps = stageService.getTaskService().getTracePoints(taskId);
    	if (tps == null) {
    		seg.write((byte)0);
    	} else {
	    	seg.write((byte)tps.size());   // 寻路点数量 byte
	    	for (int i = 0; i < tps.size(); i++) {
	    		TaskTracePoint tp = tps.get(i);
	    		seg.writeInt(i + 1);       // 寻路点序号（保留）
	    		seg.writeString(tp.name);  // 目标点名称
	    		seg.writeShort(tp.mapID);  // 目标点地图ID
	    		seg.writeShort(tp.x);	   // 目标点像素x
	    		seg.writeShort(tp.y);	   // 目标点像素y
	    		seg.writeShort(tp.gridx);  // 目标点显示x
	    		seg.writeShort(tp.gridy);  // 目标点显示y
	    	}
    	}
    }
    
    private void getTaskDetails(UWAPData data) throws Exception {
        WorldPlayer player = getPlayer(data.getSessionId());
        short taskId = data.readShort();
        if (player!=null){
        	if (player.getCurrentTasksId(taskId) != null){
            	UWAPSegment seg = new UWAPSegment(ClientConstants.SEND_TASKNEWINFO, data.getSerial(), data.getSessionId());
            	createTaskDetailSegment(seg, player, taskId);
            	write(seg);
            }
        }
    }
    
    private void putTaskDetails(int type,WorldPlayer player,short taskId,int Serial,int SessionId) throws Exception {
    	if (type == 1){//登陆发
    		short[] tasks = player.getCurrentTasksId();
        	if ((tasks != null) &&(tasks.length>0)){
        		for (int i = 0; i < tasks.length; i++) {
        			UWAPSegment seg = new UWAPSegment(ClientConstants.SEND_TASKNEWINFO, Serial,SessionId);
        			createTaskDetailSegment(seg, player, tasks[i]);
                	write(seg);
                }
        	}
    	}else if (type == 2){//接任务发
    		if (player!=null){
            	if (player.getCurrentTasksId(taskId) != null){
                	UWAPSegment seg = new UWAPSegment(ClientConstants.SEND_TASKNEWINFO, Serial, SessionId);
                	createTaskDetailSegment(seg, player, taskId);
                	write(seg);
                }
            }
    	}
    	
    }
    //mengjie add end
    private void getPlayerList(UWAPData data) throws Exception {
        Client client = getClient(data.getSessionId());
        if (client != null && client.isLogin()) {
            try {
                List l = playerService.getPlayerList(client.accountId);
                int count = l.size();
                UWAPSegment seg = new UWAPSegment(ClientConstants.ACTOR_LIST, data.getSerial(), data.getSessionId());
                if (client.version.getId().compareTo("2.1.2") < 0){
                	count = Math.min(count, 4);
        		}
                seg.write((byte) count);
                for (int i = 0; i < count; i++) {
                    Player player = (Player) l.get(i);
                    seg.writeString(player.getPlayerName());
                    seg.writeShort((short) player.getLevel());
                    seg.write((byte) player.getFace());
                    seg.write(player.getReturnTimes());
                }
                for (int i = 0; i < count; i++) {
                	Player player = (Player) l.get(i);
                	seg.write(player.getCamp());
                }
                write(seg);
            } catch (DataAccessException ex) {
                throw new ITimesException("获取列表错误", data.getSerial(), data.getSessionId(), data.getAppType());
            }
        }
    }

