    public void regOk(String password,int sessionId,int serial){
        UWAPSegment seg = new UWAPSegment(ClientConstants.ACCOUNT_REG_OK, serial, sessionId);
        seg.writeString(password);
        seg.writeString("注册成功,密码是" + password + "。");
        write(seg);
        
        //为统计平台计数
        Server.realtimeStatService.registerCounter++;
    }

