    public void reply(UWAPData data, int sessionId) {
        UWAPSegment seg = new UWAPSegment(data.getAppType(), data.toBytes(),
                                          data.getSerial(), sessionId,
                                          false);

        write(seg);
    }


    public void getBbsContent(UWAPData data) throws Exception {
        WorldPlayer player = getPlayer(data.getSessionId());
        if (player != null) {
            int id = data.readInt();
            if (id >= 0) {
                Bbs bbs = bbsService.getBbs(id);
                UWAPSegment seg = new UWAPSegment(ClientConstants.BBS_CONTENT,
                                                  data.getSerial(), data.getSessionId());
                seg.writeInt(bbs.getId());
                seg.writeInt(bbs.getPlayerId());
                seg.writeString(bbs.getPlayerName());
                seg.writeString(bbs.getTitle());
                seg.writeString(bbs.getContent());
                seg.writeString(Utils.getDateString(bbs.getPostTime()));
                write(seg);
            } else { //blog
                id = -id;
                Blog blog = blogService.getBlog(id);
                UWAPSegment seg = new UWAPSegment(ClientConstants.BBS_CONTENT, data.getSerial(), data.getSessionId());
                seg.writeInt(blog.getId());
                seg.writeInt(blog.getPlayerId());
                seg.writeString(blog.getPlayerName());
                seg.writeString(blog.getTitle());
                seg.writeString(blog.getContent());
                seg.writeString(Utils.getDateString(blog.getCreateTime()));
                write(seg);
                if (blog.getPlayerId() != player.getId()) {
                    blog.setReadedTimes(blog.getReadedTimes() + 1);
                    blogService.saveBlog(blog);
                }
            }
        }
    }

    public void postBbs(UWAPData data) throws Exception {
        WorldPlayer player = getPlayer(data.getSessionId());
        if (player != null) {
            int bbsId = data.readInt();
            if(bbsService.isBbsForbiden(bbsId)){
                throw new ITimesException("此BBS不支持提交", data.getSerial(), data.getSessionId(),
                                                  data.getAppType());
            }
            TaskNpc npc = TaskNpcs.getTaskNpc(bbsId);
            if (npc != null) {
                TaskNpcType npcType = TaskNpcTypes.getTaskNpcType(npc.getType());
                if (npcType.getType() == 24) { //blog
                    GameMap map = player.getMap();
                    if (map == null || map.getInstance() == null)
                        throw new ITimesException("现在状态不能提交Blog", data.getSerial(), data.getSessionId(),
                                                  data.getAppType());
                    else {
                        HouseInstance instance = (HouseInstance) map.getInstance();
                        if (instance.getOwnerId() != player.getId()) {
                            throw new ITimesException("不能在别人的房间提交blog", data.getSerial(), data.getSessionId(),
                                    data.getAppType());
                        } else {
                            HouseData hd = houseModel.getHouseByPlayerId(instance.getOwnerId());
                            if (!hd.isUsedWaiter()) {
                                throw new ITimesException("你没有雇佣管家，不能操作", data.getSerial(), data.getSessionId(),
                                        data.getAppType());
                            }
                            String title = data.readString();
                            String content = data.readString();
                            Blog blog = new Blog();
                            blog.setTitle(title);
                            blog.setContent(content);
                            blog.setPlayerId(player.getId());
                            blog.setPlayerName(player.getPlayerName());
                            blog.setReadedTimes(0);
                            blog.setCreateTime(new Date());
                            blogService.addBlog(blog);
                            UWAPSegment seg = new UWAPSegment(ClientConstants.BBS_POST_OK, data.getSerial(),
                                    data.getSessionId());
                            write(seg);
                            
                            //jwp add start公会私聊
                            Date date = blogService.getPreviousBlob(player.getId());
                            boolean flag = false;
                            if(date == null){
                            	flag = true;
                            }else{//12个小时的比较
                            	long oldTime = date.getTime();
                            	long time = System.currentTimeMillis();
                            	if(time - oldTime >= 12 * 3600 * 1000){
                            		flag = true;
                            	}
                            }
                            if(flag){	                            
	                            //好友发信
	                            Friend[] friends = player.getFriends();
	                            for(int k = 0; k < friends.length; k++ ){
	                            	mailService.sendMail(friends[k].getId(), friends[k].getName(), -1, "系统", "BLOG通知", player.getPlayerName()+"发表了BLOG", null, 0, true);
	                            }
                            }
                            int tongId = player.getTongId();
                            if(tongId != -1){//公会消息会自动发放
                            	 chatService.sendTongMessage(tongId, -1, "公会系统",player.getPlayerName()+
            					 "在自己的家园里发表了新的博客文章，参观家园的时候不要忘记查看看哦.");
                            	 /*TongData tongData = tongService.getTongData(tongId);
                                 TongUser[] tongUsers = tongData.getTongMembers(1);
                                 if(tongUsers != null && tongUsers.length != 0){
                                	 int playerId = player.getId();
                                	 for(int i = 0; i < tongUsers.length ; i++){
                                		 if(tongUsers[i].id != playerId){
                                			
                                		 }
                                	 }
                                 }*/
                            }
                            //jwp add end
                            
                        }
                    }
                }
            } else {
            	//mengjie add
                if (player.getLevel() < StageService.BBSLEVEL){
                	throw new ITimesException("您还没到10级，不可以发公告。", data.getSerial(), data.getSessionId(),
                            data.getAppType());
            	}else if (player.getMoeny()<StageService.BBSJMONEY){
            		throw new ITimesException("您没有100金币，不可以发公告。", data.getSerial(), data.getSessionId(),
                            data.getAppType());
            	}else{
            		Changed changed = new Changed();
            		player.decMoney(StageService.BBSJMONEY, changed);
            		sendGetItem(changed, data.getSerial(), data.getSessionId(),
                            (byte) 20);
                //mengjie add end
	                String title = data.readString();
	                String content = data.readString();
	                Bbs bbs = new Bbs();
	                bbs.setBbsId(bbsId);
	                bbs.setPlayerId(player.getId());
	                bbs.setPlayerName(player.getPlayerName());
	                bbs.setTitle(title);
	                bbs.setContent(content);
	                bbs.setPostTime(new Date());
	                bbs.setPriority(100);
	                bbsService.addBbs(bbs);
	                UWAPSegment seg = new UWAPSegment(ClientConstants.BBS_POST_OK,
	                                                  data.getSerial(), data.getSessionId());
	                write(seg);
            	}
            }
        }
    }

    public void getBbsList(UWAPData data) throws Exception {
        WorldPlayer player = getPlayer(data.getSessionId());
        if (player != null) {
            int bbsId = data.readInt();
            TaskNpc npc = TaskNpcs.getTaskNpc(bbsId);
            if (npc != null) {
                TaskNpcType npcType = TaskNpcTypes.getTaskNpcType(npc.getType());
                if (npcType.getType() == 24) { //blog
                    GameMap map = player.getMap();
                    if (map == null || map.getInstance() == null)
                        throw new ITimesException("现在的状态不能进行查询", data.getSerial(), data.getSessionId(), data.getAppType());
                    else {
                        int pageSize = data.readShort();
                        int pageNo = data.readInt();
                        if (pageSize == -1) { //删blog
                            Blog blog = blogService.getBlog(pageNo);
                            if (blog.getPlayerId() == player.getId()) {
                                blogService.deleteBlog(blog.getId());
                                UWAPSegment seg = new UWAPSegment(ClientConstants.BBS_POST_OK,
                                        data.getSerial(), data.getSessionId());
                                write(seg);
                            } else {
                                throw new ITimesException("只有房主才能删帖", data.getSerial(), data.getSessionId(),
                                        data.getAppType());
                            }
                        } else {
                            HouseInstance instance = (HouseInstance) map.getInstance();
                            HouseData house = houseModel.getHouseByPlayerId(instance.getOwnerId());
                            BlogResult result = blogService.getBbsList(instance.getOwnerId(), pageSize, pageNo);
                            UWAPSegment seg = new UWAPSegment(ClientConstants.BBS_LIST, data.getSerial(),
                                    data.getSessionId());
                            seg.writeInt( -100);
                            seg.writeShort((short) pageSize);
                            seg.writeInt(pageNo);
                            seg.writeInt(result.pageCount);
                            seg.writeShort((short) result.blogs.length);
                            for (int i = 0; i < result.blogs.length; i++) {
                                Blog blog = result.blogs[i];
                                seg.writeInt(blog.getId());
                                seg.writeString("");
                                seg.writeString(blog.getTitle() + " (" + blog.getReadedTimes() + ")");
                                seg.writeString(Utils.getDateString(blog.getCreateTime()));
                            }
                            seg.writeString(house.getPlayerName());
                            write(seg);
                        }
                    }
                }
            } else {
                int pageSize = data.readShort();
                int pageNo = data.readInt();
                BbsResult result = bbsService.getBbsList(bbsId, pageSize, pageNo);
                if(result.pageCount>10)
                    result.pageCount = 10;
//                if (result.bbs.length == 0) {
//                    throw new ITimesException("没有可显示的公告", data.getSerial(),
//                                              data.getSessionId(), data.getAppType());
//                }
                //无用的 代码啊
                /*if (result.pageCount > 10)
                	result.pageCount = 10;*/
                UWAPSegment seg = new UWAPSegment(ClientConstants.BBS_LIST,
                                                  data.getSerial(), data.getSessionId());
                seg.writeInt(bbsId);
                seg.writeShort((short) pageSize);
                seg.writeInt(pageNo);
                seg.writeInt(result.pageCount);
                seg.writeShort((short) result.bbs.length);
                for (int i = 0; i < result.bbs.length; i++) {
                    Bbs bbs = result.bbs[i];
                    seg.writeInt(bbs.getId());
                    seg.writeString(bbs.getPlayerName());
                    seg.writeString(bbs.getTitle());
                    seg.writeString(Utils.getDateString(bbs.getPostTime()));
                }
                write(seg);
            }
        }
    }

    private void requestMailContent(UWAPData data) throws Exception {
        WorldPlayer player = getPlayer(data.getSessionId());
        if (player != null) {
            int mailId = data.readInt();
            synchronized(player){
	            Mail mail = mailService.getMail(mailId);
	            UWAPSegment seg = new UWAPSegment(ClientConstants.MAIL_CONTENT, data.getSerial(), data.getSessionId());
	            seg.writeInt(mailId);
	            seg.writeInt(mail.getSourceId());
	            seg.writeString(mail.getSourceName());
	            seg.writeInt(mail.getDestId());
	            seg.writeString(mail.getTitle());
	            seg.writeString(mail.getContent());
	            byte[] attachment = mail.getAttachment();
	            if (attachment == null)
	                attachment = new byte[0];
	            seg.write(ItemUtils.dbAttachment2Client(attachment, player.getClientDataVersion()));
	            seg.writeInt(mail.getPrice());
	            seg.writeString(Utils.getDateString(mail.getPostTime()));
	            seg.writeString(Utils.getDateString(mail.getValidTime()));
	            write(seg);
	            if (!mail.getReaded()) {
	                mail.setReaded(true);
	                mailService.saveMail(mail);
	                int unReaded = mailService.getUnReadedMailCount(player.getId(), player.getBlackListIds());
	                if (unReaded == 0) {
	                    UWAPSegment seg1 = new UWAPSegment(ClientConstants.MAIL_NEW, data.getSerial(), data.getSessionId());
	                    seg1.write((byte) 0);
	                    write(seg1);
	                }
	            }
            }
        }

    }

    private void requestMailList(UWAPData data) throws Exception {
        short pageSize = data.readShort();
        int pageNo = data.readInt();
        WorldPlayer player = getPlayer(data.getSessionId());
        if (player != null) {
            try {
                MailList mails = mailService.getMailList(player, pageSize, pageNo);
                List l = mails.getList();
                UWAPSegment seg = new UWAPSegment(ClientConstants.MAIL_LIST,
                                                  data.getSerial(), data.getSessionId());
                seg.writeShort(pageSize);
                seg.writeInt(pageNo);
                seg.writeInt(mails.getCount());
                seg.writeShort((short) l.size());
                for (int i = 0; i < l.size(); i++) {
                    Mail mail = (Mail) l.get(i);
                    seg.writeInt(mail.getId());
                    //如果是系统发信，提示[系统] mengjie add
                    if (mail.getSourceId() == -1){
                    	seg.writeString("[系统]");
                    }else{
                    	seg.writeString("[玩家]");
                    }
                    seg.writeString(mail.getSourceName());
                    seg.writeString(mail.getTitle());
                    seg.writeString(Utils.getDateString(mail.getPostTime()));
                    byte[] att = mail.getAttachment();
                    if (att == null || att.length == 0) {
                        seg.writeBoolean(false);
                    } else {
                        seg.writeBoolean(true);
                    }
                    seg.writeBoolean(mail.getReaded());
                }
                write(seg);
            } catch (MailException ex) {
                throw new ITimesException(ex.getMessage(), data.getSerial(), data.getSessionId(), data.getAppType());
            }
        }
    }
    
    //  add  zjl
    public final static byte MAGIC_TYPE_BUY = 1;  
    public final static byte MAGIC_TYPE_CHANGE = 2;
    public final static int MAGIC_LIFE_CHANGE = 60;  
    public final static int MAGIC_USE_MAX = 720;     //每天最大购买限制
    public final static int MAGIC_TIMES = 2;
  
	private void magicBuy(UWAPData data) throws Exception {
		byte type = data.readByte();
		WorldPlayer player = getPlayer(data.getSessionId());
		if (player != null) {
			synchronized (player) {
				switch (type) {
				case MAGIC_TYPE_BUY:           //购买物品
					int itemId = data.readInt();
					int count = data.readInt();
					if (player != null) {
						IStoreItem item = IStoreGroups2.getStoreItem(itemId);
						boolean isFull = false;
						if (item != null) {
							itemId = item.item.getItemId();
							Changed changed = new Changed();
							int money = item.price * count;
							long useTime = player.getClock().getTime();
							long today = Utils.getTodayStart();    //一天起始时间
							long todayEnd = today + 24 * 60 * 60 * 1000L; //一天结束
						    if (player.getMagicIMoney() >= money){   
						    	//可以购买物品
						    	if(useTime >= today && useTime < todayEnd){   //一天之内的情况 
						    	}else{
									  player.setClockUse(0);
									  player.setClock(new Date());
								}
						    	if(player.getClockUse() + money > MAGIC_USE_MAX){
					    			throw new ITimesException("一天不能超过" + MAGIC_USE_MAX + "点魔法I币",
					    					data.getSerial(), data.getSessionId(),
					    					data.getAppType());
					            }
						    	
						    	player.setClockUse(player.getClockUse() + money);	 
						    }else{
						    		if(useTime >= today && useTime < todayEnd){ //一天内	
						    		}else{
						    				player.setClockUse(0);
						    				player.setClock(new Date());
						    		}
						    		if(player.getClockUse() + money > MAGIC_USE_MAX){
						    				throw new ITimesException("一天不能超过" + MAGIC_USE_MAX + "点魔法I币",
					    					data.getSerial(), data.getSessionId(),
					    					data.getAppType());
						    		}else if(player.getMagicIMoney() < money){
						    			throw new ITimesException("您的魔法i币不足,是否兑换?",
				    					data.getSerial(), data.getSessionId(),
				    					data.getAppType());
						    		}
						    }
						    
							if(player.hasItem(itemId) && player.getItemCount(itemId) + count <= 99){
								player.addItem(itemId, count, changed,
										player.getClientDataVersion());
								sendGetItem(changed, data.getSerial(), data.getSessionId(), data.getAppType());
								sendMessage(player.getId(), "购买成功,物品已放入背包!已经扣除" + money + "点魔法i币");
							}else if(!player.isFull() && !player.hasItem(itemId)){
								player.addItem(itemId, count, changed,
										player.getClientDataVersion());
								sendGetItem(changed, data.getSerial(), data.getSessionId(), data.getAppType());
								sendMessage(player.getId(), "购买成功,物品已放入背包!已经扣除" + money + "点魔法i币");
							}else{
								isFull = true;
								IItem iit = Items.getTemplate(itemId)
										.newInstance();
								byte[] att = ItemUtils.item2dbAttachment(iit,
										count);
								mailService.sendMail(player.getId(),
										player.getPlayerName(), -1, "系统",
										iit.getName() + "*" + count, "", att, 0,
										true);
								sendMessage(player.getId(),
										"你的背包满了，已经把物品邮寄到您的邮箱!已经扣除" + money + "点魔法i币");
							}
							player.setMagicIMoney(player.getMagicIMoney() - money);
						}
						UWAPSegment seg = new UWAPSegment(
								ClientConstants.EXTEND_PROTOCOL,
								data.getSerial(), data.getSessionId());
						seg.writeShort(ClientConstants.EXTEND_MAGIC_BUY);
						seg.write(MAGIC_TYPE_BUY);
						seg.writeInt(player.getMagicIMoney());
						write(seg);
					}
					break;
				case MAGIC_TYPE_CHANGE:             //活力值兑换
					int lifeValue = data.readInt();
					if (lifeValue % 10 != 0) {
						throw new ITimesException("不符合兑换规则，无法兑换",
								data.getSerial(), data.getSessionId(),
								data.getAppType());
					} else {
						int playerLife = player.getAllLife();
						if (playerLife < lifeValue) {
							throw new ITimesException("您的活力值不足",
									data.getSerial(), data.getSessionId(),
									data.getAppType());
//							sendMessage(player.getId(), "您的活力值不足");
//						    return;
						} else {                 
//							long useTime = player.getClock().getTime();
//							long today = Utils.getTodayStart();    //一天起始时间
//							long todayEnd = today + 24 * 60 * 60 * 1000L; //一天结束
							int magicValue = lifeValue * (MAGIC_LIFE_CHANGE * MAGIC_TIMES) / 10;  //兑换后魔法i币
//							if(useTime >= today && useTime < todayEnd){   //当天情况
//								if(player.getClockUse() + magicValue > MAGIC_USE_MAX){   
//									throw new ITimesException("一天不能超过" + MAGIC_USE_MAX + "点魔法I币",
//											data.getSerial(), data.getSessionId(),
//											data.getAppType());
//								}
//							}
							player.setMagicIMoney(player.getMagicIMoney()
									+ magicValue);
							player.setLifeValue(player.getLifeValue()
									- lifeValue);
							if(MAGIC_TIMES > 1){
								sendMessage(player.getId(), "兑换成功,使用了" + lifeValue + "活力获得了" + MAGIC_TIMES + "倍的魔法i币为:" + magicValue);
							}else{
								sendMessage(player.getId(), "兑换成功,使用了" + lifeValue + "活力获得了" + magicValue + "魔法i币");
							}
							UWAPSegment seg = new UWAPSegment(
									ClientConstants.EXTEND_PROTOCOL,
									data.getSerial(), data.getSessionId());
							seg.writeShort(ClientConstants.EXTEND_MAGIC_BUY);
							seg.write(MAGIC_TYPE_CHANGE);
							seg.writeInt(player.getMagicIMoney());
							write(seg);
						}
					}
					break;
				}
			}
		}
	}
  
    
    private void iShopTrade(UWAPData data) throws Exception {
//        1	itemId	商品Id	int
//        2	count	数量或者装备id	int
        int itemId = data.readInt();
        int count = data.readInt();
        //ticketCounts += count;
        WorldPlayer player = getPlayer(data.getSessionId());
        if (player != null) {
            IStoreItem item = IStoreGroups.getStoreItem(itemId);
            if (item != null) {
                int requestItemId = itemId;
                itemId = item.item.getItemId();
                if (item.item.getType() == IItem.TYPE_EQU)
                    count = 1;
//                Utils.log(log, player.getId(), data.getAppType(),
//                          "iMoney[" +
//                          player.getiMoney() + "]TRY");
                if (itemId < 0){
                	Utils.log(log, player.getId(), data.getAppType(),
                            "iMoney[" +
                            player.getLongIMoney() + "] Buytype[CMCC]TRY");
                }else{
                	Utils.log(log, player.getId(), data.getAppType(),
                            "iMoney[" +
                            player.getLongIMoney() + "] Buytype[NORMAL]TRY");
                }
                if(Server.iMoneyType == Server.IMONEY_TYPE_QQ){
                	if (itemId < 0){
                		addLogService.log(player.getId(), data.getAppType(),
                                "iMoney[" +
                                player.getLongIMoney() + "] Buytype[CMCC]TRY");
                    }else{
                    	addLogService.log(player.getId(), data.getAppType(),
                                "iMoney[" +
                                player.getLongIMoney() + "] Buytype[NORMAL]TRY");
                    }
                }
                if(item.times.size()!=0 ){
                	for(int i= 0 ;i< item.times.size();i++){
            			String start = item.times.get(i).getStart();
                    	String end = item.times.get(i).getEnd();
                    	Calendar calendarStart = IShopTimeItem.getDate(start);
                    	Calendar calendarEnd = IShopTimeItem.getDate(end);
            			if(System.currentTimeMillis()>calendarStart.getTimeInMillis()&& System.currentTimeMillis() < calendarEnd.getTimeInMillis())
            			    if(item.times.get(i).getCount() != -1 && (item.times.get(i).getCount()-count)<0){
            			    	throw new ITimesException("此商品已经销售完毕，或者数量不够",
                                        data.getSerial(),
                                        data.getSessionId(),
                                        data.getAppType());
            			    }
            		}
                }else{
                	if (item.count != -1 && (item.count - count) < 0) {
                        throw new ITimesException("此商品已经销售完毕，或者数量不够",
                                                  data.getSerial(),
                                                  data.getSessionId(),
                                                  data.getAppType());
                    }
                }
                
                
                

                int money = item.price;
                if(item.times.size()!=0 ){
                	for(int i= 0 ;i< item.times.size();i++){
            			String start = item.times.get(i).getStart();
                    	String end = item.times.get(i).getEnd();
                    	Calendar calendarStart = IShopTimeItem.getDate(start);
                    	Calendar calendarEnd = IShopTimeItem.getDate(end);
            			if(System.currentTimeMillis()>calendarStart.getTimeInMillis()&& System.currentTimeMillis() < calendarEnd.getTimeInMillis()){
            				money = item.times.get(i).getPrice();
            			
            			}
                	}
                }
                //add jwp add 折扣数在外面计算。循环里直接乘加快速度
                int discount = Discount.DISCOUNT;
                if(player.isSubscribe()){//包月折扣
                	discount = Discount.MDISCOUNT;
                }
                boolean hasTongIsland = tongService.hasTongIsland(player.getTongId());
                if(hasTongIsland){//公会折扣
                	if(discount > Discount.TONGDISCOUNT){
                		discount = Discount.TONGDISCOUNT;
                	}
                }
                String[] week = Utils.getWeekBeignEnd();
                if(topListService.playerTopList.getPlayerIbuyTop(player, 10,week[0],week[1])){
                	if(discount > Discount.FAMOUSCOUNT){
                		discount = Discount.FAMOUSCOUNT;
                	}
                }
                
                 money = Utils.getDiscountPrice(money, discount);
                
               
                
                if(Server.iMoneyType == Server.IMONEY_TYPE_PIP && item.discount != 100 && item.discount > 0){
                	money = Utils.getDiscountPrice(money, item.discount);
                }
                
                //add jwp end
                /*if (player.isSubscribe()) {
                    money = Utils.getDiscountPrice(money,Discount.MDISCOUNT);
//                    money = money * Discount.MDISCOUNT / 100;
                } else {
                	money = Utils.getDiscountPrice(money, Discount.DISCOUNT);
                	String[] week = Utils.getWeekBeignEnd();
                	if (topListService.playerTopList.getPlayerIbuyTop(player, 10,week[0],week[1])){//如果玩家是名人堂玩家
                		money = Utils.getDiscountPrice(money, Discount.FAMOUSCOUNT);
                	}
                	if (tongService.hasTongIsland(player.getTongId())) {
                		if(Utils.getDiscountPrice(money, Discount.TONGDISCOUNT ) < money ){
                			money = Utils.getDiscountPrice(money, Discount.TONGDISCOUNT );
                		}
            		}
                }*/
//                                   item.price *
//                                   item.item.getPrice() / 10000);
                if (item.item.getType() != IItem.TYPE_EQU) {
                    money *= count;
                } else {
                    EquipmentTemplate et = (EquipmentTemplate)
                                           item.item;
                    if (et.getCredit() > player.getCreditIndex())
                        throw new ITimesException("荣誉不够，需要“" + et.getCreditName() + "”",
                                                  data.getSerial(),
                                                  data.getSessionId(),
                                                  data.getAppType());
                    if (et.getCredit() > 0 &&
                        et.getRequiredLevel() > player.getLevel())
                        throw new ITimesException("级别不够",
                                                  data.getSerial(),
                                                  data.getSessionId(),
                                                  data.getAppType());
                }
                money *= 100;
                
                // 创建request对象
                StoreService.Request request = storeService.request(player, item, count, money, data.getSerial(),this,"");
                Client client = sessionId2Clients.get(data.getSessionId());
                if(request!=null){
                    // LightHu: 对于特殊分类(短信专区/话费专区)，请求的ID是负数，直接发请求给卓望认证，不考虑用券
                    if (requestItemId < 0) {
                    	sendRequestToCmccAuth(request, player.getAccountId(), player.getkey(),data.getSerial(), data.getSessionId(), true);
//                    	if(item.item.newInstance().isBinded()){
//                    		sendRequestToCmccAuth(request, player.getAccountId(), player.getkey(),data.getSerial(), data.getSessionId(), false);
//                    	}else{
//                    		sendRequestToCmccAuth(request, player.getAccountId(), player.getkey(),data.getSerial(), data.getSessionId(), true);
//                    	}
                        return;
                    }
                    
                    //mengjie add
                	if (player.getMonthibuy() >= FriendsService.FRIENDLIMIT){
	                	int friendimoney = friendsService.getImoney(player.getId());
	                	if(friendimoney*100 < money ){
	                		if(item.item.newInstance().isBinded()){
	                			sendRequestToAuth(request, player.getAccountId(), player.getkey(),data.getSerial(), data.getSessionId(), false);
	                		}else{
	                			sendRequestToAuth(request, player.getAccountId(), player.getkey(),data.getSerial(), data.getSessionId(), true);
	                		}
	                	}else{
	                		//从i币劵扣除
	                		Utils.log(log, player.getId(), 58,
	                                "iMoney[" + money + "]TRY by quan");
	                		friendsService.lessimoney(player.getId(), player.getAccountId(), money/100);
	                		BuyResult resulttemp = new BuyResult();
	                		resulttemp.success = true;
	                		resulttemp.iMoney = -1;
	                		resulttemp.bBalance = -1;
	                		resulttemp.cost = 0;
	                		resulttemp.realCost = 0;
	                		resulttemp.cause = "";
	                		resulttemp.sessionId = data.getSessionId();
	                		resulttemp.serial = data.getSerial();
	                		this.buyResult(resulttemp,request);
	                	}
                	}else{
                		if(item.item.newInstance().isBinded()){
                			sendRequestToAuth(request, player.getAccountId(), player.getkey(),data.getSerial(), data.getSessionId(), false);
                		}else{
                			sendRequestToAuth(request, player.getAccountId(), player.getkey(),data.getSerial(), data.getSessionId(), true);
                		}
                	}
                	//mengjie add end
                    //sendRequestToAuth(request, player.getAccountId(), player.getkey(),data.getSerial(), data.getSessionId());
                }else{
                    throw new ITimesException("不能购买此物品",data.getSerial(),data.getSessionId(),(byte)20);
                }
            }
        }
    }
    
    private void iShopEasy(UWAPData data) throws Exception {
		// 1 itemId 商品Id int
		// 2 count 数量或者装备id int
		// 3 type 想做的事情 byte 1:表示查询可以购买多少个指定的物品
		int itemId = data.readInt();
		int count = data.readInt();
		byte type = data.readByte();
		
		if (count <= 0){
			log.info("iShopEasy Exception itemID[" + itemId + "] type[" + type + "] count zero");
			throw new ITimesException("数据异常，请重试。", data.getSerial(),
					data.getSessionId(), data.getAppType());
		}
		
		WorldPlayer player = getPlayer(data.getSessionId());
		if (player != null) {
			IStoreItem item = IStoreGroups.getStoreItem(itemId);
			UWAPSegment seg;
			if (item != null) {
				int requestItemId = itemId;
				itemId = item.item.getItemId();
				if (item.item.getType() == IItem.TYPE_EQU)
					count = 1;
				if (itemId < 0) {
					Utils.log(log, player.getId(), data.getAppType(), "iMoney["
							+ player.getLongIMoney() + "] Buytype[CMCC]TRY");
				} else {
					Utils.log(log, player.getId(), data.getAppType(), "iMoney["
							+ player.getLongIMoney() + "] Buytype[NORMAL]TRY");
				}
				if (Server.iMoneyType == Server.IMONEY_TYPE_QQ) {
					if (itemId < 0) {
						addLogService.log(player.getId(), data.getAppType(),
								"iMoney[" + player.getLongIMoney()
										+ "] Buytype[CMCC]TRY");
					} else {
						addLogService.log(player.getId(), data.getAppType(),
								"iMoney[" + player.getLongIMoney()
										+ "] Buytype[NORMAL]TRY");
					}
				}
				if (item.count != -1 && (item.count - count) < 0) {
//					throw new ITimesException("此商品已经销售完毕，或者数量不够", data
//							.getSerial(), data.getSessionId(), data
//							.getAppType());
					seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data
							.getSerial(), data.getSessionId());
					seg.writeShort(ClientConstants.EXTEND_ISHOP_EASY);
					seg.write(type);
					seg.writeInt(-2);			//此商品已经销售完毕，或者数量不够
					write(seg);
					return;
				}

				int money = item.price;
				// add jwp add 折扣数在外面计算。循环里直接乘加快速度
				int discount = Discount.DISCOUNT;
				if (player.isSubscribe()) {// 包月折扣
					discount = Discount.MDISCOUNT;
				}
				boolean hasTongIsland = tongService.hasTongIsland(player
						.getTongId());
				if (hasTongIsland) {// 公会折扣
					if (discount > Discount.TONGDISCOUNT) {
						discount = Discount.TONGDISCOUNT;
					}
				}
				String[] week = Utils.getWeekBeignEnd();
				if (topListService.playerTopList.getPlayerIbuyTop(player, 10,
						week[0], week[1])) {
					if (discount > Discount.FAMOUSCOUNT) {
						discount = Discount.FAMOUSCOUNT;
					}
				}
				money = Utils.getDiscountPrice(money, discount);
				
				if(Server.iMoneyType == Server.IMONEY_TYPE_PIP && item.discount != 100 && item.discount > 0){
                	money = Utils.getDiscountPrice(money, item.discount);
                }

				if (item.item.getType() != IItem.TYPE_EQU) {
					money *= count;
				} else {
					EquipmentTemplate et = (EquipmentTemplate) item.item;
					if (et.getCredit() > player.getCreditIndex()){
						throw new ITimesException("荣誉不够，需要“"
								+ et.getCreditName() + "”", data.getSerial(),
								data.getSessionId(), data.getAppType());
					}
					if (et.getCredit() > 0
							&& et.getRequiredLevel() > player.getLevel())
						throw new ITimesException("级别不够", data.getSerial(),
								data.getSessionId(), data.getAppType());
				}
				
				
				int iMoney = (int)(player.getLongIMoney() / 100);
				
				switch(type){
				case 1:		//查询可以购买多少个指定的物品
					sendBuyCount(data, type, iMoney / money);
					return;
				case 2:		//购买指定的个数
					if(money > iMoney){
						sendBuyCount(data, type, -3);		//i币不够
						return;
					}
					break;
				case 3:		//查询玩家需要购买多少个
					int haveCount = player.getItemCount(itemId);
//					sendBuyCount(data, type, count - haveCount);
					seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data
							.getSerial(), data.getSessionId());
					seg.writeShort(ClientConstants.EXTEND_ISHOP_EASY);
					seg.write(type);
					seg.writeInt(count - haveCount);
					seg.writeInt(money / count);		//添加一个的单价
					write(seg);
					return;
				}
				
				money *= 100;

				// 创建request对象
				StoreService.Request request = storeService.request(player,
						item, count, money, data.getSerial(), this, "");
				Client client = sessionId2Clients.get(data.getSessionId());
				if (request != null) {
					// LightHu: 对于特殊分类(短信专区/话费专区)，请求的ID是负数，直接发请求给卓望认证，不考虑用券
					if (requestItemId < 0) {
						sendRequestToCmccAuth(request, player.getAccountId(),
								player.getkey(), data.getSerial(), data
										.getSessionId(), true);
						return;
					}
					request.sendClient = true;
					request.sendClientType = type;
					request.sendClientCount = count;
					request.sendClentData = data;
					sendRequestToAuth(request, player.getAccountId(),
							player.getkey(), data.getSerial(), data
									.getSessionId(), true);
//					sendBuyCount(data, type, count);
					// mengjie add end
					// sendRequestToAuth(request, player.getAccountId(),
					// player.getkey(),data.getSerial(), data.getSessionId());
				} else {
//					throw new ITimesException("不能购买此物品", data.getSerial(), data
//							.getSessionId(), (byte) 20);
					sendBuyCount(data, type, -2);		//不能购买此物品
				}
			}else{
				//没有此物品
				sendBuyCount(data, type, -1);
			}
		}
	}
    
    
