    public int iShopHide(WorldPlayer player, int itemId, int serial, int sessionId, int count, byte type, int delitemid, int delcount, boolean checkBBalance, boolean getMoney) throws Exception {
		// 1 itemId 商品Id int
		// 2 count 数量
		if (player != null) {
			IStoreItem item = IStoreGroups.getStoreItem(itemId);
			if (item != null) {
				int requestItemId = itemId;
				itemId = item.item.getItemId();
				if (item.item.getType() == IItem.TYPE_EQU)
					count = 1;
				if (item.count != -1 && (item.count - count) < 0) {
					return ISHOP_NOITME;
				}

				int money = item.price;
				// add jwp add 折扣数在外面计算。循环里直接乘加快速度
				int discount = Discount.DISCOUNT;
				if (player.isSubscribe()) {// 包月折扣
					discount = Discount.MDISCOUNT;
				}
				boolean hasTongIsland = tongService.hasTongIsland(player
						.getTongId());
				if (hasTongIsland) {// 公会折扣
					if (discount > Discount.TONGDISCOUNT) {
						discount = Discount.TONGDISCOUNT;
					}
				}
				String[] week = Utils.getWeekBeignEnd();
				if (topListService.playerTopList.getPlayerIbuyTop(player, 10,
						week[0], week[1])) {
					if (discount > Discount.FAMOUSCOUNT) {
						discount = Discount.FAMOUSCOUNT;
					}
				}
				money = Utils.getDiscountPrice(money, discount);
				
				if(Server.iMoneyType == Server.IMONEY_TYPE_PIP && item.discount != 100 && item.discount > 0){
                	money = Utils.getDiscountPrice(money, item.discount);
                }
				
				if(money < 1){
					money = 1;
				}

				if (item.item.getType() != IItem.TYPE_EQU) {
					money *= count;
				} else {
					EquipmentTemplate et = (EquipmentTemplate) item.item;
					if (et.getCredit() > player.getCreditIndex()){
						return ISHOP_NOCREDIT;
					}
					if (et.getCredit() > 0
							&& et.getRequiredLevel() > player.getLevel())
						return ISHOP_NOLEVEL;
				}
				
				//提取所需要的I币值
				if(getMoney){
					return money * 100;
				}
				
				int iMoney = (int)(player.getLongIMoney() / 100);
				
				if(money > iMoney){
					return ISHOP_NOIMONEY;
				}
				
				money *= 100;
				
				
				//需要检测B币的情况
				if(checkBBalance){
					if(player.getLongIMoney() - player.getBBalance() < money){
						return ISHOP_NOIMONEYHASBBALANCE;
					}
				}
				
				
				// 创建request对象
				StoreService.Request request = storeService.request(player,
						item, count, money, serial, this, "");
				Client client = sessionId2Clients.get(sessionId);
				if (request != null) {
					// LightHu: 对于特殊分类(短信专区/话费专区)，请求的ID是负数，直接发请求给卓望认证，不考虑用券
					if (requestItemId < 0) {
//						sendRequestToCmccAuth(request, player.getAccountId(),
//								player.getkey(), serial, sessionId);
						return ISHOP_CMCC;
					}
					request.serial = serial;
					request.sendSessionId = sessionId;
					request.sendItem = false;
					request.sendClientType = type;
					request.delitemid = delitemid;
					request.delitemcount = delcount;
					sendRequestToAuth(request, player.getAccountId(),
							player.getkey(), serial, sessionId, true);
					return ISHOP_OK;
				} else {
					return ISHOP_FAIL;
				}
			}else{
				//没有此物品
				return ISHOP_NOGOODS;
			}
		}
		return ISHOP_NOPLAYER;
	}
    
    private final static byte TS_GETTOPLIST = 1;//获取首页列表
    private final static byte TS_GETITEMLIST = 2;//获取商品列表
    private final static byte TS_TRADE = 3;//购买商品
    //公会商店
    private void tongShop(UWAPData data) throws Exception {
    	byte type = data.readByte();
    	WorldPlayer player = getPlayer(data.getSessionId());
        if (player != null) {
        	int npcTypeID = data.readInt();
        	switch(type){
        	case TS_GETTOPLIST: //获取首页列表
        		sendTongShop_TopList(data,player,npcTypeID);
        		break;
         	case TS_GETITEMLIST: //获取商品列表
        		String groupName = data.readString();
        		sendTongShop_ItemList(data,player,groupName,npcTypeID);
        		break;
        	case TS_TRADE: //购买商品
        		groupName = data.readString();
        		int itemId = data.readInt();
        		byte count = data.readByte();
        		synchronized (player) {
        			IStoreItem item = TongShopGroups.getShopItem(npcTypeID, groupName, itemId);
        			if(item!=null){
	        			itemId = item.item.getItemId();
	    				if (item.count != -1 && (item.count - count) < 0) {
	    					sendTongShop_ItemList(data,player,groupName,npcTypeID);
	    					sendMessage(player.getId(),"此商品已经销售完毕，或者数量不够!");
	    					return;
//	                        throw new ITimesException("此商品已经销售完毕，或者数量不够",
//	                                                  data.getSerial(),
//	                                                  data.getSessionId(),
//	                                                  data.getAppType());
	                    }
	    				int money = item.price * count;
	    				long useTime = player.getClock_TongShop().getTime();
	    				long today = Utils.getTodayStart();    //一天起始时间
	    				long todayEnd = today + 24 * 60 * 60 * 1000L; //一天结束
	    			    if (player.getMagicIMoney() >= money){   
	    			    	//可以购买物品
	    			    	if(useTime >= today && useTime < todayEnd){   //一天之内的情况 
	    			    	}else{
	    						  player.setClockUse_TongShop(0);
	    						  player.setClock_TongShop(new Date());
	    					}
	    			    	if(player.getClockUse_TongShop() + money > TongShopGroups.getMagicUseMax()){
	    		    			throw new ITimesException("一天不能超过" + TongShopGroups.getMagicUseMax() + "点魔法I币",
	    		    					data.getSerial(), data.getSessionId(),
	    		    					data.getAppType());
	    		            }
	    			    }else{
    			    		if(useTime >= today && useTime < todayEnd){ //一天内	
    			    		}else{
    			    				player.setClockUse_TongShop(0);
    			    				player.setClock_TongShop(new Date());
    			    		}
    			    		if(player.getClockUse_TongShop() + money > TongShopGroups.getMagicUseMax()){
    			    				throw new ITimesException("一天不能超过" + TongShopGroups.getMagicUseMax() + "点魔法I币",
    		    					data.getSerial(), data.getSessionId(),
    		    					data.getAppType());
    			    		}else if(player.getMagicIMoney() < money){
    			    			sendTongShop_ItemList(data,player,groupName,npcTypeID);
    			    			sendMessage(player.getId(),"您的魔法i币不足。");
    			    			return;
//    			    			throw new ITimesException("您的魔法i币不足。",
//    	    					data.getSerial(), data.getSessionId(),
//    	    					data.getAppType());
    			    		}
	    			    }
	    			    int contribute = item.contribute * count;
	    			    if(player.getContribution() < contribute){
	    			    	sendTongShop_ItemList(data,player,groupName,npcTypeID);
	    			    	sendMessage(player.getId(),"您的公会贡献度不够。");
	    			    	return;
//	    			    	throw new ITimesException("您的公会贡献度不够。",
//	    			    			data.getSerial(), data.getSessionId(),
//	    			    			data.getAppType());
	    			    }
	    			    Utils.log(log, player.getId(), data.getAppType(),
	                            "TongShop_BuyItem  itemID[" + itemId +"] magicIMoney[" +
	                            player.getMagicIMoney() + "] TongContribute[" + player.getContribution() + "] TRY");
	    			   
	    			    item.count -= count; 
						if (item.count < -1) {
							item.count = -1;
						}
						Changed changed = new Changed();
						IItem nItem = player.completeAddItem(item.item.
											newInstance(), count, changed, player.getClientDataVersion());
						player.setMagicIMoney(player.getMagicIMoney() - money);
						player.setClockUse_TongShop(player.getClockUse_TongShop() + money);	 
						player.setContribution(player.getContribution() - contribute);
						sendTongShop_ItemList(data,player,groupName,npcTypeID);
						if (nItem == null) {
							IItem iit = Items.getTemplate(item.item.getItemId()).newInstance();
							byte[] att = ItemUtils.item2dbAttachment(iit, count);
		                    mailService.sendMail(player.getId(), player.getPlayerName(), -1, "系统",
		                    		iit.getName() + "*" + count, "", att, 0, true);
		                    sendMessage(player.getId(),"你的背包满了，已经把物品邮寄到您的邮箱!");
						}
						sendGetItem(changed, data.getSerial(), data.getSessionId(), (byte) 2);
						Utils.log(log, player.getId(), data.getAppType(),
	                            "TongShop_BuyItem  itemID[" + itemId +"] magicIMoney[" +
	                            player.getMagicIMoney() + "] TongContribute[" + player.getContribution() + "] SUCCESS");
        			}else{
        				sendTongShop_ItemList(data,player,groupName,npcTypeID);
        				sendMessage(player.getId(),"此商品已下架。");
    			    	return;
//        				throw new ITimesException("此商品已下架。",
//		    					data.getSerial(), data.getSessionId(),
//		    					data.getAppType());
        			}
				}
        		
        		break;
        	}
        }
    }
    //下发公会商店的商品列表
    private void sendTongShop_ItemList(UWAPData data, WorldPlayer player, String storeName, int npcTypeID) throws Exception {
    	UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
		seg.writeShort(ClientConstants.EXTEND_TONGSHOP);
		seg.writeInt(npcTypeID);
		seg.writeInt(player.getMagicIMoney());
		seg.writeInt(player.getContribution());//公会贡献度
		seg.write(TS_GETITEMLIST);
		IStoreGroup group = TongShopGroups.getGroup(npcTypeID,storeName);
		if(group!=null){
			IStoreItem[] items = group.getItems();
			seg.writeInt(items.length);
			for (int i = 0; i < items.length; i++) {
				seg.writeInt(items[i].item.getItemId());
				seg.writeString(items[i].item.getName());
				seg.writeInt(items[i].price);
				seg.writeInt(items[i].contribute);
				seg.writeInt(items[i].count);
				seg.write(items[i].item.getQuality());
			}
		}else{
			seg.writeInt(0);
		}
		write(seg);
    }
