    private void iShopList(UWAPData data) throws Exception {
//        1	Accountname	帐号名	String
//        2	Imoney	当前i币	Int
//        3	Class	分类数量	Byte
//        循环n次	ClassName	类型名	String
//        5	count	数量	short
//        循环N次	itemId	物品id	int
//                itemName	物品名字	String
//                sellprice	价钱	int
//                Count	数量	int	-1 为无限
        WorldPlayer player = getPlayer(data.getSessionId());
        if (player != null) {
            Collection<IStoreGroup> groups = IStoreGroups.getGroups();
            Client client = sessionId2Clients.get(data.getSessionId());
            groups = filterIshopGroups(client, groups);
            UWAPSegment seg = new UWAPSegment(ClientConstants.ISHOP_LIST, data.getSerial(), data.getSessionId());
            seg.writeString(player.getAccountName());
            seg.writeInt((int)(player.getLongIMoney() / 100));
            //add mengjie
            int Imoney_q = friendsService.getImoney(player.getId());
            seg.writeInt(Imoney_q);
            //add mengjie end
            
            int size = 0;
            for (IStoreGroup group : groups) {
                if(!group.getHide()){
                	size ++;
                }
            }
            seg.write((byte) size);
            for (IStoreGroup group : groups) {
            	if(!group.getHide()){
            		seg.writeString(group.getName());
            	}
            }
            //add jwp add 折扣数在外面计算。循环里直接乘加快速度
            int discount = Discount.DISCOUNT;
            if(player.isSubscribe()){//包月折扣
            	discount = Discount.MDISCOUNT;
            }
            boolean hasTongIsland = tongService.hasTongIsland(player.getTongId());
            if(hasTongIsland){//公会折扣
            	if(discount > Discount.TONGDISCOUNT){
            		discount = Discount.TONGDISCOUNT;
            	}
            }
            String[] week = Utils.getWeekBeignEnd();
            if(topListService.playerTopList.getPlayerIbuyTop(player, 10,week[0],week[1])){
            	if(discount > Discount.FAMOUSCOUNT){
            		discount = Discount.FAMOUSCOUNT;
            	}
            }
            //add jwp end
            for (IStoreGroup group : groups) {
            	if(group.getHide()) continue;
                IStoreItem[] items = group.getItems();
                if(group.getName().contains("限时")){
                	int count = 0;
                	for(int n = 0;n < group.getItems().length; n++){
                		count += group.getItems()[n].times.size();
                	}
               
                	seg.writeShort((short)count);
                }else{
                	seg.writeShort((short) items.length);
                }
                //boolean hasTongIsland = tongService.hasTongIsland(player.getTongId());
                for (int i = 0; i < items.length; i++) {
                	int isInTime = items[i].times.size() == 0 ? -1 : 0;//等于-1不是抢购物品，0是抢购物品
                	if(isInTime < 0){
	                    // Light: 特殊分类(短信专区/话费专区)处理，ID传负数，价格无折扣
	                    if (group.getName().contains("短信") || group.getName().contains("话费")) {
	                        seg.writeInt(-items[i].item.getItemId());
	                        seg.writeString(items[i].item.getName());
	                        seg.writeInt(items[i].price);
	                    }
	                    else {
	                        seg.writeInt(items[i].item.getItemId());
	                        seg.writeString(items[i].item.getName());
	                        int tmpPrice = Utils.getDiscountPrice(items[i].price,discount);
	                        if(Server.iMoneyType == Server.IMONEY_TYPE_PIP && items[i].discount != 100 && items[i].discount > 0){
	                        	tmpPrice = Utils.getDiscountPrice(tmpPrice,items[i].discount);
	                        }
	                        seg.writeInt(tmpPrice);
	                    	
	                    }
		                seg.writeInt(items[i].count);
		                seg.write(items[i].item.getQuality()); //added by leo for color for item&equ
		                if(Server.iMoneyType == Server.IMONEY_TYPE_PIP){
		                	seg.writeInt(items[i].discount);
		                }else{
		                	seg.writeInt(100);
		                }
		                seg.writeInt(items[i].price);	//写入原价
		                seg.writeBoolean(items[i].item.newInstance().isBinded());
		                seg.writeString(isInTime + "");
                	}
	                if(isInTime >= 0){
	                    int min = 0;
	            		for(int m = 0;m < items[i].times.size();m++){
		        			seg.writeInt(items[i].item.getItemId());
		                    seg.writeString(items[i].item.getName());
	                        int tmpPrice = items[i].times.get(m).getPrice();
	                        if(Server.iMoneyType == Server.IMONEY_TYPE_PIP && items[i].discount != 100 && items[i].discount > 0){
	                        	tmpPrice = Utils.getDiscountPrice(tmpPrice,items[i].discount);
	                        }
	                        seg.writeInt(tmpPrice);
	                    	String start = items[i].times.get(m).getStart();
	                    	String end = items[i].times.get(m).getEnd();
	                    	Calendar calendarStart = IShopTimeItem.getDate(start);
	                    	Calendar calendarEnd = IShopTimeItem.getDate(end);
	                    	if(System.currentTimeMillis() >= calendarStart.getTimeInMillis()&& System.currentTimeMillis() <= calendarEnd.getTimeInMillis()){		                    	
		                    	long minute =(calendarEnd.getTimeInMillis()- System.currentTimeMillis())/(1000*60);
		                    	if(minute >= 0){   //写入抢购物品数量，在抢购时间内，写入剩余，否则写入0	
		                    		int flag = 0;
		                    		int period =-1;
		                    		if(start.equals("14:00:00")){
		                    			flag = 2;
		                    		}else if(start.equals("10:00:00")){
		                    			flag = 1;
		                    		}else if(start.equals("19:00:00")){
		                    			flag = 3;
		                    		}
		                    		if(NoahsarkConfig.getTimesCountsList().size() != 0){
		                    			//抢购中间重启服务，timesCountsList存在，timesCountsList三种情况，
		                    			//（1.只有此抢购的记录，2.各时间段都有，其他时间段可能为0可能还有库存）
		                    			List<TimesCount> list =  NoahsarkConfig.getTimesCountsList();
                        				for(int n= 0; n< list.size();n ++){                   					
                        					if(items[i].item.getItemId() == list.get(n).getItemId()&& flag == list.get(n).getTimesId()){
                        						period = n;
                        					}                        					
                        				}
                        				//获得list中对应的时间段
                        				if(period >= 0){
                        					if(list.get(period) != null){
                        						if(NoahsarkConfig.getDateLong(new Date()) > list.get(period).getPeriod()){
                        							seg.writeInt(items[i].times.get(m).getCount());
                        						}else{
                            						seg.writeInt(list.get(period).getCounts());
                            					}
                        					}
                        				}else{//只有第一个时间段的，第二个即将开始，服务断掉
                        					seg.writeInt(items[i].times.get(m).getCount());
                        				}
		                    		}else{
		                    			//timesCountsList不存在及未购买，未保存，写入它 的库存数
		                    			seg.writeInt(items[i].times.get(m).getCount());
		                    		}
		                    		min = (int)minute;
		                    		isInTime = min;	
		                    	}
		                    }
		                    else{
		                    	//不在抢购时间段内统统为0
		                    	seg.writeInt(0);
		                    }	
		                    	
                    		seg.write(items[i].item.getQuality()); //added by leo for color for item&equ
                            if(Server.iMoneyType == Server.IMONEY_TYPE_PIP){
                            	seg.writeInt(items[i].discount);
                            }else{
                            	seg.writeInt(100);
                            }
                            seg.writeInt(-1);	//写入原价
                            seg.writeBoolean(items[i].item.newInstance().isBinded());
                            if(System.currentTimeMillis()> NoahsarkConfig.getStartDate().getTime() && System.currentTimeMillis() < NoahsarkConfig.getEndDate().getTime()){
                            	if(isInTime == 0){//在活动时间内，时间段的处理
                            		seg.writeString(start.substring(0, 2) + "-" + end.substring(0,2)+0+"");
                            	}else{
                            		seg.writeString(start.substring(0, 2) + "-" + end.substring(0,2)+" ");
                            	}
                            }else{					//不在活动期间，写入"-2",若不是强购物品直接写入"-1"如上，
                            	seg.writeString(-2+"");
                            }
                    		
                    		isInTime = 0;
		                    		
		                    
	                    }
	            	}
            		
                }
            }
            write(seg);
            
            // 如果这个用户在购买话费物品之前需要模拟下载一次卓望客户端，在这里通知客户端下载
            if (client.cmccDownloadUrl != null && client.getDataVersion() > 0) {
            	seg = new UWAPSegment(ClientConstants.CMCC_EMU_DOWNLOAD, -1, data.getSessionId());
            	seg.writeString(client.cmccDownloadUrl);
            	write(seg);
            	client.cmccDownloadUrl = null;
            }
        }
    }

