	private void isMagicList(UWAPData data) throws Exception {
		WorldPlayer player = getPlayer(data.getSessionId());
		if (player != null) {
			Collection<IStoreGroup> groups = IStoreGroups2.getGroups();
			Client client = sessionId2Clients.get(data.getSessionId());
			groups = filterIshopGroups(client, groups);
			UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL,
					data.getSerial(), data.getSessionId());
			seg.writeShort(ClientConstants.EXTEND_MAGIC_SHOP);
			seg.writeString(player.getAccountName());
			seg.writeInt(player.getMagicIMoney());
			seg.write((byte) groups.size());
			for (IStoreGroup group : groups) {
				seg.writeString(group.getName());
				IStoreItem[] items = group.getItems();
				seg.writeShort((short) items.length);
				for (int i = 0; i < items.length; i++) {
					if (group.getName().contains("工资")) {
						seg.writeInt(-items[i].item.getItemId());
						seg.writeString(items[i].item.getName());
						seg.writeInt(items[i].price);
					} else {

					}
					seg.writeInt(items[i].count);
					seg.write(items[i].item.getQuality());
				}
			}
			seg.writeInt(player.getAllLife());
			write(seg);
		}
	}
	
    private void genericListContent(UWAPData data) throws Exception {
        int index = data.readInt();
        short id = data.readShort();
        if (id == 8) {
            LeaveMessage m = leaveMessageService.getLeaveMessage(index);
            UWAPSegment seg = new UWAPSegment(ClientConstants.GENERIC_LIST_CONTENT, data.getSerial(), data.getSessionId());
            seg.writeString(m.getContent());
            write(seg);
        }else if (id == 4) {
        	IItemTemplate template = Items.getTemplate(index);
            UWAPSegment seg = new UWAPSegment(ClientConstants.GENERIC_LIST_CONTENT, data.getSerial(), data.getSessionId());
            seg.writeString(template.getDesc());
            write(seg);
        }else if (id == 10244){//处理通用列表邮件内容
            Mail mail = mailService.getMail(index);
            if (mail != null) {
            	UWAPSegment seg = new UWAPSegment(ClientConstants.GENERIC_LIST_CONTENT, data.getSerial(), data.getSessionId());
            	StringBuffer stringBuffer = new StringBuffer();
            	stringBuffer.append("发信人：系统\n");
            	stringBuffer.append("标题："+ mail.getTitle() + "\n");
            	byte[] item = mail.getAttachment();//提取附件
            	int itemId = ItemUtils.getAttachementEquId(item);
            	IItem item2 = Items.getTemplate(itemId).newInstance();//获得装备名称。获取价格，返还
            	stringBuffer.append("附件："+ item2.getName() + "\n");
            	stringBuffer.append("内容："+ mail.getContent() + "\n");
            	stringBuffer.append("时间："+ Utils.getDateString(mail.getPostTime()));
            	seg.writeString(stringBuffer.toString());
            	write(seg);
            }else{
            	throw new ITimesException("获取内容错误", data.getSerial(), data.getSessionId(), data.getAppType());
            }
        } else if(id == 10246){
        	//ConcurrentHashMap<Integer, OnlyGiftGroup> onlyGiftGroups = OnlyGiftGroups.getAllOnlyGiftGroup();
        	OnlyGiftGroup onlyGiftGroup = OnlyGiftGroups.getOnlyGiftGroup(index);
        	if(onlyGiftGroup != null){
        		 UWAPSegment seg = new UWAPSegment(ClientConstants.GENERIC_LIST_CONTENT, data.getSerial(), data.getSessionId());
                 seg.writeString(onlyGiftGroup.getMessage_content());
                 write(seg);
        	}else{
        		throw new ITimesException("没有此奖励", data.getSerial(), data.getSessionId(), data.getAppType());
        	}
        } else if(id == 10252){
        	//ConcurrentHashMap<Integer, OnlyGiftGroup> onlyGiftGroups = OnlyGiftGroups.getAllOnlyGiftGroup();
        	Bbs bbs = bbsService.getBbs(index);
        	if(bbs != null){
        		UWAPSegment seg = new UWAPSegment(ClientConstants.GENERIC_LIST_CONTENT, data.getSerial(), data.getSessionId());
        		StringBuffer stringBuffer = new StringBuffer();
        		stringBuffer.append(" 发贴人： " + bbs.getPlayerName());
        		stringBuffer.append("\n 标题： " + bbs.getTitle());
        		stringBuffer.append("\n 内容： " + bbs.getContent());
        		stringBuffer.append("\n 时间："+ Utils.getDateString(bbs.getPostTime()));
            	seg.writeString(stringBuffer.toString());
            	write(seg);
        	}else{
        		 throw new ITimesException("获取内容错误", data.getSerial(), data.getSessionId(), data.getAppType());
        	}
        }else if(id == 10266 || id == 10267){
        	int type = index >>26 & 0x1F;
            int playerId = index & 0x3FFFFFF;
            Map<Integer,VoteShowInfo> voteShowMap= voteService.getVoteContentMap(type);
            if(voteShowMap.containsKey(playerId)){
            	VoteShowInfo voteShowInfo = voteShowMap.get(playerId);
            	UWAPSegment seg = new UWAPSegment(ClientConstants.GENERIC_LIST_CONTENT, data.getSerial(), data.getSessionId());
        		StringBuffer stringBuffer = new StringBuffer();
        		stringBuffer.append("角色名称:    " + voteShowInfo.getPlayerName());
        		stringBuffer.append("\n角色等级:    " + voteShowInfo.getLevel());
        		stringBuffer.append("\n角色公会:    " + voteShowInfo.getTongName());
        		stringBuffer.append("\n参赛宣言:    "+ voteShowInfo.getVoteContent());
            	seg.writeString(stringBuffer.toString());
            	write(seg);
            }else{
            	throw new ITimesException("获取内容错误", data.getSerial(), data.getSessionId(), data.getAppType());
            }
        }else if(id == 10269){
        	int sessionId = data.getSessionId();
        	WorldPlayer player = getPlayer(sessionId);
        	
        	Grid[] grids = player.getEquipments(); 
   			if(grids.length == 0 ){
   			 throw new ITimesException("获取内容错误", data.getSerial(), data.getSessionId(), data.getAppType());
   			}else{
   				//Vector<IEquipment> showGrids = new Vector<IEquipment>();
   				for(int i = 0; i < grids.length ; i++){
   					IEquipment item = (IEquipment) grids[i].item;
   					if(item.getId() == index){
   						UWAPSegment seg = new UWAPSegment(ClientConstants.GENERIC_LIST_CONTENT, data.getSerial(), data.getSessionId());
   						StringBuffer buff = new StringBuffer(200);
	   			        buff.append(item.getName());
	   			        buff.append(' ');
	   			        buff.append(IEquipment.EQUIP_TYPE_NAME[item.getPart()]);
	   			        buff.append('\n');
	   			        if (item.getPart() == IEquipment.PART_WEAPON) {
	   			            buff.append(IEquipment.WEAPON_TYPE_NAME[item.getProperty(IEquipment.
	   			                    EQUIP_ADD_WEAPON_TYPE, player.getLevel())]);
	   			            buff.append(' ');
	   			            buff.append("攻击：");
	   			            buff.append(item.getProperty(IEquipment.EQUIP_ADD_ATTACK_MIN, player.getLevel()));
	   			            buff.append('-');
	   			            buff.append(item.getProperty(IEquipment.EQUIP_ADD_ATTACK_MAX, player.getLevel()));
	   			            buff.append('\n');
	   			        } else {
	   			            buff.append("防御：");
	   			            buff.append(item.getProperty(IEquipment.EQUIP_ADD_DEFENCE, player.getLevel()));
	   			            buff.append('\n');
	   			        }
	   			        int[][] pros = item.getProperties(player.getLevel());
	
	   			        boolean flag = false;
	
	   			        for (int k = 0; k < pros.length; k++) {
	   			            if (pros[k][0] <= IEquipment.EQUIP_ADD_MCRI) {
	   			                buff.append(IEquipment.EQUIP_PROPERTIES_NAME[pros[k][0] - 1]);
	   			                buff.append('：');
	   			                buff.append(pros[k][1]);
	   			                buff.append(' ');
	
	   			                flag = true;
	   			            }
	   			        }
	
	   			        if(flag){
	   			            buff.append('\n');
	   			        }
	
	   			        buff.append("需要等级：");
	   			        buff.append(item.getRequiredLevel());
	   			        buff.append('\n');
	   			        buff.append("售价：");
	   			        buff.append(item.getPrice());
	   			        //return buff.toString();
   						seg.writeString(buff.toString());
   		            	write(seg);
   		            	break;
   					}
   				}
   			}
   			
        }else if(id == 10270){//处理装备兑换多换多mengjie
        	throw new ITimesException("请点击菜单中[兑换]项", data.getSerial(), data.getSessionId(), data.getAppType());
		} else if (id == 10272) {
			int type = index >> 26 & 0x1F;
            int playerId = index & 0x3FFFFFF;
            Map <Integer, VoteKingInfo> kingInfo = voteService.getVotesKingInfo(type);
            if (kingInfo.containsKey(playerId)) {
            	VoteKingInfo votesKing = kingInfo.get(playerId);
            	UWAPSegment seg = new UWAPSegment(ClientConstants.GENERIC_LIST_CONTENT, data.getSerial(), data.getSessionId());
        		StringBuffer stringBuffer = new StringBuffer();
        		stringBuffer.append("角色名称:    " + votesKing.getPlayerName());
        		stringBuffer.append("\n角色等级:    " + votesKing.getLevel());
        		stringBuffer.append("\n角色公会:    " + votesKing.getTongName());
        		stringBuffer.append("\n收费道具票数:    "+ votesKing.getVotes());
            	seg.writeString(stringBuffer.toString());
            	write(seg);
            }else{
            	throw new ITimesException("获取内容错误", data.getSerial(), data.getSessionId(), data.getAppType());
            }
		} else if(id == 10274){	//庄园种子 查看详情
			UWAPSegment seg = new UWAPSegment(ClientConstants.GENERIC_LIST_CONTENT, data.getSerial(), data.getSessionId());
			IItemTemplate item = Items.getTemplate(index);
			if(item != null){
				seg.writeString(item.getDesc());
				write(seg);
			}else{
				throw new ITimesException("获取内容错误", data.getSerial(), data.getSessionId(), data.getAppType());
			}
		}
		else {
            throw new ITimesException("获取内容错误", data.getSerial(), data.getSessionId(), data.getAppType());
        }
    }

    private void requestFriendsList(UWAPData data) throws Exception {
        WorldPlayer player = getPlayer(data.getSessionId());
        if (player != null) {
            Friend[] friends = player.getFriends();
            UWAPSegment seg = new UWAPSegment(ClientConstants.FRIENDS_STATUS,
                                              data.getSerial(),
                                              data.getSessionId());
            seg.write((byte) friends.length);
            long now = new Date().getTime();
            for (int i = 0; i < friends.length; i++) {
                WorldPlayer p = playerService.getWorldPlayer(friends[i].getId());
                boolean online = p != null && p.getState() == WorldPlayer.ONLINE;
                seg.writeInt(friends[i].getId());
                seg.writeBoolean(online);
                seg.writeShort((short) friends[i].getFavorite());
                seg.writeInt(online ? 0 : Utils.getLoginTimeSecond(now, friends[i].getLoginTime()));
            }
            write(seg);
        }
    }

