    private void deleteUser(UWAPData data) throws Exception {
        String userName = data.readString();
        Client client = getClient(data.getSessionId());
        if (client != null && client.status == Client.STATUS.LOGIN) {
            WorldPlayer player = playerService.loadWorldPlayer(userName, client.accountId);

            if (player == null) {
                throw new ITimesException("没有找到角色", data.getSerial(),
                                          data.getSessionId(),
                                          data.getAppType());

            }
            synchronized (player) {
            	if (player.getLevel() >= 70)
                    throw new ITimesException("70级以上的角色不可以删除哦", data.getSerial(),
                            data.getSessionId(),
                            data.getAppType());
                if (player.getTongDuty() == Tong.OWNER)
                    throw new ITimesException("不能删除会长角色", data.getSerial(),
                                              data.getSessionId(),
                                              data.getAppType());
                if (mateService.hasMate(player))
                    throw new ITimesException("必须先解除婚约才能删号", data.getSerial(),
                                              data.getSessionId(),
                                              data.getAppType());
                if (masterService.isMaster(player) || masterService.isPrentice(player))
                    throw new ITimesException("必须先解除师徒关系才能删号", data.getSerial(),
                                              data.getSessionId(),
                                              data.getAppType());
                if (player.getRef() > 0)
                    throw new ITimesException("状态不对，不能删除角色", data.getSerial(),
                                              data.getSessionId(),
                                              data.getAppType());
                //mengjie add 踢出角色后封闭删除角色
                if (playerService.isFrobiden(player.getId())) 
                	throw new ITimesException("该角色隔离中，不可删除", data.getSerial(),
                            data.getSessionId(),
                            data.getAppType());
                
                GameMap map = worldService.getMap(player, player.getMapId(), true);
                if (map != null) {
                    InstanceDefinition instance = worldService.
                            getInstanceDefinition(player.
                            getMapId());
                    if (instance != null) {
                        if(CampBattlefieldConfig.CAMP_BATTLEFIELD_TYPE_RESOURCES.equals(instance.getType())){
	    					throw new ITimesException("该角色正于战场中，不可删除", data.getSerial(),
	                                data.getSessionId(),
	                                data.getAppType());
                        }
                    }
                }
                
                playerService.acquire(player);
                player.setValid(false);
                playerService.savePlayer(player);
                log.info("ID[" + player.getId() + "] deleted");
                //mengjie add
                friendsService.killfriend(player.getId(), -1);
                //mengjie add end
                
                //jwp add
                //删除选举
                //voteService.setForbid(player.getId());
                //jwp add end
                
                //删除角色后删除对应的阵眼排行榜数据
                log.info("ID[" + player.getId() + "] delete MagicPositionRankingInfo try");
                deleteMagicPosPlayerInfo(player);
                
                updataMagicPosInfo();
                log.info("ID[" + player.getId() + "] updata MagicPositionRankingInfo end");
            
            }
            
            tongService.quit(player);
            playerService.release(player);
            
            
            UWAPSegment seg = new UWAPSegment(ClientConstants.DELETE_USER_OK,
                                              data.getSerial(), data.getSessionId());
            write(seg);
        }

    }

