    private void repaire(UWAPData data) throws Exception {
        WorldPlayer player = getPlayer(data.getSessionId());
        int[] repaires = data.readInts();
        int money = 0;
        List used = new ArrayList();
        List unUsed = new ArrayList();
        if (player != null) {
            synchronized (player) {
                for (int i = 0; i < repaires.length / 2; i++) {
                    int itemId = repaires[i * 2];
                    int id = repaires[i * 2 + 1];
                    IEquipment equ = player.getUsedEquipment(itemId, id);
                	if (equ != null) {
                		if (((new Date()).getTime() <= equ.getFAILURE_TIME()) || equ.getFAILURE_TIME() == -1){
	                        used.add(equ);
	                        money += ItemUtils.getRepaireMoney(equ);
                		}else{
//                			sendMessage("(" + equ.getName() + ")这个装备过期喽，不能修啦。",
//                    				data.getSessionId(),
//                    				data.getSessionId());
                			throw new ITimesException("(" + equ.getName() + ")这个装备过期喽，不能修啦。", data.getSerial(),
                                    data.getSessionId(),
                                    data.getAppType());
                		}
                    } else {
                        equ = player.getEquipment(itemId, id);
                        if (equ != null) {
                        	if (((new Date()).getTime() <= equ.getFAILURE_TIME()) || equ.getFAILURE_TIME() == -1){
                        		unUsed.add(equ);
                                money += ItemUtils.getRepaireMoney(equ);
                        	}else{
//                        		sendMessage("(" + equ.getName() + ")这个装备过期喽，不能修啦。",
//                        				data.getSessionId(),
//                        				data.getSessionId());
                        		 throw new ITimesException("(" + equ.getName() + ")这个装备过期喽，不能修啦。", data.getSerial(),
                                         data.getSessionId(),
                                         data.getAppType());
                        	}
                        } else {
                        	Pet[] pets = player.getPets();
                        	for (int j = 0; j<pets.length ; j++){
                        		equ = pets[j].getPetEquipment(itemId, id);
                        		if (equ != null) {
                                	if (((new Date()).getTime() <= equ.getFAILURE_TIME()) || equ.getFAILURE_TIME() == -1){
                                		unUsed.add(equ);
                                        money += ItemUtils.getRepaireMoney(equ);
                                	}else{
//                                		sendMessage("(" + equ.getName() + ")这个装备过期喽，不能修啦。",
//                                				data.getSessionId(),
//                                				data.getSessionId());
                                		throw new ITimesException("(" + equ.getName() + ")这个装备过期喽，不能修啦。", data.getSerial(),
                                                data.getSessionId(),
                                                data.getAppType());
                                	}
                                }
                        	}                            
                        }
                    }
                }
                if (player.getMoeny() < money) {
                    throw new ITimesException("没有足够金钱", data.getSerial(),
                                              data.getSessionId(),
                                              data.getAppType());
                }
                player.setMoeny(player.getMoeny() - money);
                for (int i = 0; i < used.size(); i++) {
                    IEquipment equ = (IEquipment) used.get(i);
                	player.addUsedEquipmentDurability(equ);
                }
                for (int i = 0; i < unUsed.size(); i++) {
                    IEquipment equ = (IEquipment) unUsed.get(i);
                	equ.setCurrentDurability(equ.getDurability());
                }
                UWAPSegment seg = new UWAPSegment(ClientConstants.REPAIRE_OK,
                                                  data.getSerial(),
                                                  data.getSessionId());
                seg.writeInt(money);
                write(seg);
            }
            playerService.checkPlayer(player);
        }
    }

    private void changeOption(UWAPData data) throws Exception {
        short[] option = data.readShorts();
        WorldPlayer player = getPlayer(data.getSessionId());
        
        if (player == null) {
        	return;
        }

        short[] oldOption = player.getOption();
        if (option[0] == 1 && oldOption[0] != 1) { //onlinemode->offlinemode
            removeFromAllChannels(data.getSessionId());
            //设置了免打扰后 从师傅列表中移除
            playerService.removeMasterPlayer(player);
        }
        if (option[0] != 1 && oldOption[0] == 1) { //
            addToChannels(data.getSessionId(), getPlayerChannels(player));
        }
        System.arraycopy(option, 0, oldOption, 0, Math.min(option.length, oldOption.length));
        UWAPSegment seg = new UWAPSegment(ClientConstants.CHANGE_OPTION_OK,
                data.getSerial(),
                data.getSessionId());
		seg.writeShorts(option);
		write(seg);
    }

    private void changeKey9_Option(UWAPData data) throws Exception {
        short optionlength = data.readShort();
        WorldPlayer player = getPlayer(data.getSessionId());
        
        if (player == null) {
        	return;
        }
        int[] key9_option = new int[optionlength];
        for (int i = 0 ; i < optionlength ; i++){
        	key9_option[i] = data.readInt();
        }
        int[] oldOption = player.getKey9_options();
        System.arraycopy(key9_option, 0, oldOption, 0, Math.min(key9_option.length, oldOption.length));
    }
    
    private void getDesc(UWAPData data) throws Exception {
        WorldPlayer player = getPlayer(data.getSessionId());
        if (player != null) {
            byte type = data.readByte();
            int id = data.readInt();
            byte lookType = data.readByte();
            if (type == 1) { //skill
                Recipe recipe = Recipes.getRecipe(id);
                if (recipe == null)
                    throw new ITimesException("没找到指定配方", data.getSerial(),
                                              data.getAppType());
                String desc = "原料：\n";

                TemplateGrid[] resource = recipe.getResources();

                for (int i = 0; i < resource.length; i++) {
                    desc += resource[i].template.getName() + " x " +
                            resource[i].count;

                    if (i < resource.length - 1) {
                        desc += " , ";
                    }
                }

                desc += "\n\n生成：\n";

                TemplateGrid[] product = recipe.getProducts();

                for (int i = 0; i < product.length; i++) {
                    desc += product[i].template.getName() + " x " +
                            product[i].count + "\n";
                    desc += product[i].template.getDesc() + "\n";
                }

                if (lookType == 1) {
                    desc += "\n学习费用：" + recipe.getMoney() + "J";
                }

                UWAPSegment seg = new UWAPSegment(ClientConstants.DESC,
                                                  data.getSerial(),
                                                  data.getSessionId());

                seg.write(type);
                seg.writeString(desc);
                write(seg);
            } else if (type == 2) { //ability
                Ability ability = Ability.getAbility(id);
                if (ability == null)
                    throw new ITimesException("没找到指定技能", data.getSerial(),
                                              data.getAppType());
                UWAPSegment seg = new UWAPSegment(ClientConstants.DESC,
                                                  data.getSerial(),
                                                  data.getSessionId());
                String desc = Utils.getAbilityDesc(lookType, player, ability);
                Client client = sessionId2Clients.get(data.getSessionId());
                if(client != null && client.getDataVersion() > 0){
                	
                }else{
                	if (lookType == 1) {
                        desc += "\n学习费用：" + ability.getPrice() + "J";
                    }
                }
                //去除多余回车
                desc.replaceAll("\n\n","\n"); 
                seg.write(type);
                seg.writeString(desc);
                
                if (client.getDataVersion() > 0) {
                	seg.writeInt(ability.getId());
                }
                write(seg);
            } else if (type == 3) { //item
                if (id < 0) {
                    id = -id;
                }
                IItemTemplate item = Items.getTemplate(id);
                if (item == null)
                    throw new ITimesException("没找到指定物品", data.getSerial(),
                                              data.getAppType());
                UWAPSegment seg = new UWAPSegment(ClientConstants.DESC,
                                                  data.getSerial(),
                                                  data.getSessionId());

                seg.write(type);
                seg.writeString(item.getDesc());
                write(seg);
            }
        }
    }

