    private void requestOemList(UWAPData data) throws Exception {
        WorldPlayer player = getPlayer(data.getSessionId());
        if (player != null) {
            short areaId = data.readShort();
            byte type = data.readByte();
            String name = data.readString();
            short pageSize = data.readShort();
            int pageNo = data.readInt();
            int count = oemService.getCount(areaId, type, name);
            if (pageSize * pageNo > count) {
                throw new ITimesException("没有可显示的求做", data.getSerial(),
                                          data.getSessionId(),
                                          data.getAppType());
            }
            int pageCount = count / pageSize;
            if (count % pageSize != 0)
                pageCount++;
            Oem[] oems = oemService.getOems(areaId, type, name,
                                            pageNo * pageSize,
                                            pageSize);
            UWAPSegment seg = new UWAPSegment(ClientConstants.OEM_LIST,
                                              data.getSerial(),
                                              data.getSessionId());
            seg.write(type);
            seg.writeShort(pageSize);
            seg.writeInt(pageNo);
            seg.writeInt(pageCount);
            seg.writeShort((short) oems.length);
            for (int i = 0; i < oems.length; i++) {
                seg.writeInt(oems[i].getId());
                seg.writeString(oems[i].getName());
                seg.writeShort((short) (oems[i].getTotal() - oems[i].getCurrent()));
                seg.writeInt(oems[i].getPay());
                seg.writeShort((short) oems[i].getWorkPoint());
                Recipe recipe = Recipes.getRecipe(oems[i].getItemId());
                seg.writeBoolean(recipe.getPlayeGame());
                seg.writeBoolean(player.containsRecipe(recipe));
                //modify
                seg.write(oems[i].getQuality());
            }
            write(seg);
        }
    }

    private void addPetPoint(UWAPData data) throws Exception {
        int petId = data.readInt();
        byte[] points = data.readBytes();
        WorldPlayer player = getPlayer(data.getSessionId());
        if (player != null) {
            Pet pet = player.getPet(petId);
            if (pet == null)
                throw new ITimesException("宠物不存在", data.getSerial(),
                                          data.getSessionId(), data.getAppType());
            int allPoint = 0;
            for (int i = 0; i < points.length; i++) {
                if (points[i] < 0) {
                    log.info("ID[" + player.getId() + "]试图加负点");
                    throw new ITimesException("宠物的点数不能为负数", data.getSerial(),
                                              data.getSessionId(),
                                              data.getAppType());
                }

            }
            for (int i = 0; i < points.length; i++) {
                allPoint += points[i];
            }
            if (allPoint > pet.getCurrentPoint()) {
                throw new ITimesException("宠物的点数不足", data.getSerial(),
                                          data.getSessionId(), data.getAppType());
            }
            int vitality = pet.getVitality() + pet.getEnhancevitality() + points[0];
            int strength = pet.getStrength() + pet.getEnhancestrength() + points[1];
            int agility = pet.getAgility() + pet.getEnhanceagility() + points[2];
            int intelligence = pet.getIntelligence() + pet.getEnhanceintelligence() + points[3];
            int maxPoint = pet.getPropertyPoints() * 60 / 100;
            if ((points[0] != 0 && vitality > maxPoint) ||
                (points[2] != 0 && agility > maxPoint) ||
                (points[1] != 0 && strength > maxPoint) ||
                (points[3] != 0 && intelligence > maxPoint))
                throw new ITimesException("此属性不能大于总属性的60％", data.getSerial(),
                                          data.getSessionId(), data.getAppType());
            pet.setVitality(pet.getVitality() + points[0]);
            pet.setStrength(pet.getStrength() + points[1]);
            pet.setAgility(pet.getAgility() + points[2]);
            pet.setIntelligence(pet.getIntelligence() + points[3]);
            pet.setCurrentPoint(pet.getCurrentPoint() - allPoint);
            Changed changed = new Changed();
            changed.addPetProperty(pet, Changed.PET_VITALITY, points[0]);
            changed.addPetProperty(pet, Changed.PET_STRENGTH, points[1]);
            changed.addPetProperty(pet, Changed.PET_AGILITY, points[2]);
            changed.addPetProperty(pet, Changed.PET_INTELLIGENCE, points[3]);
            changed.addPetProperty(pet, Changed.PET_CURRENTPOINT, -allPoint);
            sendGetItem(changed, data.getSerial(), data.getSessionId(),
                        (byte) 20);
            StringBuffer buff = new StringBuffer(100);
            buff.append("Points[");
            for (int i = 0; i < points.length; i++) {
                buff.append(points[i]);
                buff.append(",");
            }
            buff.append("]");
            Utils.log(log, player.getId(), data.getAppType(), buff.toString());
        }
    }

    private void buyPetPoint(UWAPData data) throws Exception {
        int itemId = data.readInt();
        int id = data.readInt();
        int petId = data.readInt();
        WorldPlayer player = getPlayer(data.getSessionId());
        if (player != null) {
            synchronized (player) {
                Pet p = player.getPet(petId);
                if (p.getPoint() <= 0)
                    throw new ITimesException("没有可以兑换的点", data.getSerial(),
                                              data.getSessionId(),
                                              data.getAppType());
                IEquipment equ = player.getEquipment(itemId, id);
                if (equ == null)
                    throw new ITimesException("装备不存在", data.getSerial(),
                                              data.getSessionId(),
                                              data.getAppType());
                //if (Math.abs(p.getLevel() - equ.getLevel()) > 5)
                if (Math.abs(p.getLevel() - equ.getRequiredLevel()) > 5)
                    throw new ITimesException("需要宠物级别上下浮动5级的装备兑换",
                                              data.getSerial(),
                                              data.getSessionId(),
                                              data.getAppType());
                Changed changed = new Changed();
                player.completeRemoveItem(equ, equ.getId(), changed);
                p.setCurrentPoint(p.getCurrentPoint() + 1);
                p.setPoint(p.getPoint() - 1);
                changed.addPetProperty(p, Changed.PET_CURRENTPOINT, 1);
                changed.addPetProperty(p, Changed.PET_POINT, -1);
                sendGetItem(changed, data.getSerial(), data.getSessionId(),
                            (byte) 12);
                Utils.log(log, player.getId(), data.getAppType(),
                          "Equ[" + itemId + "," + id + "]" + "Point[" +
                          p.getCurrentPoint() + "," + p.getPoint() + "]");
            }
            playerService.checkPlayer(player);
        }
    }

