    private void playerUpload(UWAPData data) throws Exception {
        short mapId = data.readShort();
        short x = data.readShort();
        short y = data.readShort();
        byte[] taskSave = data.readBytes();
        boolean logout = data.readBoolean();
        Client client = getClient(data.getSessionId());
        if (client != null) {
            WorldPlayer player = playerService.getWorldPlayer(client.playerId);

            if(player != null){
	            player.setMapId(mapId);
	            player.setX(x);
	            player.setY(y);
	            player.updateTaskSaveData(taskSave);
	            
	            UWAPSegment seg = new UWAPSegment(ClientConstants.
	                                              PLAYRE_UPLOAD_OK,
	                                              data.getSerial(),
	                                              data.getSessionId());
	            if (logout) {
	            	CampData campData = campMainService.getCampData(player.getCamp());
	                if(campData != null){
	                	if(campData.getKingId() == player.getId()){
	                		String campName="";
	                		if(player.getCamp() == 1){
	                			campName = "黑暗";
	                		}else if(player.getCamp() == 2){
	                			campName = "光明";
	                		}
	                		chatService.sendCampMessage(-1, "系统", "威风凛凛的"+campName+"阵营领袖"+player.getPlayerName()+"挥挥衣袖下线了。",player.getCamp());
	                	}
	                }
	                removeClient(client);
	                seg.writeBoolean(true);
	                Utils.log(log, player.getId(), data.getAppType(), null);
	                sendLogoutToAuth(player);
	            } else {
	                seg.writeBoolean(false);
	            }
	            write(seg);
            }else{
            	log.info("ID[" + client.playerId + "]Logout Error Can't find player");
            }
        } else {
//            log.info("ID[" + player.getId() + "]Logout Error Can't find player");
        }
    }

    abstract void sendLogoutToAuth(WorldPlayer player);

    void logout(WorldPlayer player) {
    	
    	if(Server.player_Delay.containsKey(player.getId())){
    		WorldBossEquipInfo info = Server.player_Delay.get(player.getId());
    		
    		Map<IItem, Integer> itemMap = info.getEquDiamondTimeMap();
    		for(Map.Entry<IItem, Integer> equDiamond: itemMap.entrySet()){
    			IItem item = equDiamond.getKey();
         		//扣除物品并通知boss刷新
         		player.completeRemoveItem(item, item.getId(), null);
 				log.info("ID[" + player.getId() + "]logout itemId[" + item.getItemId() + "]");
         		
    		}
    		if(player.isInBattle()){
    			info.setDelayTime(WorldBossEquipInfo.delayBattleFinalTime);
    		}else{
    			info.setDelayTime(WorldBossEquipInfo.delayFinalTime);
    		}
    		info.setOnline(false);
    	}
    	farmInstanceModel.savePlayerFarm(player.getId());
        player.releaseLocks();
        player.setState(WorldPlayer.OFFLINE);
        GameMap map = player.getMap();
        if (map != null) {
            map.removePlayer(player, true);
            Instance instance = map.getInstance();
            if (instance != null && instance instanceof CampBattlefieldInstance) {
            	CampBattlefieldInstance bfInstance = (CampBattlefieldInstance)instance;
            	OfflinePlayer offlinePlayer = new OfflinePlayer(player.getId(), System.currentTimeMillis());
            	bfInstance.addOfflinePlayer(player.getId(), offlinePlayer);
            }
        }
        player.setMap(null);
        
        player.setUnlineOnlineLife(player.calcOnlineLife());
        player.setLastlogoutTime(new Date());
        unRegistry(player);
        if (!playerService.release(player)) {
            synchronized(player){
            	player.reset();
                playerService.savePlayer(player);
            }
            log.info("ID[" + player.getId() + "]Saved Session");
            log.info(player.toString());
        }
      //mengjie add
        try{
        	playerService.toDbPetPracticeTime(player);
        	log.info("ID[" + player.getId() + "] PlayerName[" + player.getPlayerName() + "] toDbPetPracticeTime Saved");
        } catch (Exception ex) {
        	log.info("ID[" + player.getId() + "] PlayerName[" + player.getPlayerName() + "] toDbPetPracticeTime Error");
        	ex.printStackTrace();
        }
        //知己系统释放内存
        friendsService.Modifylevel(player.getId(),player.getLevel());
        friendsService.Removecache(player.getId());
        log.info("ID[" + player.getId() + "]Level[" + player.getLevel() +
        "]Logout----friends_cacheremoved");
//        player.reset();
//        playerService.savePlayer(player.getPlayer());
        
        // 计算本次在线时长，通知认证服务器
        if (accountSkeleton != null) {
            int onlineTime = (int)(System.currentTimeMillis() - player.getLastLoginTime().getTime());
            OnlineTimeNotifyMessage msg = new OnlineTimeNotifyMessage(player.getAccountId(), onlineTime);
            accountSkeleton.send(msg);
        }
        
        //为统计平台计数
        Server.realtimeStatService.logoutCounter++;
    }

    public void sendGetItem(Changed changed, int serial, int sessionId,
                            byte cause) {
    	
    	int playerDataVersion = 0;
    	WorldPlayer player = getPlayer(sessionId);
    	if (player == null){
    		return;
    	}else{
    		playerDataVersion = player.getClientDataVersion();
    	}              
    	
        Object[] os = changed.toClientBytes(playerDataVersion);
        if (os.length > 0) {
            UWAPSegment seg = new UWAPSegment(ClientConstants.GET_ITEM, serial,
                                              sessionId);
            seg.write(cause);
            seg.write((byte) os.length);
            for (int i = 0; i < os.length; i++) {
                seg.write((byte[]) os[i]);
            }
            write(seg);
        }

        //leo add
        Object[] autos = changed.getAutoUseData();

        for(int i = 0; i < autos.length; i++){
            AutoUseData atUse = (AutoUseData)autos[i];

            byte[] bytes = stageService.getTaskBytes((short)atUse.getTaskId(), atUse.getTaskStrings());
            UWAPSegment seg = new UWAPSegment(ClientConstants.GET_FILE_OK, serial, sessionId);
            seg.writeShort((short)atUse.getTaskId());
            seg.writeShort((short)2);
            seg.write(bytes);

            write(seg);
        }
        //leo add end
    }

    private void mailGetAttachment(UWAPData data) throws Exception {
        int mailId = data.readInt();
        WorldPlayer player = getPlayer(data.getSessionId());
        if (player != null) {
        	synchronized (player) {
	        	if( player.getClientDataVersion() > 0){				// 版本号大于0；提供提取1页的附件的功能
	        		Changed changed = new Changed();
		            ArrayList<Integer> lInt = new ArrayList<Integer>();		//mail的ID
		            short pageSize = data.readShort();					// 1页显示的邮件数
		            int pageNo = data.readInt();						// 当前页数
		            String errorString = "没有附件可提取";
	        		try{
	        			if(pageSize > 0){//此时是提取整页的邮件
	        				MailList allMailList = mailService.getMailList(player, pageSize, pageNo);
				            List list = allMailList.getList();  
				            for(int i = 0; i < list.size();i++){			// 分别取出每个附件
				               Mail mail = (Mail) list.get(i);
				               if(mail != null && mail.getSourceId() < 0)
				               {
				            	   byte[] attachment = mail.getAttachment();
					     	       if (attachment != null && attachment.length > 0){		
					     	            	//邮件中没有附件
					     	    	   mailService.getMailAttachment(player,
					     	    			   mail.getId(),changed, true);    
					     	    	  lInt.add(mail.getId());
					     	       }
				                } 
				            }  
	        			}else{//读取单个邮件
	        				mailService.getMailAttachment(player,
		                            mailId,changed, false);
	        				 lInt.add(mailId);
		        		}
	        			}catch(MailException ex)
	        			{
	        				errorString = ex.getMessage();
	        				/*throw new ITimesException(ex.getMessage(), data.getSerial(),
                                data.getSessionId(),data.getAppType());*/
	        			}finally{	 
	        				int[] mailIDs = new int[lInt.size()];
				              for(int i = 0; i < lInt.size(); i ++){
				                mailIDs[i] = lInt.get(i);
				              }
				              sendGetItem(changed, data.getSerial(), data.getSessionId(),			//提取的附件进行传送
		                                (byte) 5);
				              if(mailIDs.length != 0){
				            	  UWAPSegment seg = new UWAPSegment(ClientConstants.
					                         MAIL_GET_ATTACHMENT_OK, data.getSerial(),
					                         data.getSessionId()); 
				            	  seg.writeInts(mailIDs);			//读取的附件的ID，返回客户端
					              write(seg);
					              
					              //是否给提示
					              if(pageSize > 0){
					            	  if(!errorString.equals( "没有附件可提取")){
					            		 sendMessage(errorString, data.getSerial(), data.getSessionId()) ;
					            	  }
					              }
				              }else{
				            	  throw new ITimesException(errorString, data.getSerial(),
			                                data.getSessionId(),data.getAppType());
				              }
				              playerService.checkPlayer(player);
	        			}
	        		}else {
	        			try{
		        			Changed changed = new Changed();
		        			mailService.getMailAttachment(player,
		                            mailId,changed, false);
		                    sendGetItem(changed, data.getSerial(), data.getSessionId(),
		                                (byte) 5);
		                    UWAPSegment seg = new UWAPSegment(ClientConstants.
		                            MAIL_GET_ATTACHMENT_OK, data.getSerial(),
		                            data.getSessionId());
		                    write(seg);
	        			}catch(MailException ex)
	    	        	{
	    	        		throw new ITimesException(ex.getMessage(), data.getSerial(),
	                                data.getSessionId(),data.getAppType());
	    	        	}
	        			playerService.checkPlayer(player);
		            }
            }
            
           
        }
    }

    private void getFile(UWAPData data) throws Exception {
        String model = data.readString();
        short level = data.readShort();
        short type = data.readShort();
        short sequence = data.readShort();
        WorldPlayer player = getPlayer(data.getSessionId());
        Client client = sessionId2Clients.get(data.getSessionId());
        if (player != null) {
            UWAPSegment seg = new UWAPSegment(ClientConstants.GET_FILE_OK,
                                              data.getSerial(),
                                              data.getSessionId());
            seg.writeShort(sequence);
            seg.writeShort(type);
            Map parameters = new HashMap();
            short[] currentTasksId = player.getCurrentTasksId();
            parameters.put("CURRENTTASKS", currentTasksId);
            parameters.put("LEVEL",player.getLevel());
            if (type == 1) {
            	short crc = 0;
            	if(player.getClientDataVersion() > 6){
            		crc = data.readShort();
            	}
                Utils.log(log, player.getId(), data.getAppType(), "下载关卡");
                HouseInstance hi = houseModel.getPreTryHouse(player);
                if (hi != null && ((hi.getDefinition().getMap() >> 4) == sequence)) {
                    HouseData hd = houseModel.getHouseByPlayerId(hi.getOwnerId());
                    parameters.put("playername", hd.getPlayerName());
                    if (hd != null) {
                        HouseTemplate ht = Houses.getHouseTemplate(hd.getLevel(), hd.getStyle());
                        int waiterId = hd.getWaiterId();
                        HouseWaiter waiter = Houses.getWaiter(waiterId);
                        if (waiter != null) {
                            parameters.put("waiternpcid", ht.getWaiterNpcId());
                            parameters.put("waiterimageid", waiter.getImageId());
                        }
                        int[] ps = ht.getVisibleIndexes(hd.getVisibleParts());
                        IntHashSet parts = new IntHashSet(ps.length);
                        for (int i = 0; i < ps.length; i++) {
                            parts.add(ps[i]);
                        }
                        parameters.put("parts", parts);
                    }
                }
                
                FarmInstance fi = farmInstanceModel.getProTryFarm(player);
                if (fi != null && ((fi.getDefinition().getMap() >> 4) == sequence)) {
                    FarmData fd = farmInstanceModel.getFarmData(fi.getOwnerId());
                    parameters.put("playername", fd.getPlayerName());
                }
               
                /*byte[] bytes = stageService.getStageBytes(sequence, parameters,
                        model);*/
                byte[] bytes = stageService.getStageBytesClientDateVersion(sequence, parameters,
                        model, player.getClientDataVersion(), crc);
                if (bytes == null) {
                    throw new Exception("下载错误");
                }
                short[] tasks = (short[]) parameters.get("TASKS");
                if(player.getClientDataVersion() >= 3){
                	//4.4版本 如果是内置包的话，只写脚本数据
                	if(stageService.isInnnerStage(sequence)){
                		/*Map parameters2 = new HashMap();
                		parameters2.put("CURRENTTASKS", currentTasksId);
                		parameters2.put("LEVEL",player.getLevel());*/
                		if(player.getClientDataVersion() > 6){
                			seg.writeBoolean(true);
                		}
                		seg.write(stageService.getInnerPkgBytes(sequence, parameters, model));
                	}else{
                		if(player.getClientDataVersion() > 6){
                			if(crc != 0){
	                			short inCRC = 0;
	                			inCRC = Utils.checkCRC(bytes, inCRC, 0, 12);
	                			inCRC = Utils.checkCRC(bytes, inCRC, 12, bytes.length - 12);
	                			if(inCRC == crc){
	                				seg.writeBoolean(false);
	                				log.info("Stage[" + sequence + "] CheckCRC same");
	                			}else{
	                				seg.writeBoolean(true);
	                				seg.write(bytes);
	                			}
                			}else{
                				seg.writeBoolean(true);
                				seg.write(bytes);
                			}
                    	}else{
                    		seg.write(bytes);
                    	}
                	}
                	//seg.write(bytes);
                }else{
                	if(player.getClientDataVersion() > 6){
            			if(crc != 0){
                			short inCRC = 0;
                			inCRC = Utils.checkCRC(bytes, inCRC, 0, 12);
                			inCRC = Utils.checkCRC(bytes, inCRC, 12, bytes.length);
                			if(inCRC == crc){
                				seg.writeBoolean(false);
                			}else{
                				seg.writeBoolean(true);
                				seg.write(bytes);
                			}
            			}else{
            				seg.writeBoolean(true);
            				seg.write(bytes);
            			}
                	}else{
                		seg.write(bytes);
                	}
                }
                seg.write(player.getTaskSaveData(tasks,
                                                 stageService.
                                                 getTaskFiles(tasks,player.getLevel())));
                String[] names = stageService.getTasksName(currentTasksId,player.getLevel());

                seg.writeShorts(player.getCompletedTasksId(tasks));
                seg.writeShorts(currentTasksId);
                seg.writeStrings(names);
                //1.5增加特殊处理 任务等级下发
//                if(client.getDataVersion() > 0){
//                	short[] Taskslevel = new short[currentTasksId.length];
//                	for (int i = 0;i<Taskslevel.length;i++){
//                		Taskslevel[i] = (short) stageService.getTaskLevel(currentTasksId[i]);
//                	}
//                	seg.writeShorts(Taskslevel);
//                }
                //modify
                seg.writeString(Tips.getTip());
                if(player.getClientDataVersion() >= 3){
                	if(stageService.isInnnerStage(sequence)){
                		seg.write((byte) 1);//读内置关卡
                	}else{
                		seg.write((byte) 0);
                	}
                }else{
                	seg.write((byte) 0);
                }
                write(seg);
                Utils.log(log, player.getId(), data.getAppType(), "下载关卡成功");
                
                
                //如果是重新上线的话服务器push ui监听。。
                if(client.getDataVersion() > 0){
                	if(player.isIsFirstEnter()){
	                	Map taskUImap = TaskHelpManager.taskHelpMap;
	                	Vector taskHelpVector = new Vector();
	                    for(int i = 0; i < currentTasksId.length; i++){
	                    	if(taskUImap.containsKey(currentTasksId[i])){
	                    		taskHelpVector.add((TaskHelp) taskUImap.get(currentTasksId[i]));
	                    	}
	                    	
	                    }
	                    if(taskHelpVector.size() > 0){
	                    	seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL);
		              		seg.writeShort(ClientConstants.EXTEND_PROTOCOL_LISTENUI);
		              	    seg.writeBoolean(true);
		              	    seg.writeInt(taskHelpVector.size());
		              	    for(int k = 0; k < taskHelpVector.size(); k++){
		              	    	
		              	    	TaskHelp taskHelp = (TaskHelp) taskHelpVector.get(k);
			              	    seg.writeString(taskHelp.getUiName());
			              	    //seg.writeString((String) taskUImap.get(sequence));
			              	    seg.writeShort(taskHelp.getTaskId());
		              	    }
		              	    connectService.writeTo(seg, player.getId());
	                    	
	                    }
                	}
                }
            } else if (type == 2) {
                if (!(model.equals("NK-40-2") || model.equals("MotoV300")))
                    seg.forceCompress();
                byte[] bytes = stageService.getTaskBytes(sequence,player.getLevel());
                if (bytes == null)
                    throw new Exception("下载错误");
                if (sequence < 30000) {
                    int lvl = stageService.getTaskLevel(sequence);
//                    if(true){
                    if (lvl != 0 && lvl - 5 > player.getLevel()) {
                    	String tmpstr = String.valueOf(lvl-5);
                        sendMessage("您到了"+tmpstr+"级才可以接这个任务。", data.getSerial(), data.getSessionId());
                        return;
//                        throw new ITimesException("您到了"+tmpstr+"级才可以接这个任务。", data.getSerial(), data.getSessionId(), data.getAppType());
//                    if(lvl!=0&&lvl-5>player.getLevel()){
//                        throw new ITimesException("你的等级不够",data.getSerial(),data.getSessionId(),data.getAppType());
                    }
                    //mengjie add 毒瘤！
                    if ((sequence == 29802) || 
                    	(sequence == 29804) || 
                    	(sequence == 29806) ||
                    	(sequence == 29808) ||
                    	(sequence == 29810)){
                    	//光明
                    	if (player.getCamp() != 2){
                    		sendMessage("您不是光明阵营的成员，不可以接这个任务。", data.getSerial(), data.getSessionId());
                            throw new ITimesException("您不是光明阵营的成员，不可以接这个任务。", data.getSerial(), data.getSessionId(), data.getAppType());
                    	}
                    }else if ((sequence == 29803) || 
                        	(sequence == 29805) || 
                        	(sequence == 29807) ||
                        	(sequence == 29809) ||
                        	(sequence == 29811)){
                    	//黑暗
                    	if (player.getCamp() != 1){
                    		sendMessage("您不是黑暗阵营的成员，不可以接这个任务。", data.getSerial(), data.getSessionId());
                            throw new ITimesException("您不是黑暗阵营的成员，不可以接这个任务。", data.getSerial(), data.getSessionId(), data.getAppType());
                    	}
                    }
                    //mengjie add 重复任务特殊处理
                    if (LoopTasks.LoopTaskbyTaskid.containsKey(sequence)){//是重复任务
                    	if(player.hasCompleteTask(sequence)){
                    		LoopTasks loopTaskstmp = player.getCompletedLoopTask(sequence);
                    		Date lastfinishdate = loopTaskstmp.getLastfinishtime();
                    		if (lastfinishdate != null){
                    			Calendar callast = Calendar.getInstance();
                        		callast.setTime(lastfinishdate);
                        		Date now = new Date();
                        		Calendar calnow = Calendar.getInstance();
                        		calnow.setTime(now);
                        		
                        		if ((loopTaskstmp.getTime() == 24) && //循环周期24小时
                        				((callast.get(Calendar.DAY_OF_MONTH) == calnow.get(Calendar.DAY_OF_MONTH)) && 
                        				(callast.get(Calendar.YEAR) == calnow.get(Calendar.YEAR)) && 
                        				(callast.get(Calendar.MONTH) == calnow.get(Calendar.MONTH))) && //上次完成就是当天。
                        				(loopTaskstmp.getLoops() == 1) //循环次数为1次
                        				){
                        				log.info("ID["+player.getId()+"][AssignLoopsTaskError]["+sequence+"]-kill1");
                        				sendMessage(player.getId(), "今天您不能再接这个任务了。");
                                    	throw new ITimesException("今天您不能再接这个任务了。", data.getSerial(), data.getSessionId(), data.getAppType());
                    			}
                    		}
                        }
                    	ArrayList loopTaskstmplist = LoopTasks.LoopTaskbygroupid.get(LoopTasks.LoopTaskbyTaskid.get(sequence).getGroup());
                    	for(int i=0;i<loopTaskstmplist.size();i++){
                    		LoopTasks loopTaskstmp = (LoopTasks) loopTaskstmplist.get(i);
                    		//同组每日任务不能同时接
                    		if (player.hasCurrentTasks(loopTaskstmp.getTaskid())){
                    			log.info("ID["+player.getId()+"][AssignLoopsTaskError2]["+sequence+"]");
                				sendMessage(player.getId(), "每日任务要一个一个的做，请您先做完已经接到的任务。谢谢。");
                            	throw new ITimesException("今天您不能再接这个任务了。", data.getSerial(), data.getSessionId(), data.getAppType());
                    		}
                    		//每日前置任务筛选
                    		if((loopTaskstmp.getTaskid() == sequence) && 
                    				(loopTaskstmp.getPreTask() != loopTaskstmp.noPreTask)){//每日任务后面有跟随的任务
            					//判断前置任务是否已经完成了
            					if((short) loopTaskstmp.getPreTask() != loopTaskstmp.preTaskStart ){
            						if(player.hasCompleteTask((short) loopTaskstmp.getPreTask())){
                						LoopTasks loopPreTask = player.getCompletedLoopTask((short) loopTaskstmp.getPreTask());
                						if( !(loopPreTask.getLastfinishtime().getTime() > Utils.getTodayStart())){//是今天完成的
                							log.info("ID["+player.getId()+"][AssignPreLoopsTaskTimeError]["+sequence+"]");
	                        				sendMessage(player.getId(), "前置任务必须在今天完成");
	                                    	throw new ITimesException("前置任务必须在今天完成", data.getSerial(), data.getSessionId(), data.getAppType());
                						}
            						}else{
            							log.info("ID["+player.getId()+"][AssignPreLoopsTaskTimeError]["+sequence+"]");
                        				sendMessage(player.getId(), "前置任务必须在今天完成");
                                    	throw new ITimesException("前置任务必须在今天完成", data.getSerial(), data.getSessionId(), data.getAppType());
            						}
            					}else {
            						if(player.hasCompleteTask((short) loopTaskstmp.getTaskid())){
                						LoopTasks loopPreTask = player.getCompletedLoopTask((short) loopTaskstmp.getTaskid());
                						if( !(loopPreTask.getLastfinishtime().getTime() > Utils.getTodayStart())){//是今天完成的
                							log.info("ID["+player.getId()+"][AssignPreLoopsTaskTimeError]["+sequence+"]");
	                        				sendMessage(player.getId(), "前置任务必须在今天完成");
	                                    	throw new ITimesException("前置任务必须在今天完成", data.getSerial(), data.getSessionId(), data.getAppType());
                						}
            						}

            					}
            						/*log.info("ID["+player.getId()+"][AssignPreLoopsTaskError]["+sequence+"]");
                    				sendMessage(player.getId(), "请先完成前置任务");
                                	throw new ITimesException("请先完成前置任务。", data.getSerial(), data.getSessionId(), data.getAppType());*/
            				}
                    	}
                    }else if (sequence == 26901){//滑雪的特殊处理
                    	player.removecompletedTask((short) 26901);
                    }else {//不是重复任务
                    	if(player.hasCompleteTask(sequence)){
                        	log.info("ID["+player.getId()+"][AssignTaskError]["+sequence+"]");
                        	throw new ITimesException("不能接任务", data.getSerial(), data.getSessionId(), data.getAppType());
                        }
                    }
                    player.addTask(sequence);
                    player.resetCurrentTasks();
//                    playerService.savePlayer(player);
                    seg.write(bytes);
                    seg.writeShorts(player.getCompletedTasksId(sequence));
                    seg.writeShorts(player.getCurrentTasksId(sequence));
                    write(seg);
                    Utils.log(log, player.getId(), data.getAppType(),
                              "AddedTask[" + sequence + "]");
                    if(client.getDataVersion() > 0){
                    	putTaskDetails(2,player,sequence,data.getSerial(),data.getSessionId());
                    	
                    	//jwp add 此刻是接任务的时候，下发给客户端让客户端监听任务相关ui 后续为ui模拟
                    	Map taskUImap = TaskHelpManager.taskHelpMap;
                    	if(taskUImap.containsKey(sequence)){
                    		seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL);
    	              		seg.writeShort(ClientConstants.EXTEND_PROTOCOL_LISTENUI);
    	              	    seg.writeBoolean(true);
    	              	    seg.writeInt(1);
    	              	    TaskHelp taskHelp = (TaskHelp) taskUImap.get(sequence);
    	              	    seg.writeString(taskHelp.getUiName());
    	              	    //seg.writeString((String) taskUImap.get(sequence));
    	              	    seg.writeShort(sequence);
    	              	    connectService.writeTo(seg, player.getId());
                    	}

                    }
                } else {
                    seg.write(bytes);
                    write(seg);
                }
            } else if (type == 3 || type == 4 || type == 5) {
                PngResourceData resource = stageService.getPng(type, sequence);
                if (resource == null)
                    throw new Exception("下载错误");
                seg.write(resource.png);
                seg.write(resource.desc);
                write(seg);
			}else if(type == 6){//请求下载pip图片
				short ctnType = data.readShort();
				String[] pipImageString = data.readStrings();
				seg.writeShort(ctnType);
				seg.writeShort((short) pipImageString.length);
				for(int i = 0; i < pipImageString.length; i++){	
					seg.writeString(pipImageString[i]);
					seg.write(stageService.getPip(ctnType, pipImageString[i]));
				}
				write(seg);
			}else if(type == 7){//请求下载动画ctn
				short ctnType = data.readShort();
				String ctnName = data.readString();
				seg.writeShort(ctnType);
				if(stageService.getCtn(ctnType, ctnName) == null){
					throw new Exception("下载错误");
				}
				seg.writeString(ctnName);
				seg.write(stageService.getCtn(ctnType, ctnName));
				write(seg);
			}/* else if (type == 6) {// 人物形象
				
				 * PngResourceData resource = stageService.getPng(type,
				 * sequence); if (resource == null) throw new Exception("下载错误");
				 * seg.write(resource.png); seg.write(resource.desc);
				 * write(seg);
				 
				short face = sequence;
				seg.write((byte) 1);

				seg.writeShort((short) face);

				RoleFaceData d = RoleFaces.getRoleFace(face);
				seg.write((byte) 0);
				seg.write(d.getWalk().getPfile());
				seg.write(d.getWalk().getSfile());
				seg.write((byte) 1);
				seg.write(d.getBattle().getPfile());
				seg.write(d.getBattle().getSfile());
				seg.write((byte) 2);
				seg.write(d.getPortrait().getPfile());
				seg.write(d.getPortrait().getSfile());
				seg.write((byte) 3);
				seg.write(d.getEffect().getPfile());
				seg.write(d.getEffect().getSfile());
				write(seg);
			}*/
        }

    }


    private void pkFight(UWAPData data) throws Exception {
        int pkId = data.readInt();
        WorldPlayer player = getPlayer(data.getSessionId());
        
        if(player != null && player.inArenaBattle){
            Server.instance.arenaSession.battleFight(data, player);
        }else{
            Battle2 battle = battleService.getBattle(pkId);
            
            if (battle != null && player != null) {
                battle.process(data, player.getId());
            }
        }
    }

