    private boolean ForcePk(WorldPlayer self,WorldPlayer tagert){
    	 boolean isforcePk = false;
    	 if(battleService.inBattle(tagert) || battleService.inPkRequesters(tagert) || tagert.inArenaBattle){
    		 isforcePk = false;
    	 }else{
    		 long limitTime = 60 * 60 * 1000L;
    		 long oldTime = self.getForcePkClock().getTime();
    		 if(System.currentTimeMillis() - oldTime > limitTime){//每1小时
    			isforcePk = true;
    		 }else{
    			 isforcePk = false;
    		 }
    	 }
    	 return isforcePk;
    }
    
    /**
     * 
     *
     * @param data UWAPData
     * @throws Exception
     */
    private void pkRequest(UWAPData data) throws Exception {
        int srcId = data.readInt();
        String name = data.readString();
        int targetId = data.readInt();
        short level = data.readShort();
        short wager = data.readShort();
        WorldPlayer p1 = getPlayer(data.getSessionId());
        WorldPlayer p2 = playerService.getWorldPlayer(targetId);
        if(Math.abs(p1.getLasPkRequestTime() - System.currentTimeMillis()) < 15000){
        	//sendMessage(p1.getId(), "你邀请pk的时间太短，休息一会再要求pk吧！");
        	UWAPSegment seg = new UWAPSegment(ClientConstants.PK_REFUSE,
                     data.getSerial(), data.getSessionId());
            seg.write((byte) 0);
            seg.writeString("你邀请pk过于频繁，休息一会再要求pk吧！");
            seg.writeInt(0);
            write(seg);
        	return;
        }else{
        	p1.setLasPkRequestTime(System.currentTimeMillis());
        }
        if (wager <= 0) {
            throw new ITimesException("赌注不能小于0", data.getSerial(),
                                      data.getSessionId(), data.getAppType());
        }
        if (wager >= 0) {
            if (p1 != null && p1.online() && p2 != null && p2.online()) {
                if (wager > 0) {
                    if (p1.getMoeny() < wager) {
                        UWAPSegment seg = new UWAPSegment(ClientConstants.PK_REFUSE,
                                data.getSerial(), data.getSessionId());
                        seg.write((byte) 0);
                        seg.writeString("没有足够的金钱");
                        seg.writeInt(0);
                        write(seg);
                        return;
                    }
                    if (p2.getMoeny() < wager) {
                        UWAPSegment seg = new UWAPSegment(ClientConstants.PK_REFUSE,
                                data.getSerial(), data.getSessionId());
                        seg.write((byte) 0);
                        seg.writeString("对方没有足够的金钱");
                        seg.writeInt(0);
                        write(seg);
                        return;
                    }
                }
                if (p2.offlinemode() || robotService.isRobot(p2)) {
                    UWAPSegment seg = new UWAPSegment(ClientConstants.PK_REFUSE,
                            data.getSerial(),
                            data.getSessionId());
                    seg.write((byte) 0);
                    seg.writeString("对方拒绝");
                    seg.writeInt(0);
                    write(seg);
                    return;
                }
                if (!canPk(p1)) {
                    UWAPSegment seg = new UWAPSegment(ClientConstants.PK_REFUSE,
                            data.getSerial(),
                            data.getSessionId());
                    seg.write((byte) 0);
                    seg.writeString("状态错误");
                    seg.writeInt(0);
                    write(seg);
                    return;
                }
                if (!canPk(p2)) {
                    UWAPSegment seg = new UWAPSegment(ClientConstants.PK_REFUSE,
                            data.getSerial(),
                            data.getSessionId());
                    seg.write((byte) 0);
                    seg.writeString("对方状态错误");
                    seg.writeInt(0);
                    write(seg);
                    return;
                }
                if (!p1.inPkMap()) {
                    UWAPSegment seg = new UWAPSegment(ClientConstants.PK_REFUSE,
                            data.getSerial(),
                            data.getSessionId());
                    seg.write((byte) 0);
                    seg.writeString("此地图不允许PK");
                    seg.writeInt(0);
                    write(seg);
                    return;
                }
                if (!p2.inPkMap()) {
                    UWAPSegment seg = new UWAPSegment(ClientConstants.PK_REFUSE,
                            data.getSerial(),
                            data.getSessionId());
                    seg.write((byte) 0);
                    seg.writeString("对方地图不允许PK");
                    seg.writeInt(0);
                    write(seg);
                    return;
                }
                try {
                    battleService.addPkRequester(p1, p2, data.getSerial(), wager,false);
                } catch (BattleException ex) {
                    UWAPSegment seg = new UWAPSegment(ClientConstants.PK_REFUSE,
                            data.getSerial(),
                            data.getSessionId());
                    seg.write((byte) 0);
                    seg.writeString(ex.getMessage());
                    seg.writeInt(0);
                    write(seg);
                    return;
                }
            }
            if (p2 == null || !p2.online()) {
                if (p1 != null) {
                    UWAPSegment seg = new UWAPSegment(ClientConstants.PK_REFUSE,
                            data.getSerial(),
                            data.getSessionId());
                    seg.write((byte) 2);
                    seg.writeString("目标不存在");
                    seg.writeInt(0);
                    connectService.writeTo(seg, p1.getId());
                } else {
                    log.info("ID[" + p1.getId() + "]Name[" + name + "]Wager[" + wager +
                             "]PkError");
                }
            }
        }
    }


    private boolean canPk(WorldPlayer player) {
        Team team = player.getTeam();
        if (team == null)
            return true;
        if (team.getLeader() == player)
            return true;
        if (player.getTeamState() == WorldPlayer.TEAM_NORMAL)
            return true;
        return false;
    }


    private void battleFight(UWAPData data) throws Exception {
        int pkId = data.readInt();
        WorldPlayer player = getPlayer(data.getSessionId());
        Battle2 battle = battleService.getBattle(pkId);
        if (battle != null && player != null) {
            battle.process(data, player.getId());
        }else {
            if (player != null) {
                UWAPSegment seg = new UWAPSegment(ClientConstants.BATTLE_ABORT,
                                                  data.getSerial(),
                                                  data.getSessionId());
                seg.writeInt(pkId);
                seg.writeInt(player.getHp());
                seg.writeInt(player.getMp());
                Pet pet = player.getPet();
                seg.writeInt(pet == null ? -1 : pet.getHp());
                seg.writeInt(pet == null ? -1 : pet.getMp());
                write(seg);
            }
        }
    }

