    private void phizChange(UWAPData data) throws Exception{
    	byte type = data.readByte();	//表情类型
    	byte state = data.readByte();	//表情状态
    	WorldPlayer player = getPlayer(data.getSessionId());
    	if(player != null){
	    	switch(type){
	    	case PhizService.PHIZ_TYPE_BATTLE:				//战斗表情
	    		player.setBattle(true);
	    		phizService.addChangePhiz(player, PhizService.PHIZ_TYPE_BATTLE, PhizService.PHIZ_STATE_DEFAULT);
	    		break;
	    	case PhizService.PHIZ_TYPE_PHIZTITLE: //表情称号
	    		if(state == 1){//获取表情称号列表
	    			UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
	            	seg.writeShort(ClientConstants.EXTEND_FACE);
	            	seg.write(PhizService.PHIZ_TYPE_PHIZTITLE);
	            	seg.write((byte)1); //下发表情称号列表
	    			seg.writeShort((short)PhizTitleData.getPhizMapSize());//全部表情的数量
	            	ArrayList phizTitle = (ArrayList)player.getPhizTitleList();
	    			seg.writeShort((short)phizTitle.size());//玩家拥有的表情数量
	    			if(phizTitle.size() > 0){//
	    				for(int i = 0;i<phizTitle.size();i++){
	    					PhizTitleData phiz = (PhizTitleData)phizTitle.get(i);
	    					seg.write((byte)1);
	    					seg.writeShort(phiz.getIndex());
	    					seg.writeString(phiz.getName());
	    				}
	    			}
	    			if(phizTitle.size() < PhizTitleData.getPhizMapSize()){
		    			HashMap playerPhiz = player.getPhizTitleMap();
		    			Iterator iter = PhizTitleData.getPhizMapIterator();
		    			while(iter.hasNext()){
		    				Map.Entry<Short, PhizTitleData> entry =(Map.Entry<Short, PhizTitleData>) iter.next();
		    				if(playerPhiz.size() == 0 || !playerPhiz.containsKey(entry.getKey())){
		    					PhizTitleData tmpPhiz = entry.getValue();
		    					seg.write((byte)0);
		    					seg.writeShort(tmpPhiz.getIndex());
		    					seg.writeString(tmpPhiz.getName());
		    				}
		    			}
	    			}
	    			write(seg);
	    		}else if(state == 2){//更换表情
	    			short index = data.readShort();
	    			if(index == 0 && player.getPhizTitleIndex() == 0){
	    				throw new ITimesException("您当前没有设置表情称号。",data.getSerial(),data.getSessionId(),data.getAppType());
	    			}else if(index == player.getPhizTitleIndex()){
	    				throw new ITimesException("您已经是"+ player.getPhizTitleName()+"表情了，无需更换！",data.getSerial(),data.getSessionId(),data.getAppType());
	    			}
	    			if(index > 0 && !player.hasPhizTitle(index)){
	    				throw new ITimesException("没有该表情，无法更换。",data.getSerial(),data.getSessionId(),data.getAppType());
	    			}
	    			Changed changed = new Changed();
	    			player.setPhizTitleIndex(index);
	    			changed.setProperty(Changed.PHIZTITLE, index);
	    			connectService.sendGetItem(changed, player.getId(),(byte) 0);
	    			if(index == 0){
	    				sendMessage(player.getId(), "已取消当前表情称号。");
	    			}else{
	    				sendMessage(player.getId(), "更换表情成功！");
	    			}
	    			UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
	            	seg.writeShort(ClientConstants.EXTEND_FACE);
	            	seg.write(PhizService.PHIZ_TYPE_PHIZTITLE);
	            	seg.write((byte)2); //更换表情
	            	seg.writeShort(index);
	            	write(seg);
	            	phizService.addChangePhiz(player, player.getPhizTitleType(), player.getPhizTitleIndex());
	    		}
	    		break;
	    	}
    	}
    }
    
    /**
     * 阵营战场相关
     * @param data
     * @throws Exception
     */
    private void extend_camp_battlefield_related (UWAPData data) throws Exception {
    	byte actionType = data.readByte();
    	WorldPlayer player = getPlayer(data.getSessionId());
    	if (player != null) {
	    	switch (actionType) {
	    	case CampBattlefieldConfig.ACTION_REQUEST_NAME:
	    		actionRequestName(data);
	    		break;
	    	case CampBattlefieldConfig.ACTION_REQUEST_DESC:
	        	// 战场名称
	        	String name = data.readString();
	    		actionRequestDesc(name, player, data);
	    		break;
	    	case CampBattlefieldConfig.ACTION_REQUEST_JOIN:
	    		// 是否是随机加入
	        	boolean isRandom = data.readBoolean();
	        	// 战场名字
	        	name = data.readString();
	    		actionRequestJoin(name, isRandom, player);
	    		break;
	    	case CampBattlefieldConfig.ACTION_VIEW_SHOP:
	    		actionViewShop(player, data);
	    		break;
	    	case CampBattlefieldConfig.ACTION_SHOP_ITEM:
	    		int groupID = data.readInt();
	    		actionViewItem(player, data, groupID);
	    		break;
	    	case CampBattlefieldConfig.ACTION_BUY_ITEM:
	    		groupID = data.readInt();
	    		int itemID = data.readInt();
	    		int count = data.readInt();
	    		actionBuyItem(player, data, groupID, itemID, count);
	    		break;
	    	case CampBattlefieldConfig.ACTION_LEAVE_QUEUE:
	        	// 战场名字
	        	name = data.readString();
	        	actionRequestLeave(name, player);
	    		break;
	    	}
    	}
    }
    
    private void extend_inCamp_Battlefield_related (UWAPData data) throws Exception {
    	byte actionType = data.readByte();
    	switch (actionType) {
    	case CampBattlefieldConfig.ACTION_GOTO_BATTLEFIELD:
    		goToBattlefield(data);
    		break;
    	case CampBattlefieldConfig.ACTION_BATTLEFIELD_WAR:
    		inBattlefieldPKOk(data);
    		break;
    	case CampBattlefieldConfig.ACTION_GIVEUP_BATTLEFIELD:
    		giveUpCampBattlefield(data);
    		break;
    	}
    }
    
    private void goToBattlefield (UWAPData data) throws Exception {
    	int ID = data.readInt();
    	WorldPlayer player = getPlayer(data.getSessionId());
    	if (player != null) {
    		if (player.getCamp() != Utils.CAMP_BRIGHT && player.getCamp() != Utils.CAMP_DARK) {
    			sendMessage("无法进入阵营战场。请选择一个阵营后再进入战场。", data.getSerial(), data.getSessionId());
    		} else {
    			int battleID = -1;	//默认为没有战斗 当读取不到战斗状态时 默认可以进战场
    			try{
    				battleID = data.readInt();
    			}catch(Exception e){
    				log.info("goToBattlefield battleID read error playerID[" + player.getId() + "]");
    			}
    			Instance instance = worldService.gotoBattlefieldInstance(ID, player, battleID);
    			if (instance != null) {
    				Team team = player.getTeam();
    				if(team != null){
    					PositionSprite[] ps = team.getPlayers();
    					for(int i=0; i<ps.length; i++){
    						if(ps[i] instanceof MercenaryPlayer){
    							MercenaryPlayer mp = (MercenaryPlayer)ps[i];
    							if(player.containsMercenary(mp)){
    								player.removeMercenary(mp);
    								leaveTeam(mp);
    								Mercenary m = mp.getMercenaryShop().getMercenary();
    								m.setState(Mercenary.STATE_SLEEP);
    								mercenaryService.saveMercenary(m);
    								mercenaryService.removeMercenaryPlayer(mp.getId());
    								positionService.unRegistry(mp);
    							}
    						}
    					}
    				}
    				
    				InstanceDefinition idf = instance.getDefinition();
    				sendGotoMap(player.getId(), idf.getMap(), idf.getX(), idf.getY());
    				int hp = player.getHp();
    				int mp = player.getMp();
    				player.adjustProperty();
    				player.repairOldVersionHpMp(player.getClientDataVersion());
    				int maxHp = player.getMaxHp();
    				int maxMp = player.getMaxMp();
    				player.setHp(maxHp);
    				player.setMp(maxMp);
    				Changed changed = new Changed();
    				changed.addProperty(Changed.HP, maxHp);
    				changed.addProperty(Changed.MP, maxMp);
    				Pet p = player.getPet();
    				if (p != null) {
    					int petHp = p.getHp();
    					int petMp = p.getMp();
    					int petMaxHp = p.getMaxHp();
    					int petMaxMp = p.getMaxMp();
    					p.setHp(petMaxHp);
    					p.setMp(petMaxMp);
    					changed.addPetProperty(p, Changed.PET_HP, petMaxHp);
    					changed.addPetProperty(p, Changed.PET_MP, petMaxMp);
    				}
    				sendGetItem(changed, data.getSerial(),
    						data.getSessionId(), (byte) 5);
    				Utils.log(log, player.getId(), data.getAppType(),
    						"GotoInstance[" + idf.getId() + "]");
    			}
    		}
    	}
    }
    
    private void inBattlefieldPKOk(UWAPData data) throws Exception {
        int pkID = data.readInt();
        WorldPlayer player = getPlayer(data.getSessionId());
        if (player != null) {
        	battleService.battlefieldPKSucceed(player, pkID);
        }
    }
    
    private void giveUpCampBattlefield(UWAPData data) throws Exception {
        WorldPlayer player = getPlayer(data.getSessionId());
        if (player != null) {
        	if (campBattlefieldService.containsDraggedPlayers(player.getId())) {
        		CampBattlefieldPlayer cbPlayer = campBattlefieldService.getDraggedPlayer().get(player.getId());
				campBattlefieldService.removeWaitingPlayer(cbPlayer.getName(), cbPlayer.getLevelType(), player.getId(), player.getCamp());
				campBattlefieldService.getDraggedPlayer().remove(player.getId());
			}
        	Changed changed = new Changed();
        	player.decCredit(10, changed);
        	sendGetItem(changed, data.getSerial(),
                    data.getSessionId(), (byte) 22);
        }
    }
    
    private void actionRequestName (UWAPData data) {
    	if (CampBattlefieldConfig.battlefieldName != null) {
    		UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
			seg.writeShort(ClientConstants.EXTEND_CAMP_BATTLEFIELD_RELATED);
			seg.write(CampBattlefieldConfig.ACTION_REQUEST_NAME);
			byte length = (byte) CampBattlefieldConfig.battlefieldName.size();
			seg.write(length);
			for (int i = 0; i < length; i++) {
				seg.writeString(CampBattlefieldConfig.battlefieldName.get(i));
			}
			write(seg);
    	}
    }
    
    private void actionRequestDesc (String name, WorldPlayer player, UWAPData data) {
    	CampBattlefield campBattlefield = CampBattlefieldConfig.battlefields.get(name);
    	if (campBattlefield != null) {
    		String sendDetails = CampBattlefieldConfig.getSendDetails(name, player, campBattlefield, campBattlefieldService);
    		UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
			seg.writeShort(ClientConstants.EXTEND_CAMP_BATTLEFIELD_RELATED);
			seg.write(CampBattlefieldConfig.ACTION_REQUEST_DESC);
			seg.writeString(sendDetails);
			seg.writeString(campBattlefield.getName());
			write(seg);
    	}
    }
    
    private void actionRequestJoin (String name, boolean isRandom, WorldPlayer player) {
		long results = campBattlefieldService.addBattlefieldPlayer(name, player, System.currentTimeMillis(), isRandom);
		if (results > 0) {
			int seconds_all = (int) (results / Utils.UNIT_OF_SECOND);
			int second = seconds_all % 60;
			int minute_all = seconds_all / 60;
			if (second > 59) {
				second = 0;
				minute_all = minute_all + 1;
			}
			String msg = "";
			if (minute_all > 0) {
				msg = msg + minute_all + "分钟";
			}
			if (second > 0 || (minute_all == 0 && second == 0)) {
				msg = msg + second + "秒";
			}
			sendMessage(player.getId(), "加入失败，您还要再等待" + msg + "才能再次排战场。");
		} else if (results == CampBattlefieldConfig.SUCCESS_QUEUED) {
			sendMessage(player.getId(), "您已进入战场队列，请耐心等候其他玩家，您可以在排队期间进行其他活动。");
		} else if (results == CampBattlefieldConfig.ERROR_WITHOUT_BATTLEFIELD) {
			sendMessage(player.getId(), "加入失败，此战场未开放。");
		} else if (results == CampBattlefieldConfig.ERROR_READY_IN_QUEUE) {
			sendMessage(player.getId(), "您已在队列中，请不要重复排队。");
		} else if (results == CampBattlefieldConfig.ERROR_READY_IN_INSTANCE
				|| results == CampBattlefieldConfig.ERROR_ON_WORLD_MAP) {
			sendMessage(player.getId(), "您所在的区域无法加入战场。");
		} else if (results == CampBattlefieldConfig.ERROR_NO_CAMP) {
			sendMessage(player.getId(), "加入失败，阵营战场很危险，你还没有阵营，无法参加该战场，去巨兽裂谷加入阵营吧！光明和黑暗需要你的力量！");
		} else if (results == CampBattlefieldConfig.ERROR_LEVEL_TOO_LOW) {
			sendMessage(player.getId(), "加入失败，您的等级太低无法参战。");
		} else if (results == CampBattlefieldConfig.ERROR_INOTHER_BATTLEFIELD_QUEUE) {
			sendMessage(player.getId(), "您已经加入其它战场的队列，请离开队列再排队。");
		}
    }
    
    private void actionRequestLeave (String name, WorldPlayer player) {
    	int levelType = campBattlefieldService.setLevelTypeByBattleName(name, player.getLevel());
		CampBattlefieldPlayer cbfPlayer = campBattlefieldService.getWaitingPlayer(name, levelType, player);
		if (cbfPlayer != null) {
			sendMessage(player.getId(), "操作成功，您已离开队列");
		} else {
			sendMessage(player.getId(), "操作失败，您不在队列中。");
		}
    }
    
    private void actionViewShop (WorldPlayer player, UWAPData data) {
    	List itemList = ItemGroup.getItemInfoForType(player.getId(), 1);
    	if (itemList != null) {
    		UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
			seg.writeShort(ClientConstants.EXTEND_CAMP_BATTLEFIELD_RELATED);
			seg.write(CampBattlefieldConfig.ACTION_VIEW_SHOP);
			seg.writeInt(itemList.size());
			for (int i = 0; i < itemList.size(); i ++) {
				ItemGroup ig = (ItemGroup) itemList.get(i);
				seg.writeString(ig.getDesc());
				seg.writeInt(ig.getID());
			}
			write(seg);
    	} else {
    		sendMessage(player.getId(), "当前没有适合您购买的商品。");
    	}
    }
    
    private void actionViewItem (WorldPlayer player, UWAPData data, int groupID) {
    	HashMap<Integer, ItemInfo> itemInfoMap = ItemGroup.getItemInfo(player.getId(), groupID);
    	if (itemInfoMap != null) {
    		UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
			seg.writeShort(ClientConstants.EXTEND_CAMP_BATTLEFIELD_RELATED);
			seg.write(CampBattlefieldConfig.ACTION_SHOP_ITEM);
			seg.writeInt(itemInfoMap.size());
			for (ItemInfo itemInfo : itemInfoMap.values()) {
				seg.writeInt(itemInfo.getItemID());
				seg.writeString(itemInfo.getItem().getName());
				seg.writeInt(itemInfo.getCount());
				seg.writeInt(itemInfo.getPoint());
				seg.write(itemInfo.getItem().getQuality());
				seg.write(itemInfo.getItem().getType());
			}
			write(seg);
    	} else {
    		sendMessage(player.getId(), "当前没有适合您购买的商品。");
    	}
    }
    
    private void actionBuyItem (WorldPlayer player, UWAPData data, int groupID, int itemID, int count) throws ITimesException {
    	HashMap<Integer, ItemInfo> itemInfoMap = ItemGroup.getItemInfo(player.getId(), groupID);
		ItemInfo itemInfo = itemInfoMap.get(itemID);
		int point = itemInfo.getPoint();
		if (itemInfo.getItem().getType() != IItem.TYPE_EQU) {
			point *= count;
		}
		if (point > player.getCampBattlefieldKillPoints()) {
			actionViewItem(player, data, groupID);
			sendMessage(player.getId(), "杀戮点数不足，需要" + point + "点杀戮点");
		} else {
			byte results = ItemGroup.addItemBuyInfo(player.getId(), groupID, itemID, count);
			if (results == ItemConstants.BUY_TYPE_OK) {//购买记录成功
				Changed changed = new Changed();
				IItem nItem = player.completeAddItem(itemInfo.getItem().
						newInstance(), count, changed, player.getClientDataVersion());
				player.setCampBattlefieldKillingPoints(player.getCampBattlefieldKillPoints() - point);
				changed.addProperty(Changed.KILL_POINT, -point);
				actionViewItem(player, data, groupID);
				if (nItem == null) {
					IItem iit = Items.getTemplate(itemInfo.getItem().getItemId()).newInstance();
					byte[] att = ItemUtils.item2dbAttachment(iit, count);
					mailService.sendMail(player.getId(), player.getPlayerName(), -1, "系统",
							iit.getName() + "*" + count, "", att, 0, true);
					sendMessage(player.getId(),"你的背包满了，已经把物品邮寄到您的邮箱!");
				}
				sendGetItem(changed, data.getSerial(), data.getSessionId(), (byte) 2);
				sendMessage(player.getId(), "购买成功");
				
				//购卖成功 需要增加杀戮点数并加入排行榜
				long consumeTime = player.getKillPointConsumeTime().getTime();
				//过时了 设置为当天时间并重置杀戮点数 不然加上消费的点数
				if(consumeTime < Utils.getTodayStart()){
					player.setKillPointConsumeTime(Utils.getTodayStartDate());
					player.setKillPointConsume(point);
				}else{
					player.setKillPointConsume(player.getKillPointConsume() + point);
				}
				//加入排行榜
				ItemTop.addConsume(player.getId(), player.getKillPointConsume());
				
			} else if (results == ItemConstants.BUY_TYPE_NULL) {//无效
				actionViewItem(player, data, groupID);
				sendMessage(player.getId(), "当前没有适合您购买的商品。");
			} else if (results == ItemConstants.BUY_TYPE_ALLCOUNT_ZERO
					|| results == ItemConstants.BUY_TYPE_ALLCOUNT_NOTENOUGH
					|| results == ItemConstants.BUY_TYPE_ONECOUNT_ZERO
					|| results == ItemConstants.BUY_TYPE_ONECOUNT_NOTENOUGH) {
				actionViewItem(player, data, groupID);
				sendMessage(player.getId(), "商品不足。");
			}
		}
    }

    private void battleRequest(UWAPData data) throws Exception {
        int teamId = data.readInt();
        int mgId = data.readInt();
        WorldPlayer player = getPlayer(data.getSessionId());
        if (player != null) {
        	synchronized (player) {
        		Utils.log(log, player.getId(), data.getAppType(), "MgId[" + mgId + "]TRY");
        		
        		GameMap map = player.getMap();
        		if (map == null) {
        			UWAPSegment seg = new UWAPSegment(ClientConstants.
        					BATTLE_JOIN_RESULT,
        					data.getSerial(),
        					data.getSessionId());
        			seg.write((byte) 1);
        			seg.writeString("怪物已经逃跑了。");
        			write(seg);
        			Utils.log(log, player.getId(), data.getAppType(),
        					"MgId[" + mgId + "] map is null");
        			return;
        		}
        		MonsterGroup mg = stageService.getMonsterGroup(mgId);
        		if (mg == null) {
        			Utils.log(log, player.getId(), data.getAppType(),
        					"MgId[" + mgId + "] BattleError mg null");
        			return;
        		}
        		short mgMapID = (short)(mgId>>16);
        		if(player.getMapId() != mgMapID){
        			boolean bReturn = true;
        			if (Utils.isServerMonsterGroup(mg)) {
        				if(bossService.isWorldBoss(mgId)){
        					WorldBoss worldBoss = bossService.findWaitingBoss(mgId);
        					if(worldBoss != null){
        						if(player.getMapId() == worldBoss.getMapId()){
        							bReturn = false;
        							Utils.log(log, player.getId(), data.getAppType(),
        									"MgId[" + mgId + "] BattleError playerMapID != mgMapID but is WorldBoss");
        						}
        					}else{
        						Utils.log(log, player.getId(), data.getAppType(),
        								"MgId[" + mgId + "] BattleError playerMapID != mgMapID but WorldBoss Null");
        					}
        				}
        			}
        			if(bReturn){
        				Utils.log(log, player.getId(), data.getAppType(),
        						"MgId[" + mgId + "] BattleError playerMapID != mgMapID");
        				return;
        			}
        		}
        		
        		long now = System.currentTimeMillis();
        		for(int i=0; i<10; i++){
        			if(player.killmgid[i] != null){
        				if(player.killmgid[i].getMgId() == mgId && 
        						now - player.killmgid[i].getKilltime() < mg.getRefreshSecond() * 1000L){
        					UWAPSegment seg = new UWAPSegment(ClientConstants.
                					BATTLE_JOIN_RESULT,
                					data.getSerial(),
                					data.getSessionId());
                			seg.write((byte) 1);
                			seg.writeString("天哪，怪物还没重生，这不可能！");
                			write(seg);
                			Utils.log(log, player.getId(), data.getAppType(),
            						"MgId[" + mgId + "] killTime < resfreshTime");
                			return;
        				}
        			}else{
        				break;
        			}
        		}
        		
        		ClientBattle2 battle = null;
        		Team team = player.getTeam();
        		if (team == null ||
        				player.getTeamState() == WorldPlayer.TEAM_NORMAL) {
        			try {
        				battle = battleService.startMonsterBattle(new WorldPlayer[] {
        						player}, mg,
        						data.getSerial(), -1, map.getInstance() != null);
        			} catch (BattleException ex1) {
        				if (battle != null)
        					battleService.removeBattle(battle);
        				if (Utils.isServerMonsterGroup(mg)) {
        					refreshMonsterGroup(player.getId(), mg.getId(),
        							mg.getTileX(), mg.getTileY()); //因为客户端在请求服务器战斗以后会把怪物先刷没，所以在这里需要把怪物给刷出来
        				}
        				UWAPSegment seg = new UWAPSegment(ClientConstants.
        						BATTLE_JOIN_RESULT,
        						data.getSerial(),
        						data.getSessionId());
        				seg.write((byte) 1);
        				seg.writeString("怪物已经逃跑了。");
        				write(seg);
        				Battle2 b = battleService.getBattleByPlayer(player.getId());
        				if (b != null) {
        					b.catchToBattle(player.getId(), data.getSerial());
        				}else{
        					//当前战斗一直为空的话无条件返回
        					return;
        				}
        			}
        		} else {
        			IPlayerData[] players = team.getMembers(WorldPlayer.TEAM_FOLLOW);
        			try {
        				battle = battleService.startMonsterBattle(players, mg,
        						data.getSerial(), team.getId(), map.getInstance() != null);
        			} catch (BattleException ex2) {
        				if (battle != null)
        					battleService.removeBattle(battle);
        				if (Utils.isServerMonsterGroup(mg)) {
        					refreshMonsterGroup(players[0].getId(), mgId,
        							mg.getTileX(), mg.getTileY());
        				}
        				UWAPSegment seg = new UWAPSegment(ClientConstants.
        						BATTLE_JOIN_RESULT,
        						data.getSerial(),
        						data.getSessionId());
        				seg.write((byte) 1);
        				seg.writeString("怪物已经逃跑了。");
        				write(seg);
        				Battle2 b = battleService.getBattleByPlayer(player.getId());
        				if (b != null) {
        					b.catchToBattle(player.getId(), data.getSerial());
        				}else{
        					//当前战斗一直为空的话无条件返回
        					return;
        				}
//                throw new ITimesException(ex2.getMessage(), data.getSerial(),
//                                          data.getSessionId(),
//                                          data.getAppType());
        				
        			}
        			
        		}
        		try {
        			if (Utils.isServerMonsterGroup(mg)) {
        				if(bossService.isWorldBoss(mgId)){
        					WorldBoss worldBoss = bossService.findWaitingBoss(mgId);
        					if(worldBoss != null){//锁住战斗
        						if(battle != null){
        							IPlayerData[] players = null;
        							if (team == null ||
        									player.getTeamState() == WorldPlayer.TEAM_NORMAL) {//只有玩家自己
        								players = new IPlayerData[]{player};
        								bossService.addPlayerBoss(player.getId(), worldBoss);
//	                    			 //发送私聊
//	                    			 if(BossTips.getBossTip(mgId).length() > 0){
//	                    			 	 chatService.sendPrivateMessage(-1, "系统", player.getId(), BossTips.getBossTip(mgId));
//	                    			 }
        							}else {//组队状态
        								players = team.getMembers(WorldPlayer.TEAM_FOLLOW);
        								for(int i = 0; i < players.length; i++){
        									bossService.addPlayerBoss(players[i].getId(), worldBoss);
        									chatService.sendPrivateMessage(-1, "系统", players[i].getId(), BossTips.getBossTip(mgId));
        								}
        								//发送私聊
        								
        							}
        							//清除出世界boss战斗队列
        							bossService.removeWaitingBoss(worldBoss);
        							//刷掉世界boss
        							
        							bossService.refreshWorldBossDisable(worldBoss, worldBoss.STATE_HIDE/*, players*/);
        						}else{
        							//空战斗无条件返回
        							return;
        						}
        					}else{//已经被别人打了
        						if (battle != null)
        							battleService.removeBattle(battle);
        						UWAPSegment seg = new UWAPSegment(ClientConstants.
        								BATTLE_JOIN_RESULT,
        								data.getSerial(),
        								data.getSessionId());
        						seg.write((byte) 1);
        						seg.writeString("怪物和其他玩家战斗中");
        						write(seg);
        						return;
        					}
        				}else{
        					MonsterObject mo = map.getMonsterGroup(mgId);
        					if (mo == null || mo.getStatus() == IServerObject.STATUS_INVISIBLE) {
        						if (battle != null)
        							battleService.removeBattle(battle);
        						UWAPSegment seg = new UWAPSegment(ClientConstants.
        								BATTLE_JOIN_RESULT,
        								data.getSerial(),
        								data.getSessionId());
        						seg.write((byte) 1);
        						seg.writeString("怪物已经逃跑了。");
        						write(seg);
        						return;
        					}
        					if(battle != null){
        						mo.lock(battle);
        					}
        				}
        				
        			}
        			if (battle != null){
        				battle.start();
        				Utils.log(log, player.getId(), data.getAppType(), "MgId[" + mgId + "]");
        			}else{
        				Utils.log(log, player.getId(), data.getAppType(), "MgId[" + mgId + "] error");
        			}                
        			
        		} catch (Exception ex) {
        			if (battle != null)
        				battleService.removeBattle(battle);
        			UWAPSegment seg = new UWAPSegment(ClientConstants.
        					BATTLE_JOIN_RESULT,
        					data.getSerial(),
        					data.getSessionId());
        			seg.write((byte) 1);
        			seg.writeString("怪物已经被别的玩家接触");
        			write(seg);
        		}
			}
        }else{
        	log.error("battleRequest player null");
        }
    }

    public void refreshMonsterGroup(int playerId, int mgId, int x, int y) {
        UWAPSegment seg = new UWAPSegment(ClientConstants.REFRESH);
        seg.writeShort((short) 1);
        seg.write((byte) 1);
        seg.writeInt(mgId);
        seg.writeInt((x & 0xFFFF) << 16 | (y & 0xFFFF));
        connectService.writeTo(seg, playerId);
    }

    private void changeChatFavorite(UWAPData data) throws Exception {
        WorldPlayer player = getPlayer(data.getSessionId());
        if (player != null) {
            synchronized (player) {
                int oldFavoriteId = player.getChatFavoriteId();
                int newFavoriteId = -1;
                byte index = data.readByte();
                if (index == 0) {
                    player.setChatFavoriteId( -1);
                } else {
                    ChatFavorite[] favorites = ChatFavorites.getChatFavorites();
                    int id = favorites[index].id;
                    player.setChatFavoriteId(id);
                    newFavoriteId = id;
                }

                UWAPSegment seg = new UWAPSegment(ClientConstants.
                                                  CHANGE_CHATFAVORITE,
                                                  data.getSerial(),
                                                  data.getSessionId());
                seg.writeInt(oldFavoriteId);
                seg.writeInt(newFavoriteId);
//                playerService.savePlayer(player);
                write(seg);
                String[] removeChannel;
                String[] addChannel;
                if (oldFavoriteId != -1) {
                    removeChannel = new String[1];
                    removeChannel[0] = ChatService.FAVORITE_CHANNEL + oldFavoriteId;
                } else {
                    removeChannel = new String[0];
                }
                if (newFavoriteId != -1) {
                    addChannel = new String[1];
                    addChannel[0] = ChatService.FAVORITE_CHANNEL + newFavoriteId;
                } else {
                    addChannel = new String[0];
                }
                syncChannels(data.getSessionId(), addChannel, removeChannel);
            }
        }
    }

