    private void gather(UWAPData data) throws Exception {
        int resourceId = data.readInt();
        WorldPlayer player = getPlayer(data.getSessionId());
        if (player != null) {
            GameMap map = player.getMap();
            if (map == null)
                throw new ITimesException("状态错误", data.getSerial(),
                                          data.getSessionId(), data.getAppType());
            ResourceObject resource = map.getResource(resourceId);
            
            if(resource == null){
            	log.info("gather Exception reource is null mapID[" + map.getMapId() + "] ID[" + resourceId + "]");
            	throw new ITimesException("资源已经被采", data.getSerial(),
                        data.getSessionId(), data.getAppType());
            }
            
//            int skillPoint = player.getSkillPoint(resource.getType());
//            if (player.getSkillPoint(resource.getType()) < 0)
//                throw new ITimesException("不能采集此类资源", data.getSerial(),
//                                          data.getSessionId(), data.getAppType());
//            if (Utils.getSkillLevel(skillPoint) < resource.getLevel())
//                throw new ITimesException("技能等级不够", data.getSerial(),
//                                          data.getSessionId(), data.getAppType());
            try {
                resource.lock(player);

                UWAPSegment seg = new UWAPSegment(ClientConstants.GATHER_OK,
                                                  data.getSerial(),
                                                  data.getSessionId());
                write(seg);
            } catch (LockException ex) {
                throw new ITimesException("资源已经被采", data.getSerial(),
                                          data.getSessionId(), data.getAppType());
            }
        }
    }

