    private void teamLeave(UWAPData data) throws Exception {
        int teamId = data.readInt();
        int playerId = data.readInt();
        byte state = data.readByte();
        WorldPlayer player = getPlayer(data.getSessionId());
        if(player != null){
	        Team team = player.getTeam();
	        if (player != null && team != null && team.contains(player)) {
	            if (state == 0 || state == 1) {
	                changeTeamState(player, state);
	            } else if (state == 2) {
	                leaveTeam(player);
	            }
	        }
        }
    }

    public void changeTeamState(WorldPlayer player, byte state) {
        Team team = player.getTeam();
        WorldPlayer leader = (WorldPlayer)team.getLeader();
        if (player != leader && player.getTeamState() != state) {
            if (state == WorldPlayer.TEAM_FOLLOW) {
                //modify
                if (leader.getMap() != player.getMap()) {
                    if (leader.getMap().getMapId() == player.getMap().getMapId()) {
                        sendMessage(player.getId(), "与队长不在同一副本");
                        return;
                    } else {
                        sendMessage(player.getId(), "离队长太远");
                        return;
                    }
                }
//                if (leader.getMapId() != player.getMapId()) {
//                    sendMessage(player.getId(), "离队长太远");
//                    return;
//                }
                if (Math.abs(leader.getX() - player.getX()) > 150 ||
                    Math.abs(leader.getY() - player.getY()) > 150) {
                    sendMessage(player.getId(), "离队长太远");
                    return;
                }
                if (battleService.inBattle(leader)) {
                    sendMessage(player.getId(), "队长正在战斗状态，不能跟随");
                    return;
                }
            }
            player.setTeamState(state);
            UWAPSegment seg = new UWAPSegment(ClientConstants.TEAM_LEAVE, -1);
            seg.writeInt(team.getId());
            seg.writeInt(player.getId());
            seg.write(state);
            PositionSprite[] members = team.getPlayers();
            for (int i = 0; i < members.length; i++) {
            	if(members[i] instanceof WorldPlayer){
            		connectService.writeTo(seg, members[i].getId());
            	}
            }
        }
    }

    public void leaveTeam(PositionSprite player) {
        Team team = player.getTeam();
        if (team != null) {
            PositionSprite[] members = team.getPlayers();
            teamService.leaveTeam(team, player);
            UWAPSegment seg = new UWAPSegment(ClientConstants.
                                              TEAM_LEAVE);
            seg.writeInt(team.getId());
            seg.writeInt(player.getId());
            seg.write((byte) 2); //离开
            for (int i = 0; i < members.length; i++) {
                if (members[i] != player && (members[i] instanceof WorldPlayer)) {
                    connectService.writeTo(seg, members[i].getId());
                }
            }
        }
    }

    private void teamInvit(UWAPData data) throws Exception {
        int teamId = data.readInt();
        int playerId = data.readInt();
        String playerName = data.readString();
        int targetId = data.readInt();
        WorldPlayer player = getPlayer(data.getSessionId());
        GameMap map = player.getMap();
        
        if (map != null && !map.isCanCreateTeam()) {
            sendMessage("此地图不能发送组队邀请", data.getSerial(), data.getSessionId());
            return;
        }
        WorldPlayer target = playerService.getWorldPlayer(targetId);
        if (target == null || !target.online()) {
            throw new ITimesException("对不起,离线角色或已删除角色不能邀请入队.", data.getSerial(),
                                      data.getSessionId(),
                                      data.getAppType());
        }
        if (target.getTeam() != null) {
            throw new ITimesException("已经有所属队伍", data.getSerial(),
                                      data.getSessionId(),
                                      data.getAppType());
        }
        if (target != null && (target.offlinemode() || robotService.isRobot(target))) {
            throw new ITimesException("对方拒绝组队", data.getSerial(),
                                      data.getSessionId(),
                                      data.getAppType());
        }
        //int ret = target.addBlackList(player.getId(), player.getAccountName());	// zjl modify
        boolean flag = target.inBlackList(player.getId());
        if(flag){
        	sendMessage("你已经在对方的黑名单中，无法邀请对方进入队伍！", data.getSerial(), data.getSessionId());
        	return;
        }
        
        map = player.getMap();
        GameMap targetMap = target.getMap();
        if (map == null || targetMap == null) {
            sendMessage("创建队伍出错", data.getSerial(), data.getSessionId());
            return;
        }
        Instance instance = map.getInstance();
        Instance targetInstance = targetMap.getInstance();
        if (instance == null && targetInstance != null) {
            sendMessage("组队状态错误", data.getSerial(), data.getSessionId());
            return;
        }
        if (instance != null && targetInstance != null) {
            if (instance != targetInstance) {
                sendMessage("组队状态错误", data.getSerial(), data.getSessionId());
                return;
            }
        }
        Team team = player.getTeam();
        if (team == null) {

            if (map != null && !map.isCanCreateTeam()) {
                sendMessage("此地图不能创建队伍", data.getSerial(), data.getSessionId());
                throw new ITimesException("此地图不能创建队伍", data.getSerial(),
                		data.getSessionId(),
                		data.getAppType());
            }
            if (player != null) {
                team = teamService.createTeam(player);
                UWAPSegment seg = new UWAPSegment(ClientConstants.
                                                  TEAM_CREATE_OK,
                                                  data.getSerial(),
                                                  data.getSessionId());
                seg.writeInt(team.getId());
                write(seg);
            }
        }
        if (team.getCount() >= 3)
            throw new ITimesException("队伍已满", data.getSerial(),
                                      data.getSessionId(),
                                      data.getAppType());
        if (team.getLeader() != player)
            throw new ITimesException("只有队长才有权力邀请队友", data.getSerial(),
                                      data.getSessionId(),
                                      data.getAppType());

        if (player != null) {
            UWAPSegment seg = new UWAPSegment(ClientConstants.TEAM_INVIT,
                                              data.getSerial());
            seg.writeInt(team.getId());
            seg.writeInt(playerId);
            seg.writeString(player.getPlayerName());
            seg.writeInt(targetId);
            connectService.writeTo(seg, targetId);
        }

    }

    private void teamInvitResult(UWAPData data) throws Exception {
        int teamId = data.readInt();
        byte retCode = data.readByte();
        String cause = data.readString();
        if (retCode == 0) { //同意加入
            WorldPlayer player = getPlayer(data.getSessionId());
            if (player != null) {
                try {
                    Team team = teamService.addPlayerToTeam(teamId, player);
                    UWAPSegment seg = new UWAPSegment(ClientConstants.
                            TEAM_JOIN_OK, data.getSerial(),
                            data.getSessionId());
                    PositionSprite[] players = team.getPlayers();
                    seg.writeInt(team.getId());
                    seg.write((byte) players.length);
                    for (int i = 0; i < players.length; i++) {
                        seg.writeInt(players[i].getId());
                        seg.write((byte) players[i].getTeamState());
                        seg.writeString(players[i].getPlayerName());
                    }
                    for (int i = 0; i < players.length; i++) {
                    	if(players[i] instanceof WorldPlayer){
                    		connectService.writeTo(seg, players[i].getId());
                    	}
                    }
                    changeTeamState(player, (byte)WorldPlayer.TEAM_FOLLOW);
                } catch (TeamException ex) {
                    sendMessage(ex.getMessage(), data.getSerial(), getSessionId());
//                    throw new ITimesException(ex.getMessage(), data.getSerial(),
//                                              data.getSessionId(),
//                                              data.getAppType());
                }
            }
        } else { //失败
            Team team = teamService.getTeam(teamId);
            if (team != null) {
                UWAPSegment seg = new UWAPSegment(ClientConstants.
                                                  TEAM_INVIT_RESULT,
                                                  data.getSerial());
                seg.writeInt(teamId);
                seg.write(retCode);
                seg.writeString(cause);
                connectService.writeTo(seg, team.getLeader().getId());
            }
        }
    }

