    private void chat(UWAPData data) throws Exception {
        WorldPlayer player = getPlayer(data.getSessionId());
        int srcId = data.readInt();
        String srcName = data.readString();
        int destId = data.readInt();
        String message = data.readString();
        message.replace("\n", " ");
        if (player != null) {
            if (message.startsWith("/")) {
                Command command = new Command(message, true);
                String c = command.getCommand();
                if (c != null) {
	                if ("gquit".equals(c)) {
	                    try {
	                        int tongId = player.getTongId();
	                        tongService.quit(player);
	                        chatService.sendTongMessage(tongId, -1, "系统",
	                                player.getPlayerName() + "离开了公会");
	                        UWAPSegment seg = new UWAPSegment(ClientConstants.
	                                TONG_GRANT_OK, data.getSerial());
	                        seg.writeInt(player.getId());
	                        seg.writeString(player.getTongName());
	                        seg.write((byte) player.getTongDuty());
	                        connectService.writeTo(seg, player.getId());
	                        chatService.sendPrivateMessage( -1, "系统", player.getId(),
	                                "你已经离开了公会");
	                    } catch (TongException ex) {
	                        throw new ITimesException(ex.getMessage(),
	                                                  data.getSerial(),
	                                                  data.getSessionId(),
	                                                  data.getAppType());
	                    }
	
	                } else if (c.startsWith("[")) {
	                    if (command.getParamCount() >= 1) {
	                        boolean commited = adminService.receiveChatMessage(player.getId(),
	                                player.getPlayerName(), c,
	                                Utils.getMessage(message));
//	                        chatService.sendPrivateMessage(-1, "系统", player.getId(), "请通过菜单中的\"呼叫GM\"系统提交您的问题。");
	                        if (!commited) {
	                            chatService.sendPrivateMessage( -1, "系统", player.getId(),
	                                    "此GM暂时不在线，请通过菜单中的\"呼叫GM\"系统提交您的问题。");
	                        }
	                    }
	                } else if (c.toLowerCase().equals("gm")) {
	                    if (command.getParamCount() >= 1) {
	                        boolean commited = adminService.receiveChatMessage(player.getId(),
	                                player.getPlayerName(), c,
	                                Utils.getMessage(message));
//	                        chatService.sendPrivateMessage(-1, "系统", player.getId(), "请通过菜单中的\"呼叫GM\"系统提交您的问题。");
	                        if (!commited) {
	                            chatService.sendPrivateMessage( -1, "系统", player.getId(),
	                                    "没有在线GM，请通过菜单中的\"呼叫GM\"系统提交您的问题.");
	                        }
	                    }
	                } /*else if("boss".equals(c)){
	                    //bossService.createBoss(BossDefineLoader.bossDefineMap.get(c922030));
	                	BossDefine bossDefine = BossDefineLoader.bossDefineMap.get(104996871);
	                	bossService.createBoss(bossDefine);
	                }*/ 
	                else if(c.startsWith("camp_add")){
	                	  CommandProcessor processor = (CommandProcessor) getCommandmap().get(
	                              command.getCommand());
	                      if (processor != null) {
	                    	  command.setSerial(data.getSerial());
	                    	  command.setSessionId(data.getSessionId());
	                          processor.process(player, command);
	                      }
	                }else {
	                    if (command.getParamCount() >= 1) {
	                        WorldPlayer destPlayer = playerService.getWorldPlayer(c);	//zjl  modify
	                    	//WorldPlayer destPlayer = playerService.loadWorldPlayer(c);
	                    	if(destPlayer != null){
	                    		 //int id = playerService.getPlayerId(destPlayer.getAccountName());
		                        //int ret = destPlayer.addBlackList(player.getId(), player.getAccountName());
		                        boolean flag = destPlayer.inBlackList(player.getId());
		                        if(flag){
		                        	sendMessage("你已经在对方的黑名单中，无法向对方发送私聊!", data.getSerial(), data.getSessionId());
		                        	return;
		                        }
	                    		
	                    	}else{
	                    		sendMessage("对方不在线", data.getSerial(), data.getSessionId());
	                    		return;
	                    	}
	                        
	                        chatService.receiveMessage(player, destPlayer,
	                                Utils.getMessage(message));
	                    }else{
	                    	if(destId==ISendMessage.CAMP){
	                    		//阵营聊天的时候
	                    	    CampData campData = campMainService.getCampData(player.getCamp());
	                    	    
	                    		if(campData.hasSilenced(player.getId())){
	                    			sendMessage(player.getId(), "你已经被领袖或官员禁言了！");
	                    			return;
	                    		}
	                    	}
	                    	chatService.receiveMessage(player, player.getId(), player.getPlayerName(), destId, message);
	                    }
	                }
	            }
            } else {
            	if(destId==ISendMessage.CAMP){
            		//阵营聊天的时候
            	    CampData campData = campMainService.getCampData(player.getCamp());
            	    
            	    if(campData.hasSilenced(player.getId())){
            			sendMessage(player.getId(), "你已经被领袖或官员禁言了！");
            			return;
            		}
            	}
	            chatService.receiveMessage(player, player.getId(), player.getPlayerName(), destId, message);
	            
	            //为统计平台计数
	            Server.realtimeStatService.chatCounter++;
            }
        }

    }

