    protected String[] getPlayerChannels(WorldPlayer player) {
        if (player.offlinemode())
            return new String[0];
        List<String> channels = new ArrayList<String>(3);
        if (player.getChatOptions()[ChatOption.WORLD].pri != 0) {
            channels.add(ChatService.WORLD_CHANNEL);
        }
        if (player.getChatOptions()[ChatOption.MAP].pri != 0) {
            channels.add(ChatService.MAP_CHANNEL + player.getMapId());
        }
        if (player.getChatOptions()[ChatOption.FAVORITE].pri != 0 && player.getChatFavoriteId() != -1) {
            channels.add(ChatService.FAVORITE_CHANNEL + player.getChatFavoriteId());
        }
        if(player.getCamp() != Utils.NO_CAMP){
        	channels.add(ChatService.CAMP_CHANNEL + player.getCamp());
        }
        String[] ret = new String[channels.size()];
        channels.toArray(ret);
        return ret;
    }


    private void changeMapChannel(int sessionId, int oldMapId, int newMapId) {
        UWAPSegment seg = new UWAPSegment(ServerConstants.SYNC_CHANNEL);
        seg.writeInt(sessionId);
        seg.writeStrings(new String[] {ChatService.MAP_CHANNEL + newMapId});
        seg.writeStrings(new String[] {ChatService.MAP_CHANNEL + oldMapId});
        write(seg);
    }

    protected void addToChannels(int sessionId, String[] channels) {
        UWAPSegment seg = new UWAPSegment(ServerConstants.SYNC_CHANNEL);
        seg.writeInt(sessionId);
        seg.writeStrings(channels);
        seg.writeStrings(new String[0]);
        write(seg);
    }
    
    /**
     * @param sessionId
     * @param dataVersion
     * 将玩家的的 sessionId和dataVerssion同步到分配器下
     * @param camp TODO
     */
    protected void addPlayerDispatchChat(int sessionId, int dataVersion, int camp){
	  UWAPSegment seg = new UWAPSegment(ServerConstants.SYNC_PLAYER_DATAVESION);
      seg.writeInt(sessionId);
      seg.writeInt(dataVersion);
      seg.writeInt(camp);
      write(seg);
    }
    private void removeFromChannels(int sessionId, String[] channels) {
        UWAPSegment seg = new UWAPSegment(ServerConstants.SYNC_CHANNEL);
        seg.writeInt(sessionId);
        seg.writeStrings(new String[0]);
        seg.writeStrings(channels);
        write(seg);
    }

    private void removeFromAllChannels(int sessionId) {
        UWAPSegment seg = new UWAPSegment(ServerConstants.CLEAR_CHANNELS);
        seg.writeInt(sessionId);
        write(seg);
    }

    protected void syncChannels(int sessionId, String[] aChannels, String[] rChannels) {
        UWAPSegment seg = new UWAPSegment(ServerConstants.SYNC_CHANNEL);
        seg.writeInt(sessionId);
        seg.writeStrings(aChannels);
        seg.writeStrings(rChannels);
        write(seg);
    }

    protected void tryAddBathHouseExp(WorldPlayer player, long current, BathHouse bathHouse, Changed changed,Date logouttime) throws DataAccessException {
    	Date t;
    	if (logouttime == null){
    		t = player.getBathHouseTime();
        }else{
        	t = logouttime;
        }
    	
        if (t != null && current > t.getTime()) {
            int c = (int) ((current - t.getTime()) / bathHouse.getTime());
            int level_tmp = player.getLevel();
            for (int i = 0; i < c; i++) {
            	//mengjie add
            	if (!player.hasItem(bathHouse.getItemId(), 1)){
            		//没有澡票，解开澡票
            		if (bathHouse.getItemId() == 550017)
            			for(int ii = 0; ii < bathHouse.VIP_PACKAGE.length; ii++){
    	            		if(player.hasItem(bathHouse.VIP_PACKAGE[ii],1)){
    	            			if(player.getAllGridSize() > player.getCurrentGridSize()){
    		            			player.completeRemoveItem(bathHouse.VIP_PACKAGE[ii], 1, changed);
    		            			player.addItem(bathHouse.getItemId(), bathHouse.PACKAGE_COUNT[ii], changed, player.getClientDataVersion());
    		            			break;
    	            			}else{
    	            				//背包满
    	            				connectService.sendMessage(player.getId(), "你的背包满了，不能自动使用浴场幸运券套装.");
    	            				break;
    	            			}
    	                	}
    	            	}
            		else if (bathHouse.getItemId() == 550015)
    	        		for(int ii = 0; i < bathHouse.PET_PACKAGE.length; i++){
    	            		if(player.hasItem(bathHouse.PET_PACKAGE[ii],1)){
    	            			if(player.getAllGridSize() > player.getCurrentGridSize()){
    		            			player.completeRemoveItem(bathHouse.PET_PACKAGE[ii], 1, changed);
    		            			player.addItem(bathHouse.getItemId(), bathHouse.PACKAGE_COUNT[i], changed, player.getClientDataVersion());
    		            			break;
    	            			}else{
    	            				//背包满
    	            				connectService.sendMessage(player.getId(), "你的背包满了，不能自动使用浴场幸运券套装.");
    	            				break;
    	            			}
    	                	}
    	            	}
            	}
            	//mengjie add end
                if (player.completeRemoveItem(bathHouse.getItemId(), 1, changed) != null) {
                	log.info("ID[" + player.getId() +
                            "] completeRemoveBathItem[" +bathHouse.getItemId()+"]Login");
                    if (player.getMaxLevel() > player.getLevel()) {
                        int r = 0;
                        Buf buf = player.getBuf(Buf.ADD_BATHHOUSE_EXP);
                        //if (buf != null) {
                        //    r = buf.getValue();
                        //}
                        r += bathHouse.getRatio();
                        //int exp = (BathHouse.EXP[player.getLevel()] * (100 + r)) / 100;
                        //泡澡经验换算更改
                        int exp = (BathHouse.EXP[player.getLevel()] * r) / 100;
                        if (buf != null) {
                        	exp = exp * (100+buf.getValue()) / 100;
                        }
                        long getExp = 1L * Discount.BATH_EXP_PERCENT * exp;
                        player.addExp((int) (getExp / 100), changed);
                        //mengjie add
                        friendsService.killfriend(player.getId(), player.getLevel());
                        //推荐人
                        if ((level_tmp<player.getLevel()) && ((player.getLevel()==50)||(player.getLevel()==65)||(player.getLevel()==80)||(player.getLevel()==90)||(player.getLevel()==100))){
                        	level_tmp = player.getLevel();
                        	if (Server.iMoneyType == Server.IMONEY_TYPE_PIP){
                                addRecommendBalance(player);
                                Utils.log(log, player.getId(), -1,
                                        "RecommendBalance--accountid[" + player.getAccountId() + "]--" +
                                        		"accountname[" + player.getAccountName() + "]" +
                                        				"LEVEL["+player.getLevel()+"]Bathhouse Offline");
                            }
                        }
                        //mengjie add end
                        //mengjie add 宠物加离线经验
                        HouseData hd;
						try {
							hd = houseModel.getHouseByPlayerId(player.getId());
							if (hd != null && hd.isUsedWaiter()) {
	                            Pet p = player.getPet();
	                            if (p != null) {
	                            	//宠物泡澡经验双倍！
	                                player.tryAddPetExp(Discount.BATH_EXP_PERCENT * BathHouse.PET_EXP[p.getLevel()] * 2 / 100, changed);
	                                log.info("ID[" + player.getId() +
	                                        "] completeRemoveBathItem[" +bathHouse.getItemId()+"]Login add Pet");
	                            }
	                        }else if(hd != null && !hd.isUsedWaiter()){
	                        	//未雇佣管家查看是否正在续费 mengjie add
	                        	if (HouseData.getWaiterProcessing(player.getId()) > -1 ){
	                        		Pet p = player.getPet();
	                                if (p != null) {
	                                	HouseData.modifyProcessing(player.getId(), Discount.BATH_EXP_PERCENT * BathHouse.PET_EXP[p.getLevel()] * 2 / 100, 1);
	                                }
	                        	}
	                        }
						} catch (Exception e) {
							log.info("ID[" + player.getId() + "][自动管家续费失败]"+e);
						}
                        //mengjie add end
						if (logouttime == null){
							player.setBathHouseTime(new Date(player.getBathHouseTime().getTime() + bathHouse.getTime()));
						}
                    } else {
                    	//100级泡澡给规定经验:940500
                    	player.addExp(940500, changed);
                        //int credit = 10*(100+bathHouse.getRatio())/100;
                    	//泡澡经验换算更改
                        int credit = 10*(bathHouse.getRatio())/100;
                        //mengjie add 百级泡澡荣誉双倍
                        credit = credit * 2;
                    	//credit = 60;
                        player.addCredit(Discount.BATH_CREDIT_PERCENT * credit / 100,changed);
                        HouseData hd;
    					try {
    						hd = houseModel.getHouseByPlayerId(player.getId());
    						if (hd != null && hd.isUsedWaiter()) {
    	                        Pet p = player.getPet();
    	                        if (p != null) {
    	                            player.tryAddPetExp(Discount.BATH_EXP_PERCENT * BathHouse.PET_EXP[p.getLevel()] * 2 / 100, changed);
    	                            log.info("ID[" + player.getId() +
                                            "] completeRemoveBathItem[" +bathHouse.getItemId()+"]Login add Pet");
    	                        }
    	                    }else if(hd != null && !hd.isUsedWaiter()){
	                        	//未雇佣管家查看是否正在续费 mengjie add
	                        	if (HouseData.getWaiterProcessing(player.getId()) > -1 ){
	                        		Pet p = player.getPet();
	                                if (p != null) {
	                                	HouseData.modifyProcessing(player.getId(), Discount.BATH_EXP_PERCENT * BathHouse.PET_EXP[p.getLevel()] * 2 / 100, 1);
	                                }
	                        	}
	                        }
    					} catch (Exception e) {
    						log.info("ID[" + player.getId() + "][百级玩家泡澡给宠物加经验错误]"+e);
    					}
                        if (logouttime == null){
                        	player.setBathHouseTime(new Date(player.getBathHouseTime().getTime() + bathHouse.getTime()));
                        }
                    }
                } else {
                	if (logouttime == null){
                		player.setBathHouseTime(new Date(current));
                	}
                    break;
                }
            }
        }
//        else {
//            player.setBathHouseTime(new Date(current));
//        }
    }

    private void tryAddTimeExp(WorldPlayer player,long current,long lastLoginTime){
        long t = current-lastLoginTime;
        Changed changed = new Changed();
        if(t>=MIN_LOGINTIME){
            t = Math.min(t,MAX_LOGINTIME);
            int c =(int) (t / (30*60*1000L));
            boolean addExp = false;
            int oldLevel = player.getLevel();
            for(int i=0;i<c;i++){
                if(player.getMaxLevel() > player.getLevel()&&(player.getLevel()-oldLevel)<25){
                    int exp = BathHouse.EXP[player.getLevel()]/3;
                    player.addExp(exp,changed);
                    addExp = true;
                }
            }
            if(addExp){
                player.setChanged(changed);
            }
        }
    }
