    private void clientReportIp(UWAPData data){
        Client client = getAndCreateClient(data.getSessionId());
        
        try{
            client.setFromIp(data.readInt());
        }catch(IllegalAccessException e){
            e.printStackTrace();
        }
    }

    private void serverLogin(UWAPData data) {
        boolean success = false;
        try {
            String id = data.readString();
            String password = data.readString();
            String serverPassword = configuration.getString("serverpassword");
            maxPlayer = data.readInt();
            String connectionType = data.readString();
            if (password != null && password.equals(serverPassword)) {
                this.name = id;
                if("http".equals(connectionType)){
                    this.connectionType = 0; //http方式
                }
                UWAPSegment seg = new UWAPSegment(ServerConstants.
                                                  SERVER_LOGIN_OK);
                write(seg);
                success = true;
                notifyMaxPlayer(System.currentTimeMillis());
            }
        } catch (Exception e) {
            log.error(e, e);
        }
        if (!success) {
            close();
        }
    }

    public void write(UWAPSegment seg, int playerId) {
    	if(playerId < 0) return;
        Integer sessionId = (Integer) sessionIds.get(new Integer(playerId));
        if (seg.getType() == ClientConstants.CHAT || seg.getType() == ClientConstants.SEND_POSITION) {
            WorldPlayer player = playerService.getWorldPlayer(playerId);
            if (player == null){
            	return;
            }else if(player.offlinemode()){
            	 return;
            }                
        }
        if (sessionId != null) {
            seg.setSessionId(sessionId.intValue());
            write(seg);
        }
    }
    
    /**
     * @param seg
     * @param seg2
     * @param playerId
     * 聊天的协议要按照客户端去下发不同的协议 如果客户端大于4.4的话，需要下发协议seg2,过滤掉表情，物品等信息的
     */
    public void write(UWAPSegment seg, UWAPSegment seg2, int playerId){
    	Integer sessionId = (Integer) sessionIds.get(new Integer(playerId));
        WorldPlayer player = playerService.getWorldPlayer(playerId);
        if (player == null){
        	return;
        }else if(player.offlinemode()){
        	 return;
        }            
        if (sessionId != null) {
        	if(player.getClientDataVersion() >= 3){
        		seg2.setSessionId(sessionId.intValue());
                write(seg2);
        	}else{
        		seg.setSessionId(sessionId.intValue());
                write(seg);
        	}
        }
    	
    }
    public void write(UWAPSegment seg) {
        super.write(seg);
//        sendToAdmin(seg);
    }

    private void sendToAdmin(UWAPSegment seg) {
        if (listenedSession.size() == 0)
            return;
        Integer i = (Integer) listenedSession.get(new Integer(seg.getSessionId()));
        if (i != null) {
            adminService.receiveSegment(i.intValue(), seg);
        }
    }

    private void sendToAdmin(UWAPData data) {
        if (listenedSession.size() == 0)
            return;
        Integer i = (Integer) listenedSession.get(new Integer(data.getSessionId()));
        if (i != null) {
            adminService.receiveData(i.intValue(), data);
        }
    }


    public void addListened(int playerId) {
        if (!listened.containsKey(new Integer(playerId))) {
            Integer sessionId = (Integer) sessionIds.get(new Integer(playerId));
            if (sessionId != null) {
                listened.put(new Integer(playerId), NULL);
            } else {
                listened.put(new Integer(playerId), sessionId);
                listenedSession.put(sessionId, new Integer(playerId));
            }
        }
    }

    public void removeListened(int playerId) {
        Object o = listened.get(new Integer(playerId));
        if (o != null) {
            listened.remove(new Integer(playerId));
            listenedSession.remove(o);
        }
    }

    public void checkListened(int playerId, int sessionId) {
        Object o = listened.get(new Integer(playerId));
        if (o != null) {
            if (o == NULL) {
                listened.put(new Integer(playerId), new Integer(sessionId));
                listenedSession.put(new Integer(sessionId),
                                    new Integer(playerId));
            } else {
                listenedSession.remove(o);
                listened.put(new Integer(playerId), new Integer(sessionId));
            }
        }
    }

    public void checkListened(int playerId) {
        Object o = listened.get(new Integer(playerId));
        if (o != null && o != NULL) {
            listenedSession.remove(o);
            listened.put(new Integer(playerId), NULL);
        }
    }

    protected void registry(WorldPlayer player, int sessionId) {
        synchronized (sessionIds) {
            sessionIds.put(new Integer(player.getId()), new Integer(sessionId));
            checkListened(player.getId(), sessionId);
            clients.add(new Integer(player.getId()));
            positionService.registry(player);
            tongService.registry(player);
            friendService.registry(player);
        }
    }


    private void unRegistry(WorldPlayer player) {
        synchronized (sessionIds) {
            sessionIds.remove(new Integer(player.getId()));
            checkListened(player.getId());
            clients.remove(new Integer(player.getId()));
            leaveTeam(player);
            positionService.unRegistry(player);
            tongService.unRegistry(player);
            friendService.unRegistry(player);
//            bufService.unRegistry(player);
        }
    }

