    public void error(ErrorMessage message, SessionRequest rq) {
        if(rq.getType()==RequestType.LOGIN){
            LoginRequest request = (LoginRequest)rq;
            if(request.isReglogin()){
                UWAPSegment seg = new UWAPSegment(ClientConstants.RELOGIN_RESULT, rq.getId(), rq.getSessionId());
                seg.write((byte) 2);
                write(seg);
                return;
            }
        }else if(rq.getType()==RequestType.MODIFY_PASSWORD){
            sendMessage(ErrorMessages.getErrorMesssage(message.getCode()),-1,rq.getSessionId());
        }
        UWAPSegment seg = new UWAPSegment(ClientConstants.ERROR,
                                          rq.getId(), rq.getSessionId());
        
        if(rq instanceof com.pip.accountskeleton.StoreRequest){
        	seg.setSerial(((com.pip.accountskeleton.StoreRequest)rq).getRequest().serial);
        }
        seg.write((byte) 0);
        seg.writeString(ErrorMessages.getErrorMesssage(message.getCode()));
        session.write(seg);

    }
