	                    ibuy.setItemid(request.item.item.getItemId());
	                    ibuy.setItemname(request.item.item.getName());
	                    ibuy.setType((byte)IbuyService.ibuytype_shop);
	                	ibuy.setOtherplayerid(-1);
	                	ibuy.setOtherplayername("");
	                    ibuy.setCount(request.count);
	                    if (cost == -1)
	                    	ibuy.setImoney(request.item.price);
	                    else
	                    	ibuy.setImoney(request.price/100);
	                    Date now = new Date();
	                    ibuy.setBuytime(now);
	                    if (cost > 0){//i币消费
	                    	ibuy.setGiftflag((byte)0);
	                    }else{
	                    	ibuy.setGiftflag((byte)1);
	                    }
	                    ibuy.setLevel(player.getLevel());
	                    ibuyService.addIbuy(ibuy);
	                    
	                    sendGetItem(changed, request.serial, request.sendSessionId, (byte)20);
	                    
	                    ActivityEvent event = new ActivityEvent(ActivityEvent.EVENT_CONSUMER, player.getId(), cost);
                        ActivityServer.server.getEventManager().addEvent(event);
