    //判断是否升级VIP级别 add by zhangxuan
    private boolean isVipLevelUp(WorldPlayer player, Ibuy ibuy) {
    	//changed by zhangxuan
        int oldConsumer = player.getNewActivityConsumer();
        int newConsumer = oldConsumer + ibuy.getImoney();
        player.setNewActivityConsumer(newConsumer);
        
//        //测试数据
//        oldConsumer = 1000;
//        newConsumer = 3600;
        
        if(newConsumer >= VIP1 && oldConsumer < VIP1){
        	player.setVipNewLevel(1);
        	chatService.sendWorldMessage( -1, "系统",
                    player.getPlayerName() + "初现富气，成为幻想的1级VIP。");
        }
        if(newConsumer >= VIP2 && oldConsumer < VIP2){
        	player.setVipNewLevel(2);
        	chatService.sendWorldMessage( -1, "系统",
        			"一掷千金的"+ player.getPlayerName() +"升级成为尊贵的2级VIP。");
        }
        if(newConsumer >= VIP3 && oldConsumer < VIP3){
        	player.setVipNewLevel(3);
        	chatService.sendWorldMessage( -1, "系统",
                    player.getPlayerName() + "仗义疏财，为幻想大陆做成巨大贡献，正式升级成为令人垂涎的3级VIP。");
        }
        if(newConsumer >= VIP4 && oldConsumer < VIP4){
        	player.setVipNewLevel(4);chatService.sendWorldMessage( -1, "系统",
                     "恭喜" + player.getPlayerName() +"成为万众瞩目的4级VIP，不爱名表，名包，钻戒，就爱在幻想中小炫一把富。");
        }
        if(newConsumer >= VIP5 && oldConsumer < VIP5){
        	player.setVipNewLevel(5);
        	chatService.sendWorldMessage( -1, "系统",
                    "天啊，" + player.getPlayerName() + "升级成了世人膜拜的至尊5级VIP，作为GM我只想对你说3个字：“求包养”！");
        }
		return false;
	}
    
