    private int getAddPlayerExp (int day, WorldPlayer player) {
    	BathHouse bathHouse = BathHouse.getBathHouseByMapId((short) 1521);
    	if (day > MAXIMUM) {
    		day = MAXIMUM;
    	}
    	if(player.getLevel() == 100){
    		int tempExp = 500000;
    		return tempExp;
    	}
    	return (BathHouse.EXP[player.getLevel()] * bathHouse.getRatio()) * day / 400;
    }
    
    private int getAddPlayerCredit (int day) {
    	if (day > MAXIMUM) {
    		day = MAXIMUM;
    	}
    	return day * 10;
    }
    
    private void sendRollCall(WorldPlayer player, int serial, int sessionId, int rate){
    	long todayStart = Utils.getTodayStart();
		long lastRollcallTime = player.getLastRollcallCompleteTime().getTime();
		if (lastRollcallTime < todayStart - Utils.MILLS_OF_DAY) {
			Utils.log(log, player.getId(), 0,
					"CampRollcallProcessor playerId[" + player.getId() + " LastRollcallTime[" + player.getLastRollcallCompleteTime()
					+ "] todayStart[" + sf.format(todayStart) + "] RollcallDays[" + player.getRollcallDays() + "] TotalExp["
					+ player.getExp() + "] TotalCredit" + player.getCredit() + " TRY");
			player.setRollcallDays(1);
			player.setLastRollcallCompleteTime(new Date());
			Changed changed = new Changed();
			if (player.getMaxLevel() > player.getLevel()) {
				int exp = getAddPlayerExp(1, player) * rate;
				player.addExp(exp, changed);
			} else {
				int exp = getAddPlayerExp(1, player) * rate;
				player.addExp(exp, changed);
				int credit = getAddPlayerCredit(1) * rate;
				player.addCredit(credit, changed);
			}
			sendGetItem(changed, serial, sessionId, (byte) 17);
			sendMessage("您第1天报到,明天继续报到的话可以获得更多的经验或荣誉(等级100)呦~~", serial, sessionId);
		} else if (lastRollcallTime < todayStart && lastRollcallTime >= todayStart - Utils.MILLS_OF_DAY) {
			boolean mark = false;
			Utils.log(log, player.getId(), 0,
					"CampRollcallProcessor playerId[" + player.getId() + " LastRollcallTime[" + player.getLastRollcallCompleteTime()
					+ "] todayStart[" + sf.format(todayStart) + "] RollcallDays[" + player.getRollcallDays() + "] TotalExp["
					+ player.getExp() + "] TotalCredit" + player.getCredit() + " TRY");
			
			player.setLastRollcallCompleteTime(new Date());
			player.setRollcallDays(player.getRollcallDays() + 1);
			Changed changed = new Changed();
			if (player.getMaxLevel() > player.getLevel()) {
				int exp = getAddPlayerExp(player.getRollcallDays(), player) * rate;
				player.addExp(exp, changed);
			} else {
				int exp = getAddPlayerExp(player.getRollcallDays(), player) * rate;
				player.addExp(exp, changed);
				int credit = getAddPlayerCredit(player.getRollcallDays()) * rate;
				player.addCredit(credit, changed);
			}
			if (player.getRollcallDays() > MAXIMUM && Utils.hit(rnd, 1, 10)) {
				IItem item = Items.getTemplate(ITEM_ID).newInstance();
				IItem nItem = player.completeAddItem(item, 1, changed, player.getClientDataVersion());
				if (nItem == null) {
					IItem iit = Items.getTemplate(item.getItemId()).newInstance();
					byte[] att = ItemUtils.item2dbAttachment(iit, 1);
					mailService.sendMail(player.getId(), player.getPlayerName(), -1, "系统",
							iit.getName() + "*" + 1, "", att, 0, true);
					sendMessage(player.getId(),"你的背包满了，已经把物品邮寄到您的邮箱!");
				}
				mark = true;
			}
			sendGetItem(changed, serial, sessionId, (byte) 17);
			if (player.getRollcallDays() >= MAXIMUM) {
				sendMessage("您已连续报到" + player.getRollcallDays() + "天，明天继续报到的话仍然有几率额外获得一个" + Items.getTemplate(ITEM_ID).newInstance().getName() + "呦~~", serial, sessionId);
			} else {
				sendMessage("您已连续报到" + player.getRollcallDays() + "天，明天继续报到的话可以获得更多的经验或荣誉(等级100)呦~~", serial, sessionId);
			}
			if (mark) {
				chatService.sendWorldMessage(player.getId(), "系统", "恭喜“" + player.getPlayerName() + "”通过阵营膜拜领袖活动获得了" + Utils.itemIdToProtocolName(ITEM_ID) + "！" + Utils.itemIdToProtocol(ITEM_ID));
			}
			Utils.log(log, player.getId(), 0,
					"CampRollcallProcessor playerId[" + player.getId() + " LastRollcallTime[" + player.getLastRollcallCompleteTime()
					+ "] todayStart[" + sf.format(todayStart) + "] RollcallDays[" + player.getRollcallDays() + "] TotalExp["
					+ player.getExp() + "] TotalCredit" + player.getCredit() + "] Success!");
            
		} else {
			sendMessage("点名册上已经有您了，请明天再来吧。", serial, sessionId);
		}
    }
    
    public static final byte SHOWPAO_MAIL = 1;
    // 任务相关的要求
       public void taskRequest(WorldPlayer player, short taskID, boolean endRequest) throws Exception {
   		if (player != null) {
//   			synchronized (player) {
   				TaskRequest request = TaskRequestData.endTaskRequest(taskID);
   				if(request != null){
   					switch(request.getType()){
   					case TaskRequest.TYPE_MAILITEM:		//通过邮件发装备给玩家
   						//发一封信后 如果设置了需要显示新信件泡泡时
   						if(request.isMailNew()){
   							UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL);
   							seg.writeShort(ClientConstants.EXTEND_SHOWPAO);
   							seg.write(SHOWPAO_MAIL);
   							seg.writeString(request.getMailNewText());
   							write(seg, player.getId());
   						}
   						//需要发送打开邮件UI
   						if(request.isMailOpenUI()){
   							UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL);
   							seg.writeShort(ClientConstants.EXTEND_OPEN_UI);
   							seg.writeString("ui_quickmail");
   							seg.writeInt(1);
   							seg.writeString("NewMailOpen");
   							write(seg, player.getId());
   						}
   						if(request.getMailItemId() < 0 || request.getMailItemCount() == 0){
   						}else{
   							IItem iit = Items.getTemplate(request.getMailItemId()).newInstance();
   							byte[] att = ItemUtils.item2dbAttachment(iit, request.getMailItemCount());
   							mailService.sendMail(player.getId(), player.getPlayerName(), -1, "系统", 
   									request.getMailTitle(), request.getMailContext(), att, 0, true);
   						}
   						break;
   					}
   				}
//   			}
   		}
       }
    
    public void lyricsSystem(UWAPData data) throws Exception {
    	byte type = data.readByte();
    	WorldPlayer player = getPlayer(data.getSessionId());
        if (player != null) {
        	switch(type){
        	case LyricsSystemConfig.LYRIC_GETTYPE:		//获取歌曲类型
        		String[] lyricTypeName = LyricsSystemConfig.getTypes();
        		UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
        		seg.writeShort(ClientConstants.EXTEND_LYRIC);
        		seg.write(type);
        		if(lyricTypeName == null || lyricTypeName.length == 0){
        			seg.writeInt(0);
        		}else{
        			seg.writeInt(lyricTypeName.length);
        			seg.writeStrings(lyricTypeName);
        		}
        		IStoreItem item = IStoreGroups.getStoreItem(LyricsSystemConfig.LYRIC_SING_ITEMID);
        		if(item != null){
        			seg.writeInt(item.price);
        		}else{
        			seg.writeInt(0);
        		}
        		item = IStoreGroups.getStoreItem(LyricsSystemConfig.LYRIC_SING_ITEMID2);
        		if(item != null){
        			seg.writeInt(item.price);
        		}else{
        			seg.writeInt(0);
        		}
        		write(seg);
        		break;
        	case LyricsSystemConfig.LYRIC_GETLYRICS:	//获取歌曲列表
        		String lyricType = data.readString();
        		ArrayList<LyricData> lyrics = LyricsSystemConfig.getTypeLyrics(lyricType);
        		if(lyrics == null){
        			throw new ITimesException("找不到指定的类型的歌曲", data.getSerial(), data.getSessionId(), data.getAppType());
        		}
        		seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
        		seg.writeShort(ClientConstants.EXTEND_LYRIC);
        		seg.write(type);
        		seg.writeInt(lyrics.size());
        		for(int i=0; i<lyrics.size(); i++){
        			LyricData ld = lyrics.get(i);
        			seg.writeString(ld.getName());
        			seg.writeString(ld.getSinger());
        		}
        		write(seg);
        		break;
        	case LyricsSystemConfig.LYRIC_SING:		//点歌
        		lyricType = data.readString();		//类型
        		int lyricIndex = data.readInt();		//歌曲位置
        		String blessings = data.readString();	//祝福语
        		int destServerId = data.readInt();	//目标服务器的ID 如果只是本服点歌 则为-1
        		String destPlayerName = data.readString();	//目标角色名称
        		LyricData ld = LyricsSystemConfig.getLyric(lyricType, lyricIndex);
        		if(ld == null){
        			throw new ITimesException("找不到指定的歌曲", data.getSerial(), data.getSessionId(), data.getAppType());
        		}
//        		if(Server.iMoneyType == Server.IMONEY_TYPE_CMCC){
//        			throw new ITimesException("此功能还没开放，敬请期待", data.getSerial(), data.getSessionId(), data.getAppType());
//        		}
        		LyricDataServer lds = new LyricDataServer();
        		lds.setLyricData(ld);
        		lds.setBlessings(blessings);
        		lds.setDestPlayerName(destPlayerName);
        		lds.setDestServerId(destServerId);
        		lds.setSrcPlayerName(player.getPlayerName());
        		
        		int itemid = destServerId >= 0 ? LyricsSystemConfig.LYRIC_SING_ITEMID2 : LyricsSystemConfig.LYRIC_SING_ITEMID;
        		if(player.hasItem(itemid)){
        			Changed changed = new Changed();
        			IItem itemtmp = player.completeRemoveItem(itemid, 1, changed);
        			if(itemtmp != null){
	            		Server.instance.arenaSession.addLyric(lds.getLyricData(), lds.getBlessings(), player.getPlayerName(), lds.getDestServerId(), lds.getDestPlayerName());
	            		sendMessage("您已经点播成功。", data.getSerial(), data.getSessionId());
	            		sendGetItem(changed, data.getSerial(), data.getSessionId(), data.getAppType());
        			}else{
        				sendMessage("扣除物品出错。", data.getSerial(), data.getSessionId());
        			}
        		}else{
        			LyricsSystemConfig.addSing(player.getId(), lds);
	        		if(iShopHide(player, itemid, data.getSerial(), data.getSessionId(), 1, (byte)2, -1, 0, true, false) != ISHOP_OK){
	        			sendMessage("您的" + Server.iMoneyString + "不足，请充值后再点歌", data.getSerial(), data.getSessionId());
	        		}else{
	        			sendMessage("您已经点播成功。", data.getSerial(), data.getSessionId());
	        		}
        		}
//        		Server.instance.arenaSession.addLyric(ld, blessings, player.getPlayerName(), destServerId, destPlayerName);
        		seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
        		seg.writeShort(ClientConstants.EXTEND_LYRIC);
        		seg.write(type);
        		write(seg);
        		break;
        	case LyricsSystemConfig.LYRIC_GETSERVERS:	//获取服务器列表 这里需要等待跨服服务器发送服务器信息
        		Server.instance.arenaSession.getServers(player.getId(), data.getSerial());
        		//收到的服务器信息为字符串数组 格式为:服务器ID 服务器名称
        		break;
        	}
        }
    }
    
    private void loveSend(UWAPData data) throws Exception {
    	//要发公告的物品ID
    	final int WorldMessageItemID1 = 200611;
    	final int WorldMessageItemID2 = 200752;
    	byte type = data.readByte();
    	WorldPlayer player = getPlayer(data.getSessionId());
    	if(player != null){
    		int itemid = data.readInt();
    		int sendplayerid = data.readInt();
    		if(player.hasItem(itemid)){
    			synchronized (player) {
    				IEffectItem item = (IEffectItem)player.getItem(itemid, 0).item;
    				Effect[] effects = item.getEffects();
    				if(effects == null || effects.length == 0 || effects.length > 1){
    					throw new ITimesException("物品错误！",data.getSerial(),data.getSessionId(),data.getAppType());
    				}
    				if(effects[0].getType() != 82){
    					throw new ITimesException("物品错误！",data.getSerial(),data.getSessionId(),data.getAppType());
    				}
    				Love7Effect loveSendGift = (Love7Effect)effects[0];
    				WorldPlayer friend = playerService.getWorldPlayer(sendplayerid);
    				if(friend == null || !friend.online()){
    					throw new ITimesException("好友不在线！",data.getSerial(),data.getSessionId(),data.getAppType());
    				}
    				Changed changed = new Changed();
    				DropGroup group = DropGroups.getDropGroup(loveSendGift.getGroupID(), player.getLevel());
    				if(group == null){
    					throw new ITimesException("物品出错！",data.getSerial(),data.getSessionId(),data.getAppType());
    				}
    				int rate = rnd.nextInt(group.getRate());
    				DropItem dropItem = group.calcDropItem(rate);
    				int count = getCount(rnd, dropItem.getMin(), dropItem.getMax());
    				int itemCount = player.getItemCount(dropItem.getItem().getItemId());
    				boolean isFull = false;
    				if(itemCount > 0 && player.isFull() && itemCount + count < 100 && dropItem.getItem().getType() != IItem.TYPE_EQU){
    				}else if(player.isFull() || itemCount + count > 99){
    					isFull = true;
    				}
    				if(isFull){
    					byte[] att = ItemUtils.item2dbAttachment(dropItem.getItem().newInstance(), count);
    					mailService.sendMail(player.getId(), player.getPlayerName(), -1, "系统", dropItem.getItem().getName() + "*" + count, "情人节礼品", att, 0, true);
    					if(itemCount + count > 99){
    						sendMessage("您的物品个数已达上限，奖励物品已经发送到邮箱，请及时查收。", data.getSerial(), data.getSessionId());
    					}else{
    						sendMessage("您的背包已满，奖励物品已经发送到邮箱，请及时查收。", data.getSerial(), data.getSessionId());
    					}
    				}else{
    					player.addItem(dropItem.getItem(), count, changed, player.getClientDataVersion());
    				}
    				StringBuilder sb = new StringBuilder();
    				int dropItemId = dropItem.getItem().getItemId();
    				if(dropItemId == WorldMessageItemID1 || dropItemId == WorldMessageItemID2){
    					sb.delete(0, sb.length());
    					sb.append("“");
    					sb.append(player.getPlayerName());
    					sb.append("”从“");
    					sb.append(item.getName());
    					sb.append("”中发现了一颗“");
    					sb.append(Utils.itemIdToProtocolName(dropItem.getItem().getItemId()));
    					sb.append("”。 ");
    					sb.append(Utils.itemIdToProtocol(dropItem.getItem().getItemId()));
    					chatService.sendWorldMessage(-1, "系统", sb.toString());
    				}
    				player.completeRemoveItem(itemid, 1, changed);
    				sendGetItem(changed, data.getSerial(), data.getSessionId(), data.getAppType());
    				log.info("ID[" + player.getId() + "]Love7Item[" + dropItem.getItem().getItemId() + "]Count[" + count + "]");
    				
    				Changed changed2 = new Changed();
    				group = DropGroups.getDropGroup(loveSendGift.getGroupID(), friend.getLevel());
    				if(group == null){
    					throw new ITimesException("物品出错！",data.getSerial(),data.getSessionId(),data.getAppType());
    				}
    				rate = rnd.nextInt(group.getRate());
    				dropItem = group.calcDropItem(rate);
    				count = getCount(rnd, dropItem.getMin(), dropItem.getMax());
    				itemCount = friend.getItemCount(dropItem.getItem().getItemId());
    				isFull = false;
    				if(itemCount > 0 && friend.isFull() && itemCount + count < 100 && dropItem.getItem().getType() != IItem.TYPE_EQU){
    					isFull = false;
    				}else if(friend.isFull() || itemCount + count > 99){
    					isFull = true;
    				}
    				if(isFull){
    					byte[] att = ItemUtils.item2dbAttachment(dropItem.getItem().newInstance(), count);
    					mailService.sendMail(friend.getId(), friend.getPlayerName(), -1, "系统", dropItem.getItem().getName() + "*" + count, "情人节礼品", att, 0, true);
    				}else{
    					friend.addItem(dropItem.getItem(), count, changed2, friend.getClientDataVersion());
    				}
    				sb.delete(0, sb.length());
    				sb.append("<cff0000>");
    				sb.append(player.getPlayerName());
    				sb.append("</c>对你使用了<cff0000>");
    				sb.append(item.getName());
    				sb.append("</c>，你得到了<cff0000>");
    				sb.append(dropItem.getItem().getName());
    				sb.append("</c>");
    				if(isFull){
    					sb.append("不过您的背包已满或物品个数已达上限，奖励物品已经发送到邮箱，请及时查收。");
    				}
    				sendMessage(friend.getId(), sb.toString());
    				connectService.sendGetItem(changed2, friend.getId(), data.getAppType());
    				dropItemId = dropItem.getItem().getItemId();
    				if(dropItemId == WorldMessageItemID1 || dropItemId == WorldMessageItemID2){
    					sb.delete(0, sb.length());
    					sb.append("“");
    					sb.append(friend.getPlayerName());
    					sb.append("”从“");
    					sb.append(player.getPlayerName());
    					sb.append("”送的“");
    					sb.append(item.getName());
    					sb.append("”中发现了一颗“");
    					sb.append(Utils.itemIdToProtocolName(dropItem.getItem().getItemId()));
    					sb.append("”。 ");
    					sb.append(Utils.itemIdToProtocol(dropItem.getItem().getItemId()));
    					chatService.sendWorldMessage(-1, "系统", sb.toString());
    				}
    				log.info("ID[" + friend.getId() + "]Love7Item[" + dropItem.getItem().getItemId() + "]Count[" + count + "]");
    				byte loveType = Love7Config.TYPE_BOY2GIRL;
    				int friendsex = friend.getSex();
    				int mysex = player.getSex();
    				if(friendsex == mysex){
    					if(mysex == Utils.SEX_BOY){
    						loveType = Love7Config.TYPE_BOY2BOY;
    					}else{
    						loveType = Love7Config.TYPE_GIRL2GIRL;
    					}
    				}else{
    					if(mysex == Utils.SEX_GIRL){
    						loveType = Love7Config.TYPE_GIRL2BOY;
    					}
    				}
    				String sendLoveChat = Love7Config.getChat(loveType, player.getPlayerName(), friend.getPlayerName());
    				if(sendLoveChat != null){
    					chatService.sendWorldMessage(-1, "系统",sendLoveChat);
    				}
    				UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
    				seg.writeShort(ClientConstants.EXTEND_SENDFRIEND);
    				write(seg);
				}
    		}else{
				sendMessage("您没有该物品。", data.getSerial(), data.getSessionId());
				throw new ITimesException("物品错误！",data.getSerial(),data.getSessionId(),data.getAppType());
    		}
    	}
    }
    
    private void sendFarm(UWAPData data) throws Exception {
    	byte type = data.readByte();
    	WorldPlayer player = getPlayer(data.getSessionId());
    	if(player != null){
    		switch(type){
    		case 1:	//传送到指定玩家的庄园
    			String destPlayerName = data.readString();
    			WorldPlayer destPlayer = playerService.getWorldPlayerAndCatch(destPlayerName);
    			if(destPlayer == null){
    				throw new ITimesException("没有找到玩家！", data.getSerial(), data.getSessionId(), data.getAppType());
    			}
    			try{
	    			FarmInstance farmInstance = farmInstanceModel.preTry(player, destPlayer.getId());
	    			FarmInstance fi = farmInstanceModel.tryGotoInstance(farmInstance.getId(), player, 0);
	    			if(fi != null){
		    			InstanceDefinition idf = farmInstance.getDefinition();
		                sendGotoMap(player.getId(), idf.getMap(), idf.getX(), idf.getY());
	    			}
    			}catch(Exception e){
    				throw new ITimesException(e.getMessage(), data.getSerial(), data.getSessionId(), data.getAppType());
    			}finally{
    				playerService.releasePlayer(destPlayer);
    			}
    			break;
    		}
    	}
    }
    
    private void RawStoneReplace(UWAPData data) throws Exception{
    	int itemid = data.readInt();
    	int count = data.readInt();
    	boolean flag = data.readBoolean();
    	WorldPlayer player = getPlayer(data.getSessionId());
    	if(player != null){
    		int needitemid = 201454;//宝石力量碎片
    		int giveitemid = 201455;//四级宝石随机包
    		int removeitemcount = 5;//需删除原石数
    		int needitemcount = 10;//需删除力量碎片数
    		Changed changed = new Changed();
    		if(!player.hasItem(needitemid)){
    			throw new ITimesException("您没有宝石力量碎片，无法兑换",
    					data.getSerial(),data.getSessionId(),data.getAppType());
    		}
    		if(player.getItemCount(needitemid) < needitemcount){
    			throw new ITimesException("您的宝石力量碎片数量不够",
    					data.getSerial(),data.getSessionId(),data.getAppType());
    		}
    		synchronized (player) {
    				if(flag == false){
	    				if(player.hasItem(giveitemid) && player.getItemCount(giveitemid) < 99){
	    					player.addItem(giveitemid, 1, changed,
	    							player.getClientDataVersion());
	    					player.completeRemoveItem(itemid, removeitemcount, changed);//删原石
	    					player.completeRemoveItem(needitemid, needitemcount, changed);//删碎片
	    				}else if(!player.isFull() && !player.hasItem(giveitemid)){
	    					player.addItem(giveitemid, 1, changed,
	    							player.getClientDataVersion());
	    					player.completeRemoveItem(itemid, removeitemcount, changed);//删原石
	    					player.completeRemoveItem(needitemid, needitemcount, changed);//删碎片
	    				}else{
	    					IItem iit = Items.getTemplate(giveitemid).newInstance();
	    					byte[] att = ItemUtils.item2dbAttachment(iit,1);
	    					mailService.sendMail(player.getId(),
	    							player.getPlayerName(), -1, "系统",
	    							iit.getName() + "*" + 1, "原石兑换物品", att, 0,
	    							true);
	    					player.completeRemoveItem(itemid, removeitemcount, changed);//删原石
	    					player.completeRemoveItem(needitemid, needitemcount, changed);//删碎片
	    					sendMessage(player.getId(),
	    					"你的背包满了，已经把物品邮寄到您的邮箱!已经扣除需要交换的物品");
	    				}
	    				if(changed != null){
	    					sendGetItem(changed, data.getSerial(), data.getSessionId(), data.getAppType());
	    					sendMessage(player.getId(), "兑换成功!已经扣除需要交换的物品");
	    					log.info("RawStoneReplace ID[" + player.getId() + "] giveitemid[" + giveitemid + "] removeItemID[" 
	    							+ itemid + "] removeneeditemid[" + needitemid + "] removeItemcount[" 
	    							+ count + "] removeneeditemcount[" + needitemcount +"]");
	    				}
	    			
    				}else{//全部兑换
    					int itemcount = player.getItemCount(itemid);//背包原石数量
    					int needcount = player.getItemCount(needitemid);//力量碎片数
    					int cangivecount = 0;
    					int delitemcount = 0;
    					int delneedcount = 0;
    					int stonecount = itemcount / removeitemcount;
    					int chipcount = needcount / needitemcount;
    					//给随机包数量
    					if(stonecount < chipcount){
    						cangivecount = stonecount;
    					}else if(chipcount < stonecount){
    						cangivecount = chipcount;
    					}else{
    						cangivecount = 1;
    					}
    					//删两种物品数量
    					delitemcount = removeitemcount * cangivecount;
    					delneedcount = needitemcount * cangivecount;
    					
    					if(player.hasItem(giveitemid) && player.getItemCount(giveitemid) < 99){
    						player.completeRemoveItem(itemid, delitemcount, changed);//删原石
	    					player.completeRemoveItem(needitemid, delneedcount, changed);//删碎片
    						player.addItem(giveitemid, cangivecount, changed,
	    							player.getClientDataVersion());
						}else if(!player.isFull() && !player.hasItem(giveitemid)){
							player.completeRemoveItem(itemid, delitemcount, changed);//删原石
	    					player.completeRemoveItem(needitemid, delneedcount, changed);//删碎片
    						player.addItem(giveitemid, cangivecount, changed,
	    							player.getClientDataVersion());
						}else{
							IItem iit = Items.getTemplate(giveitemid).newInstance();
	    					byte[] att = ItemUtils.item2dbAttachment(iit,cangivecount);
	    					mailService.sendMail(player.getId(),
	    							player.getPlayerName(), -1, "系统",
	    							iit.getName() + "*" + cangivecount, "原石兑换物品 ", att, 0,
	    							true);
	    					player.completeRemoveItem(itemid, delitemcount, changed);//删原石
	    					player.completeRemoveItem(needitemid, delneedcount, changed);//删碎片
	    					sendMessage(player.getId(),
	    					"你的背包满了，已经把物品邮寄到您的邮箱!已经扣除需要交换的物品");
	    					return;
						}
    					if(changed != null){
    						sendGetItem(changed, data.getSerial(), data.getSessionId(), data.getAppType());
	    					sendMessage(player.getId(), "兑换成功!已经扣除需要交换的物品");
	    					log.info("RawStoneReplace ID[" + player.getId() + "] giveitemid[" + giveitemid + "] removeItemID[" 
	    							+ itemid + "] removeneeditemid[" + needitemid + "] removeItemcount[" 
	    							+ delitemcount + "] removeneeditemcount[" + delneedcount +"] givecount[" + cangivecount +"]");
    					}
    				
    				}
    			}		
    				UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, 
    						data.getSerial(), data.getSessionId());
					seg.writeShort(ClientConstants.EXTEND_RAWSTONEREPLACE);
					write(seg);
    		}
    	
    }
    
    
    private void DiamondReplace(UWAPData data) throws Exception{
    	int type = data.readInt();
    	int itemid = data.readInt();
    	int quality = data.readInt();
    	int count = data.readInt();
    	WorldPlayer player = getPlayer(data.getSessionId());
    	int fourdiamondId = 201502; //四级宝石兑换券
    	int fivediamondId = 201503;	//五级
    	int sixdiamondId = 201504;	//六级
    	int []singelPrice = new int[3];
    	Changed ch = new Changed();
    	if(player != null){
    		synchronized (player) {
	    		if(type == 1){	//确认信息
	    			String msg = "";
	    			if(quality == 1){
	    				//IItemTemplate item = Items.getTemplate(fourdiamondId);
	    				singelPrice = getIshopEasyPrice(player, fourdiamondId, count);
	    				msg = "置换宝石需消耗" + singelPrice[2] * count +"i，置换后可以获得同等级的宝石";
	    			}else if(quality == 2){
	    				singelPrice = getIshopEasyPrice(player, fivediamondId, count);
	    				//IItemTemplate item = Items.getTemplate(fivediamondId);
	    				msg = "置换宝石需消耗" + singelPrice[2] * count +"i，置换后可以获得同等级的宝石";
	    			}else if(quality == 3){
	    				singelPrice = getIshopEasyPrice(player, sixdiamondId, count);
	    				//IItemTemplate item = Items.getTemplate(sixdiamondId);
	    				msg = "置换宝石需消耗" + singelPrice[2] * count +"i，置换后可以获得同等级的宝石";
	    			}
	    			UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
	    			seg.writeShort(ClientConstants.EXTEND_DIAMONDREPLACE);
	    			seg.writeInt(type);
	    			seg.writeString(msg);
	    			write(seg);
	    		}else if(type == 2){	//购买兑换券兑换
	    			log.info("DiamondReplace ID[" + player.getId() + "] quality[" + quality + "] count[" + count + "] try");
	    			if(!player.hasItem(itemid, count)){
	    				log.info("DiamondReplace ID[" + player.getId() + "] quality[" + quality + "] count[" + count + "] no item");
						throw new ITimesException("没有足够的宝石!",data.getSerial(),data.getSessionId(),data.getAppType());
	    			}
	    			if(quality == 1){
	    				int calltype = iShopHide(player, fourdiamondId, data.getSerial(), data.getSessionId(), count, (byte)4, itemid, count);
	    				if(calltype == ISHOP_NOIMONEY){
							//sendMessage("您的" + Server.iMoneyString + "不足。", data.getSerial(), data.getSessionId());
	    					throw new ITimesException("您的" + Server.iMoneyString + "不足。",data.getSerial(),data.getSessionId(),data.getAppType());
	    				}else if(calltype == ISHOP_OK){
	    					player.completeRemoveItem(itemid, count, ch);
	    					sendGetItem(ch, data.getSerial(), data.getSessionId(), (byte)20);
	    					log.info("DiamondReplace ID[" + player.getId() + "] quality[" + quality + "] count[" + count + "] removeItemID[" + itemid + "]");
	    				}
	    			}else if(quality == 2){
	    				int calltype = iShopHide(player, fivediamondId, data.getSerial(), data.getSessionId(), count, (byte)4, itemid, count);
	    				if(calltype == ISHOP_NOIMONEY){
							//sendMessage("您的" + Server.iMoneyString + "不足。", data.getSerial(), data.getSessionId());
	    					throw new ITimesException("您的" + Server.iMoneyString + "不足。",data.getSerial(),data.getSessionId(),data.getAppType());
	    				}else if(calltype == ISHOP_OK){
	    					player.completeRemoveItem(itemid, count, ch);
	    					sendGetItem(ch, data.getSerial(), data.getSessionId(), (byte)20);
	    					log.info("DiamondReplace ID[" + player.getId() + "] quality[" + quality + "] count[" + count + "] removeItemID[" + itemid + "]");
	    				}
	    			}else if(quality == 3){
	    				int calltype = iShopHide(player, sixdiamondId, data.getSerial(), data.getSessionId(), count, (byte)4, itemid, count);
	    				if(calltype == ISHOP_NOIMONEY){
							//sendMessage("您的" + Server.iMoneyString + "不足。", data.getSerial(), data.getSessionId());
	    					throw new ITimesException("您的" + Server.iMoneyString + "不足。",data.getSerial(),data.getSessionId(),data.getAppType());
	    				}else if(calltype == ISHOP_OK){
	    					player.completeRemoveItem(itemid, count, ch);
	    					sendGetItem(ch, data.getSerial(), data.getSessionId(), (byte)20);
	    					log.info("DiamondReplace ID[" + player.getId() + "] quality[" + quality + "] count[" + count + "] removeItemID[" + itemid + "]");
	    				}
	    			}
	    			UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
	    			seg.writeShort(ClientConstants.EXTEND_DIAMONDREPLACE);
	    			seg.writeInt(type);
	    			write(seg);
	    		}
    		}
    	}
    	
    }
    
