    //圣宠技能
    private void petEvolutionSkill(UWAPData data) throws Exception{
    	UWAPSegment seg = new UWAPSegment(ClientConstants.EXTEND_PROTOCOL, data.getSerial(), data.getSessionId());
		seg.writeShort(ClientConstants.EXTEND_PET_SKILL);
    	WorldPlayer player = getPlayer(data.getSessionId());
  
    	Short whichIndex = data.readShort();
      	int petId = data.readInt();
    	short[] petSaintSkill = new short[1];
    	seg.writeShort(whichIndex);
    	if (player != null) {
    		synchronized (player) {
    			Pet pet = player.getPet(petId);
    			if(whichIndex == 2){
    				if(pet.getEvolutionLevel() < 4){
    					throw new ITimesException("宠物不是圣宠！", data.getSerial(),
                                data.getSessionId(),
                                data.getAppType());
    				}
    				int itemCount = player.getItemCount(201023);
    	    		if(itemCount > 0){
    	    			//移除一个物品
    					Changed change = new Changed();
    					if(player.completeRemoveItem(201023, 1, change) != null){
    						log.info("ID[" + player.getId() + "] saint Pet[" + Utils.getHexdump(pet.toBytes_log())
        	        				+  "Rebirth FAILURE!Remove reLiveSeeds Failure");
	    		    		seg.write((byte)4);		//技能已经成功重生了。
	    		    		sendGetItem(change, data.getSerial(), data.getSessionId(), (byte)73);
	    		    		Ability[] abilityCommon  = pet.getAbilities();
	    		    		AbilityData[] abilityCommondata  = pet.getAbilitiesData();
	    		    		boolean isSaint = false;
	    		    		for(int k = 0;k< abilityCommon.length;k++){
	        					if(abilityCommondata[k].getIsSaint() == 1){
	        						isSaint = true;
	        						break;
	        					}
	    		    		}
	    		    		if(isSaint){
	    		    			pet.removeAbilitySaint();
	    		    		}
	        				abilityCommon =  pet.getAbilities();
	    					int abiliyCommonId[] = new int[abilityCommon.length];
	    					for(int i = 0; i < abilityCommon.length ;i++){
	    						abiliyCommonId[i] = abilityCommon[i].getId();
	    					}
	    					Ability[] newAbilities = pet.addEvoAbilities(abiliyCommonId);
	    					petSaintSkill = new short[newAbilities.length];
	    					for(int i=0; i<petSaintSkill.length; i++){
	    						petSaintSkill[i] = (short)newAbilities[i].getId();
	    					}
	    					log.info("ID[" + player.getId() + "] Saint Pet[" + Utils.getHexdump(pet.toBytes_log())
	    		    				+ "] Rebirth SUCCESS");
    					}
    	    		}else{
    	    			seg.write((byte)3);		//你没有足够的重生宝典
    	    			log.info("ID[" + player.getId() + "] saint Pet[" + Utils.getHexdump(pet.toBytes_log())
    	        				+  "Rebirth FAILURE!Do not have enough reLiveSeeds");
    	    		}
    			}
    			seg.writeShorts(petSaintSkill);
    			write(seg);    
    		}
    	}
    }
    
